window.HADITH_DATA['ahmad'][92]=[[18201,18201,"","আমার বাবা ছিলেন সবচেয়ে দুর্বল প্রেমিক । আমি তার কানে আর কখনো তার কাছে আসতে পারিনি। লর্ড তার কাছে প্রার্থনা করে বলল, সে কি বলবে যখন আমাকে স্পর্শ করেছিল এবং যখন সে আমাকে আঘাত করেছিল, এবং আল্লাহ্‌র কাছে প্রার্থনা করেছিল। আর সে তার প্রার্থনা করেছিল। আর সে তার জন্য প্রার্থনা করেছিল। আর সে তার কাছে প্রার্থনা করেছিল, যেন আমি তাকে সাহায্য করি। আর আমি আমার জীবনের জন্য প্রার্থনা করি। আমি জানি, আমি জানি, আমি জানি, আমি তোমার কাছে ক্ষমা চাই। আর আমি তোমার জন্য প্রার্থনা করি, তুমি আমার মনের কথা বলছি, তুমি জানো না। আর তুমি জানো, তুমি জানো, তুমি তোমার জন্য আমার কাছে এটা একটা ছোট্ট জীবন বেছে নাও। আর তুমি আমাকে তোমার জন্য। তোমার জন্য। তোমার জন্য, তোমার জীবন কত বড়ই না। তোমার জন্য। তোমার জন্য, তোমার জীবন কত বড়ই না তুমি তোমার জন্য। তোমার জন্য এটা একটা বড় কথা। আর তুমি তোমার জন্য। আর তুমি তোমার জন্য এটা একটা প্রশ্ন করো। আর তুমি তোমার জন্য এটা একটা প্রশ্ন করো। আর তুমি তোমার জন্য, তোমার জন্য, তোমার জন্য। তোমার জন্য, তোমার জন্য। আর তোমার বাবা-মাকে ধন্যবাদ। আর তোমার বাবা-মাদের সাথে আছে। আর আমি যখন তুমি তোমার কাছে এটা আমার কাছে এটা একটা প্রশ্ন করি। আর তোমার জন্য। আর তোমার জন্য। জন্ম তিনবার দেওয়া হয়েছে যদি তাকে সত্যি সত্যি সত্যি প্রকাশ করতে হয়।","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي عَقِيلٍ هَاشِمِ بْنِ بِلَالٍ ‏ ‏عَنْ ‏ ‏سَابِقِ بْنِ نَاجِيَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَلَّامٍ ‏ ‏قَالَ ‏ ‏أَبُو النَّضْرِ ‏ ‏الْحَبَشِيُّ ‏ ‏قَالَ ‏ ‏مَرَّ بِهِ رَجُلٌ فِي مَسْجِدِ ‏ ‏حِمْصَ ‏ ‏فَقِيلَ هَذَا ‏ ‏خَدَمَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَامَ إِلَيْهِ فَقَالَ حَدِّثْنِي حَدِيثًا سَمِعْتَهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمْ يَتَدَاوَلْهُ بَيْنَكَ وَبَيْنَهُ الرِّجَالُ قَالَ سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَا مِنْ عَبْدٍ يَقُولُ حِينَ يُمْسِي وَحِينَ يُصْبِحُ رَضِيتُ بِاللَّهِ رَبًّا وَبِالْإِسْلَامِ دِينًا ‏ ‏وَبِمُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَبِيًّا ثَلَاثَ مَرَّاتٍ إِلَّا كَانَ حَقًّا عَلَى اللَّهِ أَنْ يُرْضِيَهُ ‏","","",""],[18202,18202,"","আমরা দু-টি ঘোড়াকে অভিবাদন জানানোর চেষ্টা করেছি, যা আমরা করেছি তার চেয়ে ভাল হয়েছে। কাপুরুষের ভালো তিনি এমন একজনের সাথে কথা বলেছিলেন যিনি লর্ডের সেবা করতেন আর তারপর আত্মসমর্পণ করতেন। সে শীঘ্রই তার কাছে পৌঁছে যাবে... ...যদি সে তার সেবাকে উড়িয়ে দেয়... ...সে লর্ড বলে ডাকে, তুমি ঘোড়াটাকে আমি যা দিয়েছি তা ধরে রাখার চেষ্টা করেছ.","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ غَيْلَانَ ‏ ‏حَدَّثَنَا ‏ ‏رِشْدِينُ بْنُ سَعْدٍ ‏ ‏حَدَّثَنَا ‏ ‏بَكْرُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ هُبَيْرَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ جُبَيْرٍ ‏ ‏أَنَّهُ حَدَّثَهُ ‏ ‏رَجُلٌ خَدَمَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَمَانِ سِنِينَ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا قُرِّبَ لَهُ طَعَامٌ قَالَ بِسْمِ اللَّهِ فَإِذَا فَرَغَ مِنْ طَعَامِهِ قَالَ ‏ ‏اللَّهُمَّ أَطْعَمْتَ وَأَسْقَيْتَ وَأَغْنَيْتَ وَأَقْنَيْتَ وَهَدَيْتَ ‏ ‏وَاجْتَبَيْتَ ‏ ‏فَلَكَ الْحَمْدُ عَلَى مَا أَعْطَيْتَ ‏","","",""],[18203,18203,"","আমরা একে অপরের কথা বলেছি, কিন্তু আমি একজন দেবীর পুত্র জয় করতে পেরে খুশি। সে রাতে তার কিছু চাহিদার জন্য ছেড়ে দেবে। সে বলল, সে নাকি আমার হাত ধরে ঈশ্বরের কাছে নিয়ে গেছে। তার জন্য প্রার্থনা করুন এবং তিনি আমার অতিথি হতে হবে তিনি বলেন আপনি এই অগ্নি বিভাগ মধ্যে এটি না হবে এবং তারপর একটি রাতের জন্য বাইরে গিয়েছিলাম এবং আমরা তাকে পাহারা দেবার জন্য আমি দেখলাম, সে হয়তো সেই রকমই একজন।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنِ ‏ ‏ابْنِ الْأَدْرَعِ ‏ ‏قَالَ ‏ ‏كُنْتُ أَحْرُسُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ لَيْلَةٍ فَخَرَجَ لِبَعْضِ حَاجَتِهِ قَالَ فَرَآنِي فَأَخَذَ بِيَدِي فَانْطَلَقْنَا فَمَرَرْنَا عَلَى رَجُلٍ ‏ ‏يُصَلِّي يَجْهَرُ بِالْقُرْآنِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَسَى أَنْ يَكُونَ ‏ ‏مُرَائِيًا ‏ ‏قَالَ قُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏يُصَلِّي يَجْهَرُ بِالْقُرْآنِ قَالَ فَرَفَضَ يَدِي ثُمَّ قَالَ إِنَّكُمْ لَنْ تَنَالُوا هَذَا الْأَمْرَ ‏ ‏بِالْمُغَالَبَةِ ‏ ‏قَالَ ثُمَّ خَرَجَ ذَاتَ لَيْلَةٍ وَأَنَا أَحْرُسُهُ لِبَعْضِ حَاجَتِهِ فَأَخَذَ بِيَدِي فَمَرَرْنَا عَلَى رَجُلٍ ‏ ‏يُصَلِّي بِالْقُرْآنِ قَالَ فَقُلْتُ عَسَى أَنْ يَكُونَ ‏ ‏مُرَائِيًا ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَلَّا إِنَّهُ ‏ ‏أَوَّابٌ ‏ ‏قَالَ فَنَظَرْتُ فَإِذَا هُوَ ‏ ‏عَبْدُ اللَّهِ ذُو الْبِجَادَيْنِ ‏","","",""],[18204,18204,"","আমরা তোমাকে অন্ধ চোখ থাকার পর তোমাকে বলেছিলাম যে ঈশ্বর তার জন্য প্রার্থনা করেছেন আর ঈশ্বরের প্রতি ভালোবাসার আতঙ্কের জন্য আত্মসমর্পণ করবেন। ঈশ্বর এই মহাপ্রতাপকে হত্যা করবে.","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ سَمُرَةَ ‏ ‏عَنْ ‏ ‏نَافِعِ بْنِ عُتْبَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تُقَاتِلُونَ ‏ ‏جَزِيرَةَ الْعَرَبِ ‏ ‏فَيَفْتَحُهَا اللَّهُ وَتُقَاتِلُونَ ‏ ‏فَارِسَ ‏ ‏فَيَفْتَحُهُمْ اللَّهُ وَتُقَاتِلُونَ ‏ ‏الرُّومَ ‏ ‏فَيَفْتَحُهُمْ اللَّهُ وَتُقَاتِلُونَ ‏ ‏الدَّجَّالَ ‏ ‏فَيَفْتَحُهُ اللَّهُ ‏","","",""],[18205,18205,"","আমরা তোমার বাবার সাথে কথা বলেছি... ...আর আমি বিশ্বাস করি যে তোমার রক্তের একজন অতিথি আছে। আমরা ঈশ্বরের লর্ডের সাথে ছিলাম আর তারপর সে... বিজয়ীর জয় অনুষ্ঠানে উদ্ধার করা হয়েছে। নেকড়েরা হাতপাড়া করে এবং তারা যেন ভালো। আমার হাত বলছে তুমি বিয়েটা ঈশ্বরের কাছে খোলা রেখে জিতেছ এবং তারপর তুমি জিতে যাবে। সিগার, সে এটা করবে, সে করবে, সে এটা করবে, সে এটা করবে, সে এটা করবে, সে এটা করবে, সে কখনো তার চোখকে দেখবে না যতক্ষণ না মদ মারা যায়।","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ يَعْنِي الْفَزَارِيَّ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ سَمُرَةَ ‏ ‏عَنْ ‏ ‏نَافِعِ بْنِ عُتْبَةَ ‏ ‏قَالَ ‏ ‏كُنْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي غَزَاةٍ فَأَتَاهُ قَوْمٌ مِنْ قِبَلِ الْمَغْرِبِ عَلَيْهِمْ ثِيَابُ ‏ ‏الصُّوفِ ‏ ‏فَوَافَقُوهُ عِنْدَ ‏ ‏أَكَمَةٍ ‏ ‏وَهُمْ قِيَامٌ وَهُوَ قَاعِدٌ فَأَتَيْتُهُ فَقُمْتُ بَيْنَهُمْ وَبَيْنَهُ فَحَفِظْتُ مِنْهُ أَرْبَعَ كَلِمَاتٍ أَعُدُّهُنَّ فِي يَدِي قَالَ ‏ ‏تَغْزُونَ ‏ ‏جَزِيرَةَ الْعَرَبِ ‏ ‏فَيَفْتَحُهَا اللَّهُ ثُمَّ تَغْزُونَ ‏ ‏فَارِسَ ‏ ‏فَيَفْتَحُهَا اللَّهُ ثُمَّ تَغْزُونَ ‏ ‏الرُّومَ ‏ ‏فَيَفْتَحُهَا اللَّهُ ثُمَّ تَغْزُونَ ‏ ‏الدَّجَّالَ ‏ ‏فَيَفْتَحُهُ اللَّهُ قَالَ ‏ ‏نَافِعٌ ‏ ‏يَا ‏ ‏جَابِرُ ‏ ‏أَلَا ‏ ‏تَرَى أَنَّ ‏ ‏الدَّجَّالَ ‏ ‏لَا يَخْرُجُ حَتَّى تُفْتَحَ ‏ ‏الرُّومُ ‏","","",""],[18206,18206,"","আমি খুব বেশি কিছু করার কথা বলেছি, তাকে দ্রুত পাঠাতে হলে আমি লজ্জিত। আমি তাদের কাছে অনুরোধ করছি ঈশ্বরের দোহাই, তুমি প্রভুর গেরিলা... ...যে তুমি ঈশ্বরের কাছে যা বলেছে তা করতে গিয়ে...","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ يَعْنِي الْمُعَلِّمَ ‏ ‏عَنِ ‏ ‏ابْنِ بُرَيْدَةَ ‏ ‏حَدَّثَنِي ‏ ‏حَنْظَلَةُ بْنُ عَلِيٍّ ‏ ‏أَنَّ ‏ ‏مِحْجَنَ بْنَ الْأَدْرَعِ ‏ ‏حَدَّثَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ الْمَسْجِدَ فَإِذَا هُوَ بِرَجُلٍ قَدْ قَضَى صَلَاتَهُ وَهُوَ يَتَشَهَّدُ وَهُوَ يَقُولُ اللَّهُمَّ إِنِّي أَسْأَلُكَ بِاللَّهِ الْوَاحِدِ الْأَحَدِ ‏ ‏الصَّمَدِ ‏ ‏الَّذِي لَمْ يَلِدْ وَلَمْ يُولَدْ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ أَنْ تَغْفِرَ لِي ذُنُوبِي إِنَّكَ أَنْتَ الْغَفُورُ الرَّحِيمُ قَالَ فَقَالَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ غُفِرَ لَهُ قَدْ غُفِرَ لَهُ قَدْ غُفِرَ لَهُ ثَلَاثَ مَرَّاتٍ ‏","","",""],[18207,18207,"","আমি জানি যে, ঈশ্বর তাঁর জন্য প্রার্থনা করেছেন এবং প্রতিপক্ষের নাম বধির হওয়ার পর লোকেদের পাপ উদ্ধার করবেন । প্রতিপক্ষ আর মোলে তিন বার বিষে আক্রান্ত হয় যখন প্রতিপক্ষ মারা যায়। তোমার দুঃখ যেন খারাপ থাকে, আর তোমার দুঃখটা শেষ হয়ে যাবে।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْجُرَيْرِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَقِيقٍ ‏ ‏عَنْ ‏ ‏مِحْجَنِ بْنِ الْأَدْرَعِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَطَبَ النَّاسَ فَقَالَ ‏ ‏يَوْمُ الْخَلَاصِ وَمَا يَوْمُ الْخَلَاصِ يَوْمُ الْخَلَاصِ وَمَا يَوْمُ الْخَلَاصِ يَوْمُ الْخَلَاصِ وَمَا يَوْمُ الْخَلَاصِ ثَلَاثًا فَقِيلَ لَهُ وَمَا يَوْمُ الْخَلَاصِ قَالَ يَجِيءُ ‏ ‏الدَّجَّالُ ‏ ‏فَيَصْعَدُ ‏ ‏أُحُدًا ‏ ‏فَيَنْظُرُ ‏ ‏الْمَدِينَةَ ‏ ‏فَيَقُولُ لِأَصْحَابِهِ أَتَرَوْنَ هَذَا الْقَصْرَ الْأَبْيَضَ هَذَا ‏ ‏مَسْجِدُ أَحْمَدَ ‏ ‏ثُمَّ يَأْتِي ‏ ‏الْمَدِينَةَ ‏ ‏فَيَجِدُ بِكُلِّ ‏ ‏نَقْبٍ ‏ ‏مِنْهَا مَلَكًا مُصْلِتًا فَيَأْتِي ‏ ‏سَبْخَةَ ‏ ‏الْحَرْفِ ‏ ‏فَيَضْرِبُ ‏ ‏رُوَاقَهُ ‏ ‏ثُمَّ تَرْجُفُ ‏ ‏الْمَدِينَةُ ‏ ‏ثَلَاثَ رَجَفَاتٍ فَلَا ‏ ‏يَبْقَى مُنَافِقٌ وَلَا مُنَافِقَةٌ وَلَا فَاسِقٌ وَلَا فَاسِقَةٌ إِلَّا خَرَجَ إِلَيْهِ فَذَلِكَ يَوْمُ الْخَلَاصِ ‏","","",""],[18208,18208,"","আমরা একটা আবেগ নিয়ে কথা বলেছি যে, বাবার জন্য ভালো একটা সমস্যা নিয়ে এসেছি। সে খুব খুশি ছিল যে তাকে খুন করতে হয়েছে এবং সে বায়ুতে ছিল। সে যা বলে, আমি আমার হাত তুলে নিচ্ছি। শহর তার মায়ের গ্রাম খুন করছে, তাকে তার সবচেয়ে ভাল বাবা বলে ডাকে, শুধু তার বাবা, একজন রাজা ভিতরে যেতে বাধ্য, তারপর সে ভিতরে যেতে বাধ্য। আমার হাত কেটে আমার হাত কেটে গেল, কে যেন আমার কথা শুনবে? আমার হাত বলে যে তুমি তোমার ঋণ আমাদের কাছে ঈশ্বরের কাছে হেরেছো? ভাই হতে পারে যে তোমার বাবার সাথে যাবে সে কথা বলেছে.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَقِيقٍ ‏ ‏عَنْ ‏ ‏رَجَاءِ بْنِ أَبِي رَجَاءٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏بُرَيْدَةُ ‏ ‏عَلَى بَابِ الْمَسْجِدِ فَمَرَّ ‏ ‏مِحْجَنٌ ‏ ‏عَلَيْهِ ‏ ‏وَسُكْبَةُ ‏ ‏يُصَلِّي فَقَالَ ‏ ‏بُرَيْدَةُ ‏ ‏وَكَانَ فِيهِ ‏ ‏مُرَاحٌ ‏ ‏لِمِحْجَنٍ ‏ ‏أَلَا تُصَلِّي كَمَا ‏ ‏يُصَلِّي هَذَا فَقَالَ ‏ ‏مِحْجَنٌ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخَذَ بِيَدِي فَصَعِدَ عَلَى ‏ ‏أُحُدٍ ‏ ‏فَأَشْرَفَ ‏ ‏عَلَى ‏ ‏الْمَدِينَةِ ‏ ‏فَقَالَ ‏ ‏وَيْلُ أُمِّهَا قَرْيَةً يَدَعُهَا أَهْلُهَا خَيْرَ مَا تَكُونُ ‏ ‏أَوْ كَأَخْيَرِ مَا تَكُونُ ‏ ‏فَيَأْتِيهَا ‏ ‏الدَّجَّالُ ‏ ‏فَيَجِدُ عَلَى كُلِّ بَابٍ مِنْ أَبْوَابِهَا مَلَكًا مُصْلِتًا جَنَاحَيْهِ فَلَا يَدْخُلُهَا قَالَ ثُمَّ نَزَلَ وَهُوَ آخِذٌ بِيَدِي فَدَخَلَ الْمَسْجِدَ وَإِذَا هُوَ بِرَجُلٍ ‏ ‏يُصَلِّي فَقَالَ لِي مَنْ هَذَا فَأَتَيْتُ عَلَيْهِ فَأَثْنَيْتُ عَلَيْهِ خَيْرًا فَقَالَ اسْكُتْ لَا تُسْمِعْهُ فَتُهْلِكَهُ قَالَ ثُمَّ أَتَى حُجْرَةَ امْرَأَةٍ مِنْ نِسَائِهِ فَنَفَضَ يَدَهُ مِنْ يَدِي قَالَ إِنَّ خَيْرَ دِينِكُمْ أَيْسَرُهُ إِنَّ خَيْرَ دِينِكُمْ أَيْسُرُهُ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ شَقِيقٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏رَجَاءِ بْنِ أَبِي رَجَاءٍ الْبَاهِلِيِّ ‏ ‏عَنْ ‏ ‏مِحْجَنٍ ‏ ‏رَجُلٍ مِنْ ‏ ‏أَسْلَمَ ‏ ‏فَذَكَرَ مَعْنَاهُ وَلَمْ يَقُلْ ‏ ‏حَجَّاجٌ ‏ ‏وَلَا ‏ ‏أَبُو النَّضْرِ ‏ ‏بِجَنَاحِهِ ‏","","",""],[18209,18209,"","আমরা দুজন জাহাজকে একটি ফুলের বাচ্চা নিয়ে কথা বলেছি... ...একদা আমি বলেছিলাম দুটো গোপন বা দু'জন গোপনীয়তা বা দুঃখের জীবন। তিনি বললেন, আমার বাবা একজন স্বৈরশাসক। আমি তো শুধু বলেছিলাম, আমি যদি বলি, \"আমার বাবা\" আর \"আমি\" নবী তার জন্য এসেছিলেন এবং তাকে উদ্ধার করতে তিনি প্রার্থনা করতে যান তিনি কখনো যেতে না বলেন, তিনি তার কুত্তী করেছিলেন, তিনি বলেন আমার বাবা-বো-মা-মা-মামমম্য-মামসরী।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏مَرَّةً ‏ ‏عَنْ ‏ ‏بُسْرٍ ‏ ‏أَوْ ‏ ‏بُسْرِ بْنِ مِحْجَنٍ ‏ ‏ثُمَّ كَانَ يَقُولُ بَعْدُ ‏ ‏عَنْ ‏ ‏أَبِي مِحْجَنٍ الدِّيلِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ فِي الْمَسْجِدِ فَحَضَرَتْ الصَّلَاةُ فَصَلَّى فَقَالَ لِي أَلَا صَلَّيْتَ قَالَ قُلْتُ يَا رَسُولَ اللَّهِ قَدْ صَلَّيْتُ فِي الرَّحْلِ ثُمَّ أَتَيْتُكَ قَالَ ‏ ‏فَإِذَا فَعَلْتَ فَصَلِّ مَعَهُمْ وَاجْعَلْهَا ‏ ‏نَافِلَةً ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏وَلَمْ يَقُلْ ‏ ‏أَبُو نُعَيْمٍ ‏ ‏وَلَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏وَاجْعَلْهَا ‏ ‏نَافِلَةً ‏","","",""],[18210,18210,"","আমরা একটি ছেলের জন্য ভাল কাজ করেছি নিশ্চিত করার চেষ্টা করেছি. তারপর এটা ভবিষ্যদ্বাণী যে তিনি এটা সংরক্ষণ এবং এটি ধার্মিকদের রক্ষা করার দুটি উপায় তাহলে তুমি পাগলের ঘরে যেতে দিবে... ...যে তুমি আমাকে ক্ষমা করবে, প্রভু, আমি ব্যর্থ হব না। সে ঈশ্বরের কাছে আত্মসমর্পণ করেছে যেন একটা প্রতিজ্ঞা করে। যতক্ষণ না সে এগুলো খুলে ফেলে.","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجُ بْنُ النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏بَقِيَّةُ بْنُ الْوَلِيدِ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ سُلَيْمٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ جَابِرٍ ‏ ‏عَنْ ‏ ‏ضَمْرَةَ بْنِ ثَعْلَبَةَ ‏ ‏أَنَّهُ ‏ ‏أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَلَيْهِ ‏ ‏حُلَّتَانِ ‏ ‏مِنْ ‏ ‏حُلَلِ ‏ ‏الْيَمَنِ ‏ ‏فَقَالَ يَا ‏ ‏ضَمْرَةُ ‏ ‏أَتَرَى ثَوْبَيْكَ هَذَيْنِ مُدْخِلَيْكَ الْجَنَّةَ فَقَالَ لَئِنْ اسْتَغْفَرْتَ لِي يَا رَسُولَ اللَّهِ لَا أَقْعُدُ حَتَّى أَنْزَعَهُمَا عَنِّي فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّهُمَّ اغْفِرْ ‏ ‏لِضَمْرَةَ بْنِ ثَعْلَبَةَ ‏ ‏فَانْطَلَقَ سَرِيعًا حَتَّى نَزَعَهُمَا عَنْهُ ‏","","",""],[18211,18211,"","আমি আমাকে হত্যা করার কথা বলেছি, প্রভু তার কাছে প্রার্থনা করেছেন এবং তিনি তাকে ভালোবাসতে গিয়ে তাকে মারতে রাজি হবেন।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏يَعْقُوبَ بْنِ بَحِيرٍ ‏ ‏عَنْ ‏ ‏ضِرَارِ بْنِ الْأَزْوَرِ ‏ ‏قَالَ ‏ ‏بَعَثَنِي أَهْلِي ‏ ‏بِلَقُوحٍ ‏ ‏إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَمَرَنِي أَنْ أَحْلُبَهَا فَحَلَبْتُهَا فَقَالَ لِي ‏ ‏دَعْ ‏ ‏دَاعِيَ ‏ ‏اللَّبَنِ ‏","","",""],[18212,18212,"","আমরা একজন ভাল মানুষ নিয়ে জন্মগ্রহণ করেছি যিনি প্রান্তরে নিহত হয়েছে. আমার ফোন করবে না, বাছা।","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏يَعْقُوبَ بْنِ بَحِيرٍ ‏ ‏رَجُلٍ مِنْ الْحَيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ضِرَارَ بْنَ الْأَزْوَرِ ‏ ‏قَالَ ‏ ‏أَهْدَيْنَا لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِقْحَةً ‏ ‏قَالَ فَحَلَبْتُهَا قَالَ فَلَمَّا أَخَذْتُ ‏ ‏لِأُجْهِدَهَا ‏ ‏قَالَ ‏ ‏لَا تَفْعَلْ دَعْ دَاعِيَ اللَّبَنِ ‏","","",""],[18213,18213,"","আমরা আমাদের সবচেয়ে ভালো কিছুর কথা বলেছি, ঈশ্বর তাকে আদেশ দিয়েছেন আর তিনি তা করে যাচ্ছেন আর আমার হৃদয় ঈশ্বরের জন্য আমার ফোন করে ধ্বংস করার চেষ্টা করছে। আমরা কথা বলেছি। ঈশ্বর সম্বন্ধে আপনি তাঁকে হত্যা করার চেষ্টা করেছিলেন বা না করার চেষ্টা করেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ سِنَانٍ ‏ ‏عَنْ ‏ ‏ضِرَارِ بْنِ الْأَزْوَرِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّ بِهِ وَهُوَ يَحْلُبُ فَقَالَ ‏ ‏دَعْ ‏ ‏دَاعِيَ ‏ ‏اللَّبَنِ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏و حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ بَكَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْمُبَارَكِ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏أَوْ عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏يَعْقُوبَ بْنِ بَحِيرٍ ‏ ‏عَنْ ‏ ‏ضِرَارِ بْنِ الْأَزْوَرِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِنَحْوِهِ ‏","","",""],[18214,18214,"","আমরা কথা বলেছি কিভাবে আমরা জানতে চেষ্টা করেছি যে তিনি কি করে বলছেন তার কাছে একটি হাতিয়ার আছে। ঈশ্বর তাকে দেখেছেন তার বক্তব্যের শেষে তিনি তাকে অনুসরণ করেছেন। আমি জানি, তিনি যদি জানতে চান, তাহলে আমি কি ভাবে চেষ্টা করছি। আমি কি ভাবে চেষ্টা করছি, তা হল, তিনি কি করে জানেন, তার কাছে কি ভাবে তিনি কি পরিমাণ তথ্য আছে? এবং আমি জানি, আমি কি ভাবে এটা জানতে চাই। আমি জানি, আমি জানি, তিনি কি করে, আমি এটা করতে চাই। এবং আমি কি ভাবে তাকে জিজ্ঞেস করেছি, আমি যখন আমি এটা করতে চাই, তখন আমি জানি, আমি জানি, আমি জানি, আমি জানি, আমি জানি, আমি কি বলছি, আমি জানি, আমি জানি, আমি জানি, আমি কি করেছি। আমি জানি না। আমি জানি, আমি জানি, আমি জানি, আমি জানি, আমি জানি, আমি কি করেছি। তার নিজের দেশে যদি ভুল পথে থাকতো।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْرَائِيلَ الْجُشَمِيُّ ‏ ‏عَنْ ‏ ‏شَيْخٍ لَهُمْ يُقَالُ لَهُ ‏ ‏جَعْدَةُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى لِرَجُلٍ رُؤْيَا قَالَ فَبَعَثَ إِلَيْهِ فَجَاءَ فَجَعَلَ يَقُصُّهَا عَلَيْهِ وَكَانَ الرَّجُلُ عَظِيمَ الْبَطْنِ قَالَ فَجَعَلَ يَقُولُ بِأُصْبُعِهِ فِي بَطْنِهِ لَوْ كَانَ هَذَا فِي غَيْرِ هَذَا لَكَانَ خَيْرًا لَكَ ‏","","",""],[18215,18215,"","আমরা দুই বছর কাজ করেছি, যা আমার কাছে প্রভুর দয়া দেখানোর পর ঘটেছে, ঈশ্বরের কাছে সবচেয়ে ভালো ঈশ্বরের সেবা করাই হল তার সেরা। আমরা চাই, আমরা সবচেয়ে ভালো। তাকে বন্ধ করে দাও, আর আমি যখন কথা বললাম তখন আমি একটা ছেলেকে কি বলেছিলাম.","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏عَنِ ‏ ‏السَّائِبِ بْنِ يَزِيدَ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ بْنِ الْحَضْرَمِيِّ ‏ ‏إِنْ شَاءَ اللَّهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَمْكُثُ الْمُهَاجِرُ ‏ ‏بِمَكَّةَ ‏ ‏بَعْدَ قَضَاءِ ‏ ‏نُسُكِهِ ‏ ‏ثَلَاثًا ‏ ‏قَالَ ‏ ‏مَا كَانَ أَشَدَّ عَلَى ‏ ‏ابْنِ عُيَيْنَةَ ‏ ‏أَنْ يَقُولَ حَدَّثَنَا ‏","","",""],[18216,18216,"","আমরা সিরিনের ছেলের সঙ্গে পর্দার বেদীর পুত্র সম্বন্ধে কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏حَدَّثَنَا ‏ ‏مَنْصُورٌ ‏ ‏عَنِ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنِ ‏ ‏ابْنِ الْعَلَاءِ بْنِ الْحَضْرَمِيِّ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏حَدَّثَنَا بِهِ ‏ ‏هُشَيْمٌ ‏ ‏مَرَّتَيْنِ مَرَّةً عَنْ ‏ ‏ابْنِ الْعَلَاءِ ‏ ‏وَمَرَّةً لَمْ يَصِلْ ‏ ‏أَنَّ ‏ ‏أَبَاهُ ‏ ‏كَتَبَ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَبَدَأَ بِنَفْسِهِ ‏","","",""],[18217,18217,"","আমরা দুই বছর ধরে পুত্রদের দেখে আসছি যারা একজন যাজকের সাথে শান্তি স্থাপন করতে ভয় পায় যে এটা না বলে সে আত্মসমর্পণ করবে যদি তুমি প্রভাবিত হও, যদি তুমি খেয়ে ফেলতে বা খেয়ে ফেলতে পারো পাস.","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ يَسَافٍ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ قَيْسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا تَوَضَّأْتَ ‏ ‏فَانْتَثِرْ ‏ ‏وَإِذَا ‏ ‏اسْتَجْمَرْتَ ‏ ‏فَأَوْتِرْ ‏","","",""],[18218,18218,"","আমরা একটা নির্দিষ্ট ছেলের ব্যাপারে কথা বলেছি যে কিনা একটা ঘোমটা দিতে রাজি আছে। ঈশ্বরের কাছে প্রার্থনা করবে যদি তুমি শান্ত থাকো","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ يَسَافٍ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ قَيْسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا تَوَضَّأْتَ ‏ ‏فَانْتَثِرْ ‏ ‏وَإِذَا ‏ ‏اسْتَجْمَرْتَ ‏ ‏فَأَوْتِرْ ‏","","",""],[18219,18219,"","আমরা তার দেখা দেখা দেখার সবচেয়ে ভালো দুটো তরবারি নিয়ে কথা বলেছি... ...ঈশ্বর তাকে শিখিয়েছিলেন আর দয়ার আদালতে পৌঁছে দিয়েছেন... ...আর যখন আমি তার নাম শেয়ার করতে পারি না, চুরি আর ওজনের ব্যাপার না।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ يَسَافٍ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ قَيْسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي حَجَّةِ الْوَدَاعِ ‏ ‏إِنَّمَا هُنَّ أَرْبَعٌ لَا تُشْرِكُوا بِاللَّهِ شَيْئًا وَلَا تَقْتُلُوا النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ وَلَا تَسْرِقُوا وَلَا تَزْنُوا ‏","","",""],[18220,18220,"","আমরা পরের বার বাবার সাথে কথা বলেছিলাম আমরা কীভাবে কথা বলছি সেটা নিয়ে কথা বলতে। আমি আনন্দিত যে তিনি ঈশ্বরের কাছে প্রার্থনা করেছিলেন যদি না তিনি ঈশ্বরের বমিতে আত্মসমর্পণ করতেন। এমন কিছু যা তুমি করতে নিষেধ করেছ, তাকে ঈশ্বরের অনুগ্রহ থেকে উদ্ধার করতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏قَالَ ثَنَا ‏ ‏أَبُو مُعَاوِيَةَ يَعْنِي شَيْبَانَ ‏ ‏حَدَّثَنَا ‏ ‏مَنْصُورٌ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ يَسَافٍ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ قَيْسٍ الْأَشْجَعِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي حَجَّةِ الْوَدَاعِ ‏ ‏أَلَا إِنَّمَا هُنَّ أَرْبَعٌ أَنْ لَا تُشْرِكُوا بِاللَّهِ شَيْئًا وَلَا تَقْتُلُوا النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ وَلَا تَزْنُوا وَلَا تَسْرِقُوا قَالَ فَمَا أَنَا ‏ ‏بِأَشَحَّ ‏ ‏عَلَيْهِنَّ مِنِّي إِذْ سَمِعْتُهُنَّ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[18221,18221,"","তিনি আমাকে ঈশ্বরের কাছে প্রার্থনা করতে বলেছিলেন এবং আপনাকে যদি প্রভাবিত করে থাকেন এবং যদি আপনি শেষ পর্যন্ত হাল ছেড়ে দেন, তাহলে তিনি আত্মসমর্পণ করবেন","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏وَالثَّوْرِيُّ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ يَسَافٍ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ قَيْسٍ ‏ ‏قَالَ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا تَوَضَّأْتَ ‏ ‏فَانْتَثِرْ ‏ ‏وَإِذَا ‏ ‏اسْتَجْمَرْتَ ‏ ‏فَأَوْتِرْ ‏","","",""],[18222,18222,"","আমরা দুই মাসের একটি জাহাজের কথা বলেছি, তার মঙ্গলের দাস হবার কথা শোনার জন্য।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنِ ‏ ‏ابْنِ خُثَيْمٍ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ عُبَيْدِ بْنِ رِفَاعَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَوْلَى الْقَوْمِ مِنْهُمْ وَابْنُ أُخْتِهِمْ مِنْهُمْ وَحَلِيفُهُمْ مِنْهُمْ ‏","","",""],[18223,18223,"","আমরা দুই মাস ধরে একটি নির্দিষ্ট ঈশ্বরের গোলামের কথা বলেছি, ঈশ্বরের দোহাই তাকে শান্তি এনে দিয়েছে এবং একটি হাঙ্গর তোমাকে বলে দেবে তোমার ঈর্ষার কারণে তারা বলেছে, ছেলে না, তোমার ভাগ্নে বলেছে তুমি তোমার চেয়ে ভালো আর সে তোমাকে ভাগ্যের জন্য রক্ষা করতে পারবে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏ابْنِ خُثَيْمٍ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ عُبَيْدِ بْنِ رِفَاعَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏جَمَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُرَيْشًا ‏ ‏فَقَالَ هَلْ فِيكُمْ مِنْ غَيْرِكُمْ قَالُوا لَا إِلَّا ابْنُ أُخْتِنَا وَحَلِيفُنَا وَمَوْلَانَا فَقَالَ ‏ ‏ابْنُ أُخْتِكُمْ مِنْكُمْ وَحَلِيفُكُمْ مِنْكُمْ وَمَوْلَاكُمْ مِنْكُمْ إِنَّ ‏ ‏قُرَيْشًا ‏ ‏أَهْلُ صِدْقٍ وَأَمَانَةٍ فَمَنْ ‏ ‏بَغَى ‏ ‏لَهَا ‏ ‏الْعَوَائِرَ ‏ ‏أَكَبَّهُ ‏ ‏اللَّهُ فِي النَّارِ لِوَجْهِهِ ‏","","",""],[18224,18224,"","আমার প্রিয় স্ত্রী ও বাবা আমাদের সঙ্গে বাইবেল অধ্যয়ন করতে রাজি হয়েছিলেন । স্বপ্ন, আমাদের থেকে এবং আমাদের ভাতিজা আমাদের থেকে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏بِشْرٌ يَعْنِي ابْنَ الْمُفَضَّلِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عُثْمَانَ بْنِ خُثَيْمٍ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ عُبَيْدِ بْنِ رِفَاعَةَ بْنِ رَافِعٍ الزُّرَقِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏حَلِيفُنَا مِنَّا وَمَوْلَانَا مِنَّا وَابْنُ أُخْتِنَا مِنَّا ‏","","",""],[18225,18225,"","আমরা হারুনের কয়েকজনের কথা বলেছি, আমরা বলেছিলাম যে একটা বাচ্চা একটা সুন্দরী মেয়ে যে ভালো মেয়ে হতে চায়। চিড়িয়াখানাটা ছিল লর্ডের কাছে উদ্ধারের চেষ্টা করা। মহান মহান আল্লাহ, তারপর এটা ঈশ্বরের অনুগ্রহে ছাড়া ছিল। আমি প্রতিজ্ঞা করছি, আপনি আমাকে \"বেদ\" বলবেন না। তাহলে তুমি যা করেছ, তারপর তোমার চালা শুরু করবে, তোমার হৃদয় তার কাজতে ফিরে আসবে, আর তারপর তুমি তোমার ইচ্ছা আর সম্মান খুঁজে পাবে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ يَحْيَى بْنِ خَلَّادٍ الزُّرَقِيِّ ‏ ‏عَنْ ‏ ‏رِفَاعَةَ بْنِ رَافِعٍ الزُّرَقِيِّ ‏ ‏وَكَانَ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَالِسٌ فِي الْمَسْجِدِ فَصَلَّى قَرِيبًا مِنْهُ ثُمَّ انْصَرَفَ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَعِدْ صَلَاتَكَ فَإِنَّكَ لَمْ تُصَلِّ قَالَ فَرَجَعَ فَصَلَّى كَنَحْوٍ مِمَّا صَلَّى ثُمَّ انْصَرَفَ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لَهُ أَعِدْ صَلَاتَكَ فَإِنَّكَ لَمْ تُصَلِّ فَقَالَ يَا رَسُولَ اللَّهِ عَلِّمْنِي كَيْفَ أَصْنَعُ قَالَ ‏ ‏إِذَا اسْتَقْبَلْتَ الْقِبْلَةَ فَكَبِّرْ ثُمَّ اقْرَأْ ‏ ‏بِأُمِّ الْقُرْآنِ ‏ ‏ثُمَّ اقْرَأْ بِمَا شِئْتَ فَإِذَا رَكَعْتَ فَاجْعَلْ ‏ ‏رَاحَتَيْكَ ‏ ‏عَلَى رُكْبَتَيْكَ وَامْدُدْ ظَهْرَكَ وَمَكِّنْ لِرُكُوعِكَ فَإِذَا رَفَعْتَ رَأْسَكَ فَأَقِمْ صُلْبَكَ حَتَّى تَرْجِعَ الْعِظَامُ إِلَى مَفَاصِلِهَا وَإِذَا سَجَدْتَ فَمَكِّنْ لِسُجُودِكَ فَإِذَا رَفَعْتَ رَأْسَكَ فَاجْلِسْ عَلَى فَخِذِكَ الْيُسْرَى ثُمَّ اصْنَعْ ذَلِكَ فِي كُلِّ رَكْعَةٍ وَسَجْدَةٍ ‏","","",""],[18226,18226,"","তিনি বলেছিলেন: “আমি আমার কামনার আশীর্বাদ সম্বন্ধে পড়েছি: আপনার টাকা ঈশ্বরের প্রভু ঈশ্বরের দ্বারা জন্ম লাভ করার অর্থ হল, আপনার অর্থ হল ঈশ্বরের পুত্র । ঈশ্বর আর আমি আর কখনোই তা করতে পারব না। ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন এবং তাঁর নেতৃত্বের কাছে সমর্পণ করেছেন এবং ঈশ্বর তাঁর ভালবাসা এবং করুণার জন্য, খুব সুন্দর, তিনি যাচ্ছেন। ঈশ্বরের কাছে প্রার্থনা করুন এবং তিনি জিজ্ঞেস করেন কে, ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন এবং তিনি আপনার কাছে আপনার কাছে পেশ করবেন।","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ مَهْدِيٍّ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نُعَيْمِ بْنِ عَبْدِ اللَّهِ الْمُجْمِرِ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ يَحْيَى الزُّرَقِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏رِفَاعَةَ بْنِ رَافِعٍ الزُّرَقِيِّ ‏ ‏قَالَ ‏ ‏كُنَّا نُصَلِّي يَوْمًا وَرَاءَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمَّا رَفَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأْسَهُ مِنْ الرَّكْعَةِ وَقَالَ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ قَالَ ‏ ‏رَجُلٌ ‏ ‏وَرَاءَهُ رَبَّنَا لَكَ الْحَمْدُ حَمْدًا كَثِيرًا طَيِّبًا مُبَارَكًا فِيهِ فَلَمَّا انْصَرَفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ مَنْ الْمُتَكَلِّمُ ‏ ‏آنِفًا ‏ ‏قَالَ الرَّجُلُ أَنَا يَا رَسُولَ اللَّهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَقَدْ ‏ ‏رَأَيْتُ بِضْعَةً وَثَلَاثِينَ مَلَكًا ‏ ‏يَبْتَدِرُونَهَا ‏ ‏أَيُّهُمْ يَكْتُبُهَا أَوَّلًا ‏","","",""],[18227,18227,"","আমরা আনন্দের সাথে কথা বলেছি, আমরা কিভাবে এই বিষয়ে কথা বলেছি। সে বলতে শুরু করল আমরা ঈশ্বরের বার্তাবাহকের সাথে, তার পতাকা ছিল গৌরবের জন্য। কয়েক বছর আগে তিনি বলেছিলেন যে, তার তিন বা চার বছর কাজ সত্যিই তার রয়েছে । আত্মসমর্পণ কর যদি আমি প্রার্থনা করি এবং উজ্জ্বল হই, তাহলে আমি তোমার আলো এবং তারপর জিতবো। তারপর আমি উঠে দাঁড়াবো, যতক্ষণ না আমি কাজ করি এবং তারপর একটা ভালো ধ্বংশ হয়ে যাব, ততক্ষণ পর্যন্ত তুমি চুপ থাকবে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عَجْلَانَ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ يَحْيَى بْنِ خَلَّادٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏وَكَانَ بَدْرِيًّا ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْمَسْجِدِ فَدَخَلَ رَجُلٌ فَصَلَّى فِي نَاحِيَةِ الْمَسْجِدِ فَجَعَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَرْمُقُهُ ‏ ‏ثُمَّ جَاءَ فَسَلَّمَ فَرَدَّ عَلَيْهِ وَقَالَ ارْجِعْ فَصَلِّ فَإِنَّكَ لَمْ تُصَلِّ قَالَ مَرَّتَيْنِ ‏ ‏أَوْ ثَلَاثًا ‏ ‏فَقَالَ لَهُ فِي الثَّالِثَةِ ‏ ‏أَوْ فِي الرَّابِعَةِ ‏ ‏وَالَّذِي بَعَثَكَ بِالْحَقِّ لَقَدْ أَجْهَدْتُ نَفْسِي فَعَلِّمْنِي وَأَرِنِي فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَرَدْتَ أَنْ تُصَلِّيَ فَتَوَضَّأْ فَأَحْسِنْ وُضُوءَكَ ثُمَّ اسْتَقْبِلْ الْقِبْلَةَ ثُمَّ كَبِّرْ ثُمَّ اقْرَأْ ثُمَّ ارْكَعْ حَتَّى تَطْمَئِنَّ رَاكِعًا ثُمَّ ارْفَعْ حَتَّى تَطْمَئِنَّ قَائِمًا ثُمَّ اسْجُدْ حَتَّى تَطْمَئِنَّ سَاجِدًا ثُمَّ ارْفَعْ حَتَّى تَطْمَئِنَّ جَالِسًا ثُمَّ اسْجُدْ حَتَّى تَطْمَئِنَّ سَاجِدًا ثُمَّ قُمْ فَإِذَا أَتْمَمْتَ صَلَاتَكَ عَلَى هَذَا فَقَدْ أَتْمَمْتَهَا وَمَا انْتَقَصْتَ مِنْ هَذَا مِنْ شَيْءٍ فَإِنَّمَا تُنْقِصُهُ مِنْ صَلَاتِكَ ‏","","",""],[18228,18228,"","আমরা যাজকদের সাথে কথা বলেছি, আমরা দাসের সাথে কথা বলেছি, আল্লাহ তাকে আমার ছেলে হিসেবে নয়, স্বপ্নের মধ্যে দিয়ে যেতে বলেছেন। আমরা আমাদের সাথে আছি বলে আমরা সবার সেরাটা। আমরা কি বলেছি? আমরা কি সত্যিই জানি, আমরা এখন আমাদের সাথে আছি? আমরা কি বলছি, আমরা এখন আমাদের সাথে আছি? আমরা এখন আমরা এখন থেকে ভাল আছি। আমরা কি করছি? আমরা যদি আমরা আমাদের সাথে আছি, আমরা এখন আমরা এখন আমরা এখানে এসেছি, আমরা এখন আমরা এখন আমাদের কাছে এসেছি। আমরা এখন আমরা এখন আমরা এখানে আছি। আমরা এখন আমরা এখন আমাদের জন্য একটি ভাল উপায় আছে। আমরা কি? আমরা এখন আমরা আমাদের জন্য একটি ভাল উপায় আছে? আমরা কি করব? আমরা এখন আমরা এখানে এসেছি এবং আমরা এখন আমরা একটি দল হিসেবে কাজ করছি, আমরা আমাদের সাথে কাজ করছি। আমরা কি করছি? যারা বিলুপ্ত হয়েছে বা হবে না, তাদের বলা হয়েছে যে আমরা নেই।","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏عِكْرِمَةُ يَعْنِي ابْنَ عَمَّارٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏طَارِقُ بْنُ عَبْدِ الرَّحْمَنِ الْقُرَشِيُّ ‏ ‏قَالَ ‏ ‏جَاءَ ‏ ‏رَافِعُ بْنُ رِفَاعَةَ ‏ ‏إِلَى مَجْلِسِ ‏ ‏الْأَنْصَارِ ‏ ‏فَقَالَ لَقَدْ نَهَانَا نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْيَوْمَ عَنْ شَيْءٍ كَانَ يَرْفُقُ بِنَا فِي مَعَايِشِنَا فَقَالَ ‏ ‏نَهَانَا عَنْ ‏ ‏كِرَاءِ ‏ ‏الْأَرْضِ قَالَ مَنْ كَانَتْ لَهُ أَرْضٌ فَلْيَزْرَعْهَا أَوْ لِيُزْرِعْهَا أَخَاهُ أَوْ لِيَدَعْهَا وَنَهَانَا عَنْ كَسْبِ ‏ ‏الْحَجَّامِ ‏ ‏وَأَمَرَنَا أَنْ نُطْعِمَهُ ‏ ‏نَوَاضِحَنَا ‏ ‏وَنَهَانَا عَنْ كَسْبِ الْأَمَةِ إِلَّا مَا عَمِلَتْ بِيَدِهَا وَقَالَ هَكَذَا بِأَصَابِعِهِ نَحْوَ الْخَبْزِ وَالْغَزْلِ وَالنَّفْشِ ‏","","",""],[18229,18229,"","আমরা একটা কালো ছেলের কথা বলেছিলাম, যার কথা ছিল খারাপ একটা ছেলেকে জানতে হয়েছে ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ عِلَاقَةَ ‏ ‏عَنْ ‏ ‏عَرْفَجَةَ بْنِ شُرَيْحٍ الْأَسْلَمِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهَا سَتَكُونُ بَعْدِي ‏ ‏هَنَاتٌ ‏ ‏وَهَنَاتٌ ‏ ‏وَرَفَعَ يَدَيْهِ فَمَنْ رَأَيْتُمُوهُ يُفَرِّقُ بَيْنَ أُمَّةِ ‏ ‏مُحَمَّدٍ ‏ ‏وَهُمْ جَمِيعٌ فَاقْتُلُوهُ كَائِنًا مَنْ كَانَ مِنْ النَّاسِ ‏","","",""],[18230,18230,"","আমরা আমাদের আবেগ দিয়ে বাপ্তাইজিত হয়েছি... ...একটা লড়াই চালিয়ে যাওয়ার রীতি নিয়ে... ...আমি বলতে শুনেছি যে ঈশ্বর তাকে স্বর্গে আর স্বর্গে নিয়ে যাবে.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ عِلَاقَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَرْفَجَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّهُ سَتَكُونُ ‏ ‏هَنَاتٌ ‏ ‏وَهَنَاتٌ ‏ ‏فَمَنْ أَرَادَ أَنْ يُفَرِّقَ أَمْرَ هَذِهِ الْأُمَّةِ وَهِيَ جَمِيعٌ فَاضْرِبُوهُ بِالسَّيْفِ كَائِنًا مَنْ كَانَ ‏","","",""],[18231,18231,"","আমরা একটি ছেলে কথা বলেছি যে পরম খুশি যে ঈশ্বরকে তাঁর কাছে পাঠানো হওয়ার আগে তাকে ঈশ্বরের কাছে পাঠানো হয়েছিল. তিনি তাকে তার প্রার্থনা পাঠাতে আদেশ করেছিলেন, তিনি বললেন, তিনি ঈশ্বরের কাছে প্রার্থনা করতে। সে এটা ব্যাখ্যা করতে বলেছিল.","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى يَعْنِي ابْنَ سَعِيدٍ ‏ ‏أَنَّ ‏ ‏عَبَّادَ بْنَ تَمِيمٍ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏عُوَيْمِرِ بْنِ أَشْقَرَ ‏ ‏أَنَّهُ ذَبَحَ قَبْلَ أَنْ يَغْدُوَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَّهُ ذَكَرَ ذَلِكَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعْدَمَا فَرَغَ ‏ ‏فَأَمَرَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَعُودَ لِأُضْحِيَّتِهِ ‏","","",""],[18232,18232,"","আমরা ঈশ্বরের প্রতি প্রেম দেখিয়ে আমাকে ধ্বংস করার চেষ্টা করেছিলাম । চলে যায়নি.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي جَعْفَرٍ الْخَطْمِيِّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ كَعْبٍ الْقُرَظِيِّ ‏ ‏عَنْ ‏ ‏كَثِيرِ بْنِ السَّائِبِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ابْنَا قُرَيْظَةَ ‏ ‏أَنَّهُمْ ‏ ‏عُرِضُوا عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏زَمَنَ ‏ ‏قُرَيْظَةَ ‏ ‏فَمَنْ كَانَ مِنْهُمْ ‏ ‏مُحْتَلِمًا ‏ ‏أَوْ نَبَتَتْ ‏ ‏عَانَتُهُ ‏ ‏قُتِلَ وَمَنْ لَا تُرِكَ ‏","","",""],[18233,18233,"","আমরা কয়েকটা ঘোড়ার কথা বলেছি, আমি সেই ভাববাদী যে তার জন্য প্রার্থনা করেছিল আর তার চাহিদা পূরণ করে দিয়েছিল।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏بُشَيْرِ بْنِ يَسَارٍ ‏ ‏عَنِ ‏ ‏الْحُصَيْنِ بْنِ مِحْصَنٍ ‏ ‏أَنَّ عَمَّةً لَهُ أَتَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي حَاجَةٍ فَفَرَغَتْ مِنْ حَاجَتِهَا فَقَالَ لَهَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَذَاتُ زَوْجٍ أَنْتِ قَالَتْ نَعَمْ قَالَ كَيْفَ أَنْتِ لَهُ قَالَتْ مَا ‏ ‏آلُوهُ ‏ ‏إِلَّا مَا عَجَزْتُ عَنْهُ قَالَ ‏ ‏فَانْظُرِي أَيْنَ أَنْتِ مِنْهُ فَإِنَّمَا هُوَ جَنَّتُكِ وَنَارُكِ ‏","","",""],[18234,18234,"","আমার দুগ্ধশর্করা ভবনের একজন দাসের মঙ্গলভাব ছিল আমার প্রিয় এক দাস, যে বলে যে, ঈশ্বর উপস্থিত হয়েছেন । সেই দিন, লোকে বলে এটা ঈশ্বর নয়, মানুষ মুক্ত নয়। আমি বলছি, এটা একটা মিথ্যাবাদী যে তাকে যেতে বলবে। তারা আমাকে বলবে যে তার চাচাকে যেতে যাচ্ছে। যাও, আমরা আমার ছেলেকে খুঁজে বের করার চেষ্টা করেছি, আমার ছেলে, প্রাপ্তবয়স্কের ছেলে, দালাই নামের ছেলে, সে বলল, আল্লাহ তার নিজের শান্তি আছে এবং তিনি বলেছেন এটা অপরিহার্য। আমাকে এই পাপের সাথে যেতে হবে, সে বলল আমি তোমার ছেলে হিসেবেও পড়তে পারি।","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ أَبِي الْعَبَّاسِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏رَجُلٌ يُقَالُ لَهُ ‏ ‏رَبِيعَةُ بْنُ عَبَّادٍ ‏ ‏مِنْ ‏ ‏بَنِي الدِّيلِ ‏ ‏وَكَانَ جَاهِلِيًّا ‏ ‏قَالَ ‏ ‏رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْجَاهِلِيَّةِ فِي سُوقِ ‏ ‏ذِي الْمَجَازِ ‏ ‏وَهُوَ يَقُولُ يَا أَيُّهَا النَّاسُ قُولُوا ‏ ‏لَا إِلَهَ إِلَّا اللَّهُ تُفْلِحُوا وَالنَّاسُ مُجْتَمِعُونَ عَلَيْهِ وَوَرَاءَهُ رَجُلٌ ‏ ‏وَضِيءُ ‏ ‏الْوَجْهِ أَحْوَلُ ذُو ‏ ‏غَدِيرَتَيْنِ ‏ ‏يَقُولُ إِنَّهُ ‏ ‏صَابِئٌ ‏ ‏كَاذِبٌ يَتْبَعُهُ حَيْثُ ذَهَبَ فَسَأَلْتُ عَنْهُ فَذَكَرُوا لِي نَسَبَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالُوا لِي هَذَا عَمُّهُ ‏ ‏أَبُو لَهَبٍ ‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏رَبِيعَةَ بْنِ عَبَّادٍ الدُّؤَلِيِّ ‏ ‏وَكَانَ جَاهِلِيًّا فَأَسْلَمَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ الْحَدِيثَ قَالَ فَقُلْتُ مَنْ هَذَا قَالَ هَذَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ عَبْدِ الْمُطَّلِبِ ‏ ‏وَهُوَ يَذْكُرُ النُّبُوَّةَ قُلْتُ مَنْ هَذَا الَّذِي يُكَذِّبُهُ قَالُوا ‏ ‏هَذَا عَمُّهُ ‏ ‏أَبُو لَهَبٍ ‏ ‏قَالَ ‏ ‏أَبُو الزِّنَادِ ‏ ‏فَقُلْتُ ‏ ‏لِرَبِيعَةَ بْنِ عَبَّادٍ ‏ ‏إِنَّكَ يَوْمَئِذٍ كُنْتَ صَغِيرًا قَالَ لَا وَاللَّهِ إِنِّي يَوْمَئِذٍ لَأَعْقِلُ أَنِّي ‏ ‏لَأَزْفِرُ ‏ ‏الْقِرْبَةَ ‏ ‏يَعْنِي أَحْمِلُهَا ‏","","",""],[18235,18235,"","আমরা হারুনের চেয়ে মহান ছিলাম। আমি বাবাকে বলেছিলাম তার দাদার ছায়ার উপর নজর রাখতে। অজানা কুকুরকে শপথ থেকে নেয়া হয়েছে। লর্ডের কাছে যে আদেশ করেছে, সে বলতে যাচ্ছে সে আমার বাবাকে মাফ করে দিয়েছে.","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْأَشْهَبِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ طَرَفَةَ ‏ ‏أَنَّ جَدَّهُ ‏ ‏عَرْفَجَةَ ‏ ‏أُصِيبَ أَنْفُهُ يَوْمَ ‏ ‏الْكُلَابِ ‏ ‏فِي الْجَاهِلِيَّةِ فَاتَّخَذَ أَنْفًا مِنْ وَرِقٍ فَأَنْتَنَ عَلَيْهِ ‏ ‏فَأَمَرَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَتَّخِذَ أَنْفًا مِنْ ذَهَبٍ ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏فَقِيلَ ‏ ‏لِأَبِي الْأَشْهَبِ ‏ ‏أَدْرَكْتَ ‏ ‏عَبْدَ الرَّحْمَنِ ‏ ‏جَدَّهُ ‏ ‏قَالَ ‏ ‏نَعَمْ ‏","","",""],[18236,18236,"","তার মামা হয়তো ঈশ্বরকে তাঁর পতাকার সঙ্গে দৃঢ়ভাবে কথা বলার সুযোগ পেয়ে খুশি হবেন এবং তিনি যা করবেন, তা ছেড়ে দেবেন তাই আমি সেই রহস্যটি স্মরণ করি, যা আমার দৃষ্টির আলোতে পরিণত হবে । ( গীতসংহিতা ৩৭: ১১) আপনি একই কাজ করেন এবং সেই আলো থেকে ভেসে চলে যাওয়ার ব্যথা অনুভব করেন এবং সেই গৌরবে ঢেকে রাখার জন্য আমি কখনোই আমার গৌরবের কাছে প্রার্থনা করতে পারি না ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ يَعْنِي ابْنَ صَالِحٍ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ يَعْنِي ابْنَ الْحَارِثِ ‏ ‏عَنْ ‏ ‏حَرَامِ بْنِ حَكِيمٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏عَبْدِ اللَّهِ بْنِ سَعْدٍ ‏ ‏أَنَّهُ ‏ ‏سَأَلَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَمَّا يُوجِبُ الْغُسْلَ وَعَنْ الْمَاءِ يَكُونُ بَعْدَ الْمَاءِ وَعَنْ الصَّلَاةِ فِي بَيْتِي وَعَنْ الصَّلَاةِ فِي الْمَسْجِدِ وَعَنْ مُؤَاكَلَةِ الْحَائِضِ فَقَالَ ‏ ‏إِنَّ اللَّهَ لَا ‏ ‏يَسْتَحْيِي مِنْ الْحَقِّ وَأَمَّا أَنَا فَإِذَا فَعَلْتُ كَذَا وَكَذَا فَذَكَرَ الْغُسْلَ قَالَ أَتَوَضَّأُ وُضُوئِي لِلصَّلَاةِ أَغْسِلُ فَرْجِي ثُمَّ ذَكَرَ الْغُسْلَ وَأَمَّا الْمَاءُ يَكُونُ بَعْدَ ‏ ‏الْمَاءِ ‏ ‏فَذَلِكَ ‏ ‏الْمَذْيُ ‏ ‏وَكُلُّ ‏ ‏فَحْلٍ ‏ ‏يُمْذِي ‏ ‏فَأَغْسِلُ مِنْ ذَلِكَ فَرْجِي وَأَتَوَضَّأُ وَأَمَّا الصَّلَاةُ فِي الْمَسْجِدِ وَالصَّلَاةُ فِي بَيْتِي فَقَدْ ‏ ‏تَرَى مَا أَقْرَبَ بَيْتِي مِنْ الْمَسْجِدِ وَلَأَنْ أُصَلِّيَ فِي بَيْتِي أَحَبُّ إِلَيَّ مِنْ أَنْ أُصَلِّيَ فِي الْمَسْجِدِ إِلَّا أَنْ تَكُونَ صَلَاةً مَكْتُوبَةً وَأَمَّا مُؤَاكَلَةُ الْحَائِضِ فَآكِلْهَا ‏","","",""],[18237,18237,"","আমরা নাবিকদের বাস করার কথা বলেছিলাম, ঈশ্বরের চাচার কাছে আমি খুশি যে আমি ঈশ্বরের কাছে প্রার্থনা করব, যেন তিনি তার জন্য কিছু জিনিস প্রদান করেন এবং কিছু কারণ জানতে পারেন।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ صَالِحٍ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏حَرَامِ بْنِ حَكِيمٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏عَبْدِ اللَّهِ بْنِ سَعْدٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ مُؤَاكَلَةِ الْحَائِضِ فَقَالَ وَاكِلْهَا ‏","","",""],[18238,18238,"","আমরা একটি ছেলে যে আমাদের কাছে করা থেকে ভাল করেছি যে কিভাবে আমি লর্ডকে নিয়ন্ত্রণ করতে পারি সে সম্পর্কে কথা বলেছি, ঈশ্বর তার শপথ নিয়েছেন এবং তিনি বলেছেন যে, তিনি করতে চান, আমার বাবার সাথে প্রেম।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏بَكْرُ بْنُ سَوَادَةَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ أَسْلَمَ مَوْلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏لِجَعْفَرِ بْنِ أَبِي طَالِبٍ ‏ ‏أَشْبَهْتَ خَلْقِي وَخُلُقِي ‏","","",""],[18239,18239,"","আমরা আমাদের আবেগ দিয়ে বাপ্তাইজিত হয়েছি আমার ছেলে আমার কাছে ফিরে এসেছে. যদি তুমি চেষ্টা করো, প্রতিবেশী হবে চেষ্টা করা, এমনকি আমাদের জীবনের চেয়েও শ্রেষ্ঠ ঈশ্বরের সাথে যা করার আছে, তার চেয়েও ভালো। সে বলল, আমরা চাই এটা হবে। আমরা চাই এটা হবে সবচেয়ে ভালো কাজ। আমরা যদি চাই, আমরা এটা করি, আমরা চাই। আমরা এটা করি, আমরা আমাদের জীবনের জন্য সবচেয়ে ভাল কিছু করতে পারি। যদি আমরা আমাদের জীবনের জন্য। এবং আমরা এটা করি, আমরা আমাদের জীবনের জন্য যা করি, তাহলে আমরা এর জন্য আমাদের কাছে এটা একটা ভাল উপায় আছে। আমরা যা চাই, তা হল, আমরা আমাদের জীবনের জন্য যা চাই, এবং আমরা এর থেকে অনেক বড় সুযোগ। আমরা শুধু চাই, আমরা যদি আমরা তা করি, তাহলে আমরা শুধু চাই। আমরা এটা হবে, আমরা শুধু একটা ভাল উপায়। আমরা যা করব। আমরা চাই, আমরা এর জন্য। আমরা যা করব তা হল, এবং আমরা চাই, তা হল আমাদের জীবনের জন্য যা করব। এটা আমাদের জীবনের জন্য। এটা হবে আমাদের জীবনের জন্য। এটা হবে আমাদের জীবনের জন্য। কিন্তু আমরা যা করব, এবং আমরা যা করব তা হবে, তা হবে, এবং আমরা শুধু আমাদের জীবনের জন্য। (হাততালি)","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ يَعْنِي الْجُرَيْرِيَّ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ عَبْدِ اللَّهِ بْنِ الشِّخِّيرِ ‏ ‏عَنْ ‏ ‏مَاعِزٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ سُئِلَ ‏ ‏أَيُّ الْأَعْمَالِ أَفْضَلُ قَالَ إِيمَانٌ بِاللَّهِ وَحْدَهُ ثُمَّ الْجِهَادُ ثُمَّ حَجَّةٌ بَرَّةٌ تَفْضُلُ سَائِرَ الْعَمَلِ كَمَا بَيْنَ مَطْلَعِ الشَّمْسِ إِلَى مَغْرِبِهَا ‏ ‏حَدَّثَنَا ‏ ‏هُدْبَةُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبُ بْنُ خَالِدٍ ‏ ‏عَنِ ‏ ‏الْجُرَيْرِيِّ ‏ ‏عَنْ ‏ ‏حَيَّانَ بْنِ عُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏مَاعِزٌ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُئِلَ أَيُّ الْأَعْمَالِ أَفْضَلُ ‏ ‏فَذَكَرَ نَحْوَهُ ‏","","",""],[18240,18240,"","আমি আমার সবচেয়ে ভাল ছবিগুলোর কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏عَبَّادُ بْنُ رَاشِدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْحَسَنَ ‏ ‏يَقُولُ ثَنَا ‏ ‏أَحْمَرُ بْنُ جَزِيٍّ صَاحِبُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنْ كُنَّا ‏ ‏لَنَأْوِي إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِمَّا ‏ ‏يُجَافِي ‏ ‏مِرْفَقَيْهِ عَنْ جَنْبَيْهِ إِذَا سَجَدَ ‏","","",""],[18241,18241,"","আমি শুনেছি যে আমি আমার বাবা-মা'র সাথে ছিলাম, যখন আমি তোমার কণ্ঠ শুনতে পেলাম, আমি তাকে \"আমি নই\" বলে বলতে শুনেছি। পানি থেকে পানি উদ্ধার করা হয়েছে.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ الزُّبَيْرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏كَثِيرُ بْنُ زَيْدٍ ‏ ‏عَنِ ‏ ‏الْمُطَّلِبِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عِتْبَانَ ‏ ‏أَوْ ‏ ‏ابْنِ عُتْبَانَ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏قُلْتُ أَيْ نَبِيَّ اللَّهِ ‏ ‏إِنِّي كُنْتُ مَعَ أَهْلِي فَلَمَّا سَمِعْتُ صَوْتَكَ أَقْلَعْتُ فَاغْتَسَلْتُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَاءُ مِنْ الْمَاءِ ‏","","",""],[18242,18242,"","আমি কয়েক জন লোকের সঙ্গে কথা বলেছিলাম, যারা বলে যে আমার বাবা হয়তো আমার কাছ থেকে তার নাম শুনতে পারেন । ঈশ্বর তাকে উদ্ধার করেছেন এবং বিখ্যাত খাদ্য সরবরাহ করেছেন, শিকারীদের মতো একই প্রভাবও তিনি দিয়েছেন । তার মত টর্ফের আগে কথা হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ مَعْرُوفٍ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏هَارُونَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ أَبِي حُرَّةَ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏حَكِيمِ بْنِ أَبِي حُرَّةَ ‏ ‏عَنْ ‏ ‏سِنَانِ بْنِ سَنَّةَ صَاحِبِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الطَّاعِمُ الشَّاكِرُ لَهُ مِثْلُ أَجْرِ الصَّائِمِ الصَّابِرِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَاه ‏ ‏أَحْمَدُ بْنُ حَاتِمٍ الطَّوِيلُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ الدَّرَاوَرْدِيُّ ‏ ‏مِثْلَهُ ‏","","",""],[18243,18243,"","আমরা আমাদের সময় রক্ষা করার চেষ্টা করেছি এবং তিনি আমাদের জীবন যুদ্ধের যুদ্ধ থেকে রক্ষা করার চেষ্টা করেছি, তিনি আমার বাবা কিন্তু আমি আমার চাচার সাথে বিবাহ বিচ্ছেদের ব্যাপারে তর্ক করছি। সুন্নী, এক বছর আগে, ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং আমার মন তার উপর চাপিয়ে দেবার জন্য নিজেকে সমর্পণ করেছেন।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ حَرْمَلَةَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ هِنْدٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏حَرْمَلَةَ بْنَ عَمْرٍو وَهُوَ أَبُو عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ ‏ ‏حَجَجْتُ حَجَّةَ الْوَدَاعِ ‏ ‏مُرْدِفِي ‏ ‏عَمِّي ‏ ‏سِنَانُ بْنُ سَنَّةَ ‏ ‏قَالَ فَلَمَّا وَقَفْنَا ‏ ‏بِعَرَفَاتٍ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاضِعًا إِحْدَى أُصْبُعَيْهِ عَلَى الْأُخْرَى فَقُلْتُ لِعَمِّي مَاذَا يَقُولُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ يَقُولُ ‏ ‏ارْمُوا الْجَمْرَةَ بِمِثْلِ حَصَى ‏ ‏الْخَذْفِ ‏","","",""],[18244,18244,"","আমরা চেষ্টা করে আমার ভাইকে তার চাচার সাথে বাইরে যেতে বলি, আমি তাকে বলেছি যে ঈশ্বরের কাছে আপনার টাকা আছে, আমি তাকে ভয় করি, সে যদি তার ঘোড়া পড়ে তাহলে একটা বালিশ দিতে পারত তার লড়াই শেষ হয় এবং এরপর সে তার লড়াই করে ।","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَخِي ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَبْدِ اللَّهِ بْنِ عُتْبَةَ بْنِ مَسْعُودٍ ‏ ‏أَنَّ ‏ ‏شَبْلَ بْنَ حَامِدٍ الْمُزَنِيَّ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ مَالِكٍ الْأَوْسِيَّ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لِلْوَلِيدَةِ ‏ ‏إِنْ زَنَتْ فَاجْلِدُوهَا ثُمَّ إِنْ زَنَتْ فَاجْلِدُوهَا ثُمَّ إِنْ زَنَتْ فَاجْلِدُوهَا ثُمَّ إِنْ زَنَتْ فَبِيعُوهَا وَلَوْ ‏ ‏بِضَفِيرٍ ‏ ‏وَالضَّفِيرُ ‏ ‏الْحَبْلُ فِي الثَّالِثَةِ ‏ ‏أَوْ فِي الرَّابِعَةِ ‏","","",""],[18245,18245,"","আমরা আমার ভালোবাসার মাখন নিয়ে কথা বলেছি, ঈশ্বর হয়ত আপনার টাকা দিয়ে শেষ করেছেন, তিনি তার টাকা হারতেন। প্রেমের সঙ্গে বিয়ে","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ عَبْدِ رَبِّهِ ‏ ‏حَدَّثَنَا ‏ ‏بَقِيَّةُ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنِي ‏ ‏الزُّبَيْدِيُّ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ ‏ ‏شِبْلَ بْنَ خُلَيْدٍ الْمُزَنِيَّ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ مَالِكٍ الْأَوْسِيَّ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لِلْوَلِيدَةِ ‏ ‏إِنْ زَنَتْ فَاجْلِدُوهَا ثُمَّ إِنْ زَنَتْ فَاجْلِدُوهَا ثُمَّ إِنْ زَنَتْ فَاجْلِدُوهَا ثُمَّ إِنْ زَنَتْ فَبِيعُوهَا وَلَوْ بِضَفِيرٍ وَالضَّفِيرُ الْحَبْلُ ‏","","",""],[18246,18246,"","আমরা দুই বছর ধরে একটা কুত্তার ছেলের সাথে কথা বলেছি, ঈশ্বরের আছে আর সে বলবে তুমি কখনো জিতে যাওনি... ...যখন সে বলেছিল যে তুমি আমার স্বপ্নের সিল্ক পশু.","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنِ ‏ ‏الْحَارِثِ بْنِ مَالِكٍ ابْنِ بَرْصَاءَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا ‏ ‏تُغْزَى ‏ ‏مَكَّةُ ‏ ‏بَعْدَهَا أَبَدًا ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏الْحَارِثُ خُزَاعِيٌّ ‏","","",""],[18247,18247,"","আমরা হারুনের কথা বলেছিলাম যে আমরা জাপিরকে টাকার সাথে যাত্রা করার জন্য জীবনের অর্থ নিয়ে কথা বলেছিলাম, যখন সে আমাকে বলল সে একটা কুত্তার বাচ্চা হবে। ক্ষমা করো তার গণনা শেষ হওয়ার পর তুমি কখনো জিততে পারবে না।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏زَكَرِيَّا ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏عَنِ ‏ ‏الْحَارِثِ بْنِ مَالِكٍ ابْنِ بَرْصَاءَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ يَوْمَ فَتْحِ ‏ ‏مَكَّةَ ‏ ‏لَا ‏ ‏تُغْزَى هَذِهِ بَعْدَهَا أَبَدًا إِلَى يَوْمِ الْقِيَامَةِ ‏","","",""],[18248,18248,"","আমি আমার দাদার সম্বন্ধে সবচেয়ে ভাল কিছু বলেছিলাম, যিনি ঈশ্বরের কাছে এসেছিলেন কিন্তু উত্তম প্রভু তাকে রক্ষা করেছেন । আমরা যদি যাই, আমরা না হই, আমরা আর যদি শক্তিশালী হই তাহলে আমাদের সাথে শক্তিশালী হতে হবে। শপথ করে বলো, তারপর আমরা শহরে যেতাম, এমনকি ডিনারের পরেও... ...আমরা কখনো আমার সাথে কথা বলতাম না। তিনি তার জন্য প্রার্থনা করেছেন এবং আত্মসমর্পণের জন্য প্রার্থনা করেছেন, যখন আমরা বলতে যাচ্ছি যে আমরা ছয়টি গোপন এবং ফিসফিস করে কথা বলি, এবং তারপর একের পর এক আগুনের মত গরমের দশ ভাগের এক ভাগ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عَبْدِ الرَّحْمَنِ الطَّائِفِيُّ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ عَبْدِ اللَّهِ بْنِ أَوْسٍ الثَّقَفِيِّ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَوْسِ بْنِ حُذَيْفَةَ ‏ ‏قَالَ ‏ ‏كُنْتُ فِي الْوَفْدِ الَّذِينَ أَتَوْا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَسْلَمُوا مِنْ ‏ ‏ثَقِيفٍ ‏ ‏مِنْ ‏ ‏بَنِي مَالِكٍ ‏ ‏أَنْزَلَنَا فِي ‏ ‏قُبَّةٍ ‏ ‏لَهُ فَكَانَ يَخْتَلِفُ إِلَيْنَا بَيْنَ بُيُوتِهِ وَبَيْنَ الْمَسْجِدِ فَإِذَا صَلَّى الْعِشَاءَ الْآخِرَةَ انْصَرَفَ إِلَيْنَا فَلَا ‏ ‏يَبْرَحُ ‏ ‏يُحَدِّثُنَا ‏ ‏وَيَشْتَكِي ‏ ‏قُرَيْشًا ‏ ‏وَيَشْتَكِي أَهْلَ ‏ ‏مَكَّةَ ‏ ‏ثُمَّ يَقُولُ لَا سَوَاءَ كُنَّا ‏ ‏بِمَكَّةَ ‏ ‏مُسْتَذَلِّينَ ‏ ‏أَوْ مُسْتَضْعَفِينَ ‏ ‏فَلَمَّا خَرَجْنَا إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏كَانَتْ ‏ ‏سِجَالُ ‏ ‏الْحَرْبِ عَلَيْنَا وَلَنَا فَمَكَثَ عَنَّا لَيْلَةً لَمْ يَأْتِنَا حَتَّى طَالَ ذَلِكَ عَلَيْنَا بَعْدَ الْعِشَاءِ قَالَ قُلْنَا مَا أَمْكَثَكَ عَنَّا يَا رَسُولَ اللَّهِ قَالَ ‏ ‏طَرَأَ عَنِّي حِزْبٌ مِنْ الْقُرْآنِ فَأَرَدْتُ أَنْ لَا أَخْرُجَ حَتَّى أَقْضِيَهُ فَسَأَلْنَا ‏ ‏أَصْحَابَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ أَصْبَحْنَا قَالَ قُلْنَا كَيْفَ ‏ ‏تُحَزِّبُونَ ‏ ‏الْقُرْآنَ قَالُوا ‏ ‏نُحَزِّبُهُ ‏ ‏سِتَّ سُوَرٍ وَخَمْسَ سُوَرٍ وَسَبْعَ سُوَرٍ وَتِسْعَ سُوَرٍ وَإِحْدَى عَشْرَةَ سُورَةً وَثَلَاثَ عَشْرَةَ سُورَةً وَحِزْبُ ‏ ‏الْمُفَصَّلِ ‏ ‏مِنْ ‏ ‏ق ‏ ‏حَتَّى تَخْتِمَ ‏","","",""],[18249,18249,"","আমি আমার বিশ্বাসের সর্বোত্তম দিক সম্বন্ধে পড়েছি: আপনার টাকাপয়সা হল করুণা দেখানোর একটা আদালতকে সাহায্য করা । পাঠক বলছে যে আমার প্রার্থনা রক্ষা পেয়েছে, আল্লাহ তার তৈরি করা যা দেখতে পাচ্ছেন, আর তাকে দেখাতে হবে না।","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ مَهْدِيٍّ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ التَّمَّارِّ ‏ ‏عَنِ ‏ ‏الْبَيَاضِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ عَلَى النَّاسِ وَهُمْ يُصَلُّونَ وَقَدْ عَلَتْ أَصْوَاتُهُمْ بِالْقِرَاءَةِ فَقَالَ ‏ ‏إِنَّ الْمُصَلِّي يُنَاجِي رَبَّهُ عَزَّ وَجَلَّ فَلْيَنْظُرْ مَا يُنَاجِيهِ وَلَا يَجْهَرْ بَعْضُكُمْ عَلَى بَعْضٍ بِالْقُرْآنِ ‏","","",""],[18250,18250,"","আমি আমার ছেলেকে সবচেয়ে ভাল করে বলেছিলাম যে, আমার বাবার সঙ্গে আমার সময়ের প্রমোদ হচ্ছে ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏وُهَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِي وَاقِدٍ اللَّيْثِيِّ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو أَرْوَى ‏ ‏قَالَ ‏ ‏كُنْتُ ‏ ‏أُصَلِّي مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْعَصْرَ ثُمَّ آتِي الشَّجَرَةَ قَبْلَ غُرُوبِ الشَّمْسِ ‏","","",""],[18251,18251,"","আমরা আমাদের দুজনের সাথে বিছানায় যাচ্ছি, বাবার ছেলে আমাদের কথা বলে। নারীবাদীদের কাছে ভাববাদী প্রার্থনা করেছেন, আত্মসমর্পণ করতে হবে এবং আত্মসমর্পণ করতে হবে। আমি মনে করি নি যে তারা বলেছে যে আমি কয়েক ঘন্টার জন্য তার উপর কাজ করছিলাম তাই চোর আমাকে মেরে ফেলতে পারে. চোরদের.","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجُ بْنُ النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏دَاوُدُ بْنُ أَبِي هِنْدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو حَرْبِ بْنُ أَبِي الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏فَضَالَةَ اللَّيْثِيِّ ‏ ‏قَالَ ‏ ‏أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَسْلَمْتُ وَعَلَّمَنِي حَتَّى عَلَّمَنِي الصَّلَوَاتِ الْخَمْسَ لِمَوَاقِيتِهِنَّ قَالَ فَقُلْتُ لَهُ إِنَّ هَذِهِ لَسَاعَاتٌ أُشْغَلُ فِيهَا فَمُرْنِي بِجَوَامِعَ فَقَالَ لِي ‏ ‏إِنْ شُغِلْتَ فَلَا تُشْغَلْ عَنْ الْعَصْرَيْنِ قُلْتُ وَمَا الْعَصْرَانِ قَالَ صَلَاةُ الْغَدَاةِ وَصَلَاةُ الْعَصْرِ ‏","","",""],[18252,18252,"","আমরা বেনের সাথে দেখা করতে যাব, নাকি তোমাকে খুঁজে বের করব, তার কথা শুনুন। ভাববাদী তার জন্য প্রার্থনা করলেন এবং তিনি বলবেন যে তার রক্ত আছে। আকাশের স্বর্গে স্বর্গ আর ভালোবাসা ছিল। তাকে রক্ষা করতে শেখানো হয়েছে।","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏قَالَ ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏أَخْبَرَنَا عَنْ ‏ ‏زُرَارَةَ بْنِ أَوْفَى ‏ ‏عَنْ ‏ ‏مَالِكِ بْنِ الْحَارِثِ ‏ ‏رَجُلٍ مِنْهُمْ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ ضَمَّ يَتِيمًا بَيْنَ أَبَوَيْنِ مُسْلِمَيْنِ إِلَى طَعَامِهِ وَشَرَابِهِ حَتَّى يَسْتَغْنِيَ عَنْهُ وَجَبَتْ لَهُ الْجَنَّةُ ‏ ‏الْبَتَّةَ ‏ ‏وَمَنْ أَعْتَقَ امْرَأً مُسْلِمًا كَانَ فَكَاكَهُ مِنْ النَّارِ ‏ ‏يُجْزِي بِكُلِّ عُضْوٍ مِنْهُ عُضْوًا مِنْهُ مِنْ النَّارِ ‏","","",""],[18253,18253,"","আমরা ইতোমধ্যে একজন আগন্তুক বা কুমারীর সাথে কথা বলেছি, আপনার টাকা হচ্ছে দুই বছর আগে সে ঈশ্বরকে বলে যে সে ঈশ্বরের কাছে এসেছে আর আমি কে!","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدِ بْنِ جُدْعَانَ ‏ ‏عَنْ ‏ ‏زُرَارَةَ بْنِ أَوْفَى ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مَالِكٍ ‏ ‏أَوْ ‏ ‏مَالِكِ بْنِ عَمْرٍو ‏ ‏كَذَا ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ ضَمَّ يَتِيمًا بَيْنَ أَبَوَيْهِ فَلَهُ الْجَنَّةُ ‏ ‏الْبَتَّةَ ‏","","",""],[18254,18254,"","আমরা আমাদের মনের মধ্যে শান্তি সৃষ ্ টি করেছি... ...যেটা আমাদের কাছে এসেছে... ...তার জন্য প্রার্থনা করেছে... আমি এটা টেনে নিয়ে যাচ্ছি, আমরা একটা আগন্তুক তোমার ব্যাপারে জানতে চাই","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏زُرَارَةَ بْنِ أَوْفَى ‏ ‏عَنْ ‏ ‏أُبَيِّ بْنِ مَالِكٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ أَدْرَكَ وَالِدَيْهِ أَوْ أَحَدَهُمَا ثُمَّ دَخَلَ النَّارَ مِنْ بَعْدِ ذَلِكَ فَأَبْعَدَهُ اللَّهُ وَأَسْحَقَهُ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏زُرَارَةَ بْنَ أَوْفَى ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أُبَيِّ بْنِ مَالِكٍ ‏ ‏عَنْ النَّبِيِّ ‏","","",""],[18255,18255,"","সে বললো আর আমাকে খেলার কথা বলেছিল, ছেলে বা মানুষ কে বেঁচে থাকতে পারে। তোমার টাকা হচ্ছে তার কাছে প্রার্থনা করা আর সে বলবে যে তুমি আর তার ছেলে কে? আমি তাদের যেতে দেব।","‏ ‏قَالَ ‏ ‏و حَدَّثَنِي ‏ ‏بَهْزٌ ‏ ‏قَالَ ثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏زُرَارَةَ بْنِ أَوْفَى ‏ ‏عَنْ ‏ ‏رَجُلٍ مِنْ قَوْمِهِ يُقَالُ لَهُ ‏ ‏أُبَيُّ بْنُ مَالِكٍ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ أَدْرَكَ وَالِدَيْهِ أَوْ أَحَدَهُمَا فَدَخَلَ النَّارَ فَأَبْعَدَهُ اللَّهُ ‏","","",""],[18256,18256,"","আমরা একটি কুয়াশার কথা বলেছি এবং তারপর আমরা একটি ছেলেকে বললাম যে তার সময় মারা গেছে। আমি আল্লাহ্‌ বলে যাচ্ছি, এটা সব কিছু। স্বপ্নের মানুষ যে এটা থেকে বেরিয়ে এসেছে, বছরটা ছিল দারুন সময়, সে ঈশ্বর এবং তার আত্মার কাছে করা প্রতিজ্ঞার জন্য ক্ষমা চায়নি।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا ثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏فِي حَدِيثِهِ ‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏زُرَارَةَ بْنِ أَوْفَى ‏ ‏عَنْ ‏ ‏مَالِكِ بْنِ عَمْرٍو الْقُشَيْرِيِّ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ أَعْتَقَ رَقَبَةً مُسْلِمَةً فَهِيَ فِدَاؤُهُ مِنْ النَّارِ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏مَكَانَ كُلِّ عَظْمٍ مِنْ عِظَامِ مُحَرِّرِهِ بِعَظْمٍ مِنْ عِظَامِهِ ‏ ‏وَمَنْ أَدْرَكَ أَحَدَ وَالِدَيْهِ ثُمَّ لَمْ يُغْفَرْ لَهُ فَأَبْعَدَهُ اللَّهُ وَمَنْ ضَمَّ يَتِيمًا مِنْ بَيْنِ أَبَوَيْنِ مُسْلِمَيْنِ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏إِلَى طَعَامِهِ وَشَرَابِهِ حَتَّى يُغْنِيَهُ اللَّهُ ‏ ‏وَجَبَتْ لَهُ الْجَنَّةُ ‏","","",""],[18257,18257,"","আমরা আমার ভালবাসার সাধারণ ভীতি নিয়ে কথা বলেছি, ঈশ্বর তাকে আত্মসমর্পণ করতে বলেছেন আর আমার ছেলেকে বললেন যে, তোমার ছেলে বলেছে আমরা জানি না সে কি। সে আমাকে ধোঁকা দিয়েছে। সে বলেছিল, \"আমি জানি না\" কিন্তু একবার সে বলেছিল।\" সে বলেছিল, \"আমি জানি না যে,\" আমি এটা জানি। আমি তাকে বলেছিলাম। আর আমি এটা জানি না যে, আমি তাকে বলেছিলাম, আমি তোমার জন্য বলছি, আমি এটা করতে চাই। আমি তোমার জন্য অনেক কষ্ট করে বলছি। আর আমার মনে হয় যে, আমি তোমার ছেলে এটা একটা প্রশ্ন করি। আর আমার ছেলে হবে যে তুমি আমাকে এটা করতে পারবে। আর তুমি আমার বাবা আমাকে এটা করতে পারবে না। আমি তোমার ছেলে হবে। আর আমি তোমার কাছে এটা করতে চাই না যে, আমি তোমার ছেলে যে তোমার ছেলে। আমি তোমার কাছে এটা একটা প্রশ্ন করে। আমার দুই ঘোড়া ছিল আমার বাবা মুক্ত ছিলেন।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏يُونُسُ بْنُ عُبَيْدٍ ‏ ‏عَنْ ‏ ‏حُصَيْنِ بْنِ أَبِي الْحُرِّ ‏ ‏عَنِ ‏ ‏الْخَشْخَاشِ الْعَنْبَرِيِّ ‏ ‏قَالَ ‏ ‏أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَعِي ابْنٌ لِي قَالَ فَقَالَ ابْنُكَ هَذَا قَالَ قُلْتُ نَعَمْ قَالَ ‏ ‏لَا ‏ ‏يَجْنِي عَلَيْكَ وَلَا ‏ ‏تَجْنِي عَلَيْهِ ‏ ‏قَالَ ‏ ‏هُشَيْمٌ ‏ ‏مَرَّةً ‏ ‏يُونُسُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مُخْبِرٌ ‏ ‏عَنْ ‏ ‏حُصَيْنِ بْنِ أَبِي الْحُرِّ ‏","","",""],[18258,18258,"","আমরা এক সুখী দম্পতি সম্বন্ধে কথা বলেছিলাম, যার মানে হল শহীদ হওয়া । ঈশ্বরের দয়ায় প্রার্থনা করতে, ঈশ্বরের দয়ায় এবং ঈশ্বরের দয়ায় প্রার্থনা করতে, লর্ডের অনুসন্ধান দ্বারা পরাজিত হবে এবং তার বালিশ ছিনিয়ে নেবে। সে বলছে, সে সবাই শপথ নিয়েছে, আমি একটু ঈর্ষান্বিত, নাকি আমার হিংসা হচ্ছে একজন নাতি-বধূর প্রতি, সেই তীব্র ঈর্ষা। \"না আমি বলতে চাচ্ছি, \"না আমি জানি না কিভাবে শুরু করতে হয়, অথবা যদি না বলি, \"আমি তাকে বলতে চাই, \"আমি তাকে হারাতে চাই না\"। ঈশ্বর তাকে একটা গোপন রহস্য ফিরিয়ে দিতে বলেছেন, তিনি প্রথমে জয়ের জন্য আসবেন।\" সকাল।","‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُهَاجِرٍ ‏ ‏يَعْنِي أَخَا ‏ ‏عَمْرِو بْنِ مُهَاجِرٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَقِيلُ بْنُ شَبِيبٍ ‏ ‏عَنْ ‏ ‏أَبِي وَهْبٍ الْجُشَمِيِّ ‏ ‏وَكَانَتْ لَهُ صُحْبَةٌ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَسَمَّوْا بِأَسْمَاءِ الْأَنْبِيَاءِ وَأَحَبُّ الْأَسْمَاءِ إِلَى اللَّهِ عَزَّ وَجَلَّ عَبْدُ اللَّهِ وَعَبْدُ الرَّحْمَنِ وَأَصْدَقُهَا حَارِثٌ وَهَمَّامٌ وَأَقْبَحُهَا حَرْبٌ وَمُرَّةُ ‏ ‏وَارْتَبِطُوا ‏ ‏الْخَيْلَ وَامْسَحُوا ‏ ‏بِنَوَاصِيهَا ‏ ‏وَأَعْجَازِهَا ‏ ‏أَوْ قَالَ ‏ ‏وَأَكْفَالِهَا ‏ ‏وَقَلِّدُوهَا ‏ ‏وَلَا ‏ ‏تُقَلِّدُوهَا ‏ ‏الْأَوْتَارَ ‏ ‏وَعَلَيْكُمْ بِكُلِّ ‏ ‏كُمَيْتٍ ‏ ‏أَغَرَّ ‏ ‏مُحَجَّلٍ ‏ ‏أَوْ أَشْقَرَ ‏ ‏أَغَرَّ ‏ ‏مُحَجَّلٍ ‏ ‏أَوْ ‏ ‏أَدْهَمَ ‏ ‏أَغَرَّ ‏ ‏مُحَجَّلٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُهَاجَرِ ‏ ‏حَدَّثَنَا ‏ ‏عَقِيلُ بْنُ شَبِيبٍ ‏ ‏عَنْ ‏ ‏أَبِي وَهْبٍ الْكَلَاعِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏ ‏قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏وَلَا أَدْرِي ‏ ‏بِالْكُمَيْتِ ‏ ‏بَدَأَ أَوْ ‏ ‏بِالْأَدْهَمِ ‏ ‏قَالَ وَسَأَلُوهُ لِمَ فَضَّلَ الْأَشْقَرَ قَالَ لِأَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعَثَ ‏ ‏سَرِيَّةً ‏ ‏فَكَانَ أَوَّلَ مَنْ جَاءَ بِالْفَتْحِ صَاحِبُ الْأَشْقَرِ ‏","","",""],[18259,18259,"","আমরা এমন একজনের প্রতি প্রবল আগ্রহ নিয়ে কথা বলেছি যে অল্প কিছু ক্ষতি করেছে। আমার বাবা এটা দিয়েছেন। দূরে গিয়ে বলতে চাই সে আমাকে গুলি করতে চায়নি, সে আমাকে মারতে চায়, কথা বলার চেয়ে সে ভাল।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ ‏ ‏سُئِلَ عَنْ رَجُلٍ يُسَلِّمُ عَلَيْهِ وَهُوَ غَيْرُ مُتَوَضِّئٍ ‏ ‏فَقَالَ ثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنِ ‏ ‏الْحُضَيْنِ أَبِي سَاسَانَ ‏ ‏عَنِ ‏ ‏الْمُهَاجِرِ بْنِ قُنْفُذٍ ‏ ‏أَنَّهُ سَلَّمَ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَتَوَضَّأُ فَلَمْ يَرُدَّ عَلَيْهِ حَتَّى تَوَضَّأَ فَرَدَّ عَلَيْهِ وَقَالَ إِنَّهُ ‏ ‏لَمْ يَمْنَعْنِي أَنْ أَرُدَّ عَلَيْكَ إِلَّا أَنِّي كَرِهْتُ أَنْ أَذْكُرَ اللَّهَ إِلَّا عَلَى طَهَارَةٍ ‏ ‏قَالَ ‏ ‏فَكَانَ ‏ ‏الْحَسَنُ ‏ ‏مِنْ أَجْلِ هَذَا الْحَدِيثِ يَكْرَهُ أَنْ يَقْرَأَ ‏ ‏أَوْ يَذْكُرَ اللَّهَ عَزَّ وَجَلَّ ‏ ‏حَتَّى يَتَطَهَّرَ ‏","","",""],[18260,18260,"","আমরা আমার প্রতিভার সেরাটা নিয়ে কথা বলেছি, কিন্তু ঈশ্বর তাকে রক্ষা করেছেন। আমি বরং তোমার মুখে কিছু করতে চাই, যদি তুমি সেরা ভাববাদী হও। ছয় জনের মধ্যে একজন থাকে। অনেক সময় ঋণ এবং অন্ধকারে তার আরেক ধরনের ঋণের কারণে তাকে এক সুন্দর, অন্ধকার, অন্ধকার, দুটি আশাবাদী মৃত্যু কখনো ঈশ্বরের সাথে শেয়ার করা হবে না। মনে হতো যেন লেখা ছিল, একটা লেখা ছিল, তুমি কিছু সময় পর এটা করতে পারো নি।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنِ ‏ ‏الرُّكَيْنِ بْنِ الرَّبِيعِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏فُلَانِ بْنِ عَمِيلَةَ ‏ ‏عَنْ ‏ ‏خُرَيْمِ بْنِ فَاتِكٍ الْأَسَدِيِّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏النَّاسُ أَرْبَعَةٌ وَالْأَعْمَالُ سِتَّةٌ فَالنَّاسُ مُوَسَّعٌ عَلَيْهِ فِي الدُّنْيَا وَالْآخِرَةِ وَمُوَسَّعٌ لَهُ فِي الدُّنْيَا ‏ ‏مَقْتُورٌ ‏ ‏عَلَيْهِ فِي الْآخِرَةِ ‏ ‏وَمَقْتُورٌ ‏ ‏عَلَيْهِ فِي الدُّنْيَا مُوَسَّعٌ عَلَيْهِ فِي الْآخِرَةِ وَشَقِيٌّ فِي الدُّنْيَا وَالْآخِرَةِ وَالْأَعْمَالُ ‏ ‏مُوجِبَتَانِ ‏ ‏وَمِثْلٌ بِمِثْلٍ وَعَشْرَةُ أَضْعَافٍ وَسَبْعُ مِائَةِ ضِعْفٍ ‏ ‏فَالْمُوجِبَتَانِ ‏ ‏مَنْ مَاتَ مُسْلِمًا مُؤْمِنًا لَا يُشْرِكُ بِاللَّهِ شَيْئًا فَوَجَبَتْ لَهُ الْجَنَّةُ وَمَنْ مَاتَ كَافِرًا وَجَبَتْ لَهُ النَّارُ وَمَنْ هَمَّ بِحَسَنَةٍ فَلَمْ يَعْمَلْهَا فَعَلِمَ اللَّهُ أَنَّهُ قَدْ أَشْعَرَهَا قَلْبَهُ وَحَرَصَ عَلَيْهَا كُتِبَتْ لَهُ حَسَنَةً وَمَنْ هَمَّ بِسَيِّئَةٍ لَمْ تُكْتَبْ عَلَيْهِ وَمَنْ عَمِلَهَا كُتِبَتْ وَاحِدَةً وَلَمْ تُضَاعَفْ عَلَيْهِ وَمَنْ عَمِلَ حَسَنَةً كَانَتْ لَهُ بِعَشْرِ أَمْثَالِهَا وَمَنْ أَنْفَقَ نَفَقَةً فِي سَبِيلِ اللَّهِ كَانَتْ لَهُ بِسَبْعِ مِائَةِ ضِعْفٍ ‏","","",""],[18261,18261,"","আমরা কথা বলেছিলাম কিভাবে তারা ঈশ্বর ও ঈশ্বরের মধ্যে পার্থক্য জয় করতে পারে... ...তোমাদের প্রভুর সাথে একটি কাজ করে... ...আর আমি কে. ( গীত.","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏حَدَّثَنَا ‏ ‏الرُّكَيْنُ بْنُ الرَّبِيعِ بْنِ عَمِيلَةَ الْفَزَارِيُّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏يُسَيْرِ بْنِ عَمِيلَةَ ‏ ‏عَنْ ‏ ‏خُرَيْمِ بْنِ فَاتِكٍ الْأَسَدِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَنْفَقَ نَفَقَةً فِي سَبِيلِ اللَّهِ كُتِبَتْ بِسَبْعِ مِائَةِ ضِعْفٍ ‏","","",""],[18262,18262,"","আমরা আমার বাবার কথা বলেছিলাম একটা অদ্ভুত চমকের কথা। তোমার রাজা আমাকে বলেছিলেন যে ঈশ্বর তাকে আত্মসমর্পণ করতে বলেছেন। আর তারা যা বলে, ঈশ্বর তা বলেন, আপনার ভ্রমণ এবং ভয় দেখিয়ে,","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ يَعْنِي ابْنَ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏شَمْرِ بْنِ عَطِيَّةَ ‏ ‏عَنْ ‏ ‏خُرَيْمِ بْنِ فَاتِكٍ الْأَسَدِيِّ ‏ ‏قَالَ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نِعْمَ الرَّجُلُ أَنْتَ يَا ‏ ‏خُرَيْمُ ‏ ‏لَوْلَا ‏ ‏خُلَّتَانِ ‏ ‏قَالَ قُلْتُ وَمَا هُمَا يَا رَسُولَ اللَّهِ قَالَ ‏ ‏إِسْبَالُكَ ‏ ‏إِزَارَكَ ‏ ‏وَإِرْخَاؤُكَ ‏ ‏شَعْرَكَ ‏","","",""],[18263,18263,"","আমরা সবাই বিয়ের কোয়ার্টারের ব্যাপারে কথা বলেছি, তোমার অসাধারণ ইচ্ছার জন্য, সে তার কাছে প্রার্থনা করেছে আর জিজ্ঞেস করেছে কার সাথে তার কার সময় কাটা হয়েছে সাতশ ব্যাঙের সাথে দেখা করতে পারিনি।","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ عَلِيٍّ ‏ ‏عَنْ ‏ ‏زَائِدَةَ ‏ ‏عَنِ ‏ ‏الرُّكَيْنِ بْنِ الرَّبِيعِ بْنِ عَمِيلَةَ الْفَزَارِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏يُسَيْرِ بْنِ عَمِيلَةَ ‏ ‏عَنْ ‏ ‏خُرَيْمِ بْنِ فَاتِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَنْفَقَ نَفَقَةً فِي سَبِيلِ ‏ ‏اللَّهِ تُضَاعَفُ بِسَبْعِ مِائَةِ ضِعْفٍ ‏","","",""],[18264,18264,"","আমরা আপনাদের কাজ করার জন্য একজন ভাল বাবা হওয়ার কথা বলেছিলাম। ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং ছয় বছর বয়সী একজন মানুষকে আত্মসমর্পণ করেছেন। আর এই বছর সাত বার সাত বার। জেলে আপনার সাথে শেয়ার করতে অনেক ব্যস্ত ছিল, অথবা তাদের মত তারা এটা কিভাবে করতে হবে তা শিখতে হবে। তিনি খারাপ সময় এবং তার জীবনে একটি সময় অতিবাহিত করেছেন। তিনি একটি চিঠি লিখেছেন। ( প্রকাশিত বাক্য ৭: ৯, ১০) তার রক্তে ঐশিক সংগীত ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنِ ‏ ‏الرُّكَيْنِ بْنِ الرَّبِيعِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏خُرَيْمِ بْنِ فَاتِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْأَعْمَالُ سِتَّةٌ وَالنَّاسُ أَرْبَعَةٌ ‏ ‏فَمُوجِبَتَانِ ‏ ‏وَمِثْلٌ بِمِثْلٍ وَالْحَسَنَةُ بِعَشْرِ أَمْثَالِهَا وَالْحَسَنَةُ بِسَبْعِ مِائَةٍ فَأَمَّا ‏ ‏الْمُوجِبَتَانِ ‏ ‏مَنْ مَاتَ لَا يُشْرِكُ بِاللَّهِ شَيْئًا دَخَلَ الْجَنَّةَ وَمَنْ مَاتَ يُشْرِكُ بِاللَّهِ شَيْئًا دَخَلَ النَّارَ وَأَمَّا مِثْلٌ بِمِثْلٍ فَمَنْ هَمَّ بِحَسَنَةٍ حَتَّى يُشْعِرَهَا قَلْبَهُ وَيَعْلَمُ اللَّهُ عَزَّ وَجَلَّ ذَلِكَ مِنْهُ كُتِبَتْ لَهُ حَسَنَةً وَمَنْ عَمِلَ سَيِّئَةً كُتِبَتْ عَلَيْهِ سَيِّئَةً وَمَنْ عَمِلَ حَسَنَةً كُتِبَتْ لَهُ بِعَشْرِ أَمْثَالِهَا وَمَنْ أَنْفَقَ نَفَقَةً فِي سَبِيلِ اللَّهِ فَحَسَنَةٌ بِسَبْعِ مِائَةٍ وَالنَّاسُ أَرْبَعَةٌ مُوَسَّعٌ عَلَيْهِ فِي الدُّنْيَا ‏ ‏مَقْتُورٌ ‏ ‏عَلَيْهِ فِي الْآخِرَةِ وَمُوَسَّعٌ عَلَيْهِ فِي الْآخِرَةِ ‏ ‏مَقْتُورٌ ‏ ‏عَلَيْهِ فِي الدُّنْيَا وَمُوَسَّعٌ عَلَيْهِ فِي الدُّنْيَا وَالْآخِرَةِ ‏ ‏وَمَقْتُورٌ ‏ ‏عَلَيْهِ فِي الدُّنْيَا وَالْآخِرَةِ ‏","","",""],[18265,18265,"","আমরা একটা আবেগ নিয়ে কথা বলেছি যা আমাদের দুঃখকে সহ্য করতে সাহায্য করেছে, ঈশ্বরের কাছে প্রার্থনা করছি তার জন্য এবং একবার অন্ত্যেষ্টিক্রিয়ার সময় তিনি তার জন্য একটি শেষকৃত্য বিতরণ করেছেন।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الشَّعْبِيَّ ‏ ‏قَالَ أَشْهَدُ عَلَى ‏ ‏أَبِي سَعِيدِ بْنِ زَيْدٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّتْ بِهِ جِنَازَةٌ فَقَامَ ‏","","",""],[18266,18266,"","আমি কিভাবে কথা বলতে পারি সে বিষয়ে আমি তর্ক করেছি, ঈশ্বর আমার ফোনকে ঈশ্বরের কাছে পৌঁছে দিয়েছেন।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ أَوْسٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏حَدَّثَهُ ‏ ‏مُؤَذِّنُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏نَادَى مُنَادِي رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي يَوْمٍ مَطِيرٍ ‏ ‏صَلُّوا فِي ‏ ‏الرِّحَالِ ‏","","",""],[18267,18267,"","আমরা আমার শ্বশুর আব্বার কথা বলেছিলাম যখন আমার ভাই তাকে বলেছিল, তাকে সেই বইগুলোর ছায়ার জন্য সান্ত্বনা প্রদান করুন, যা তিনি তাকে বলেছিলেন যে তিনি ঈশ্বরের সাথে বাইরে গেছেন। পুত্র-ব্লাড বলেছে আমার শ্বশুর আব্বাকে বলছি, আমি আমার ভাইয়ের মত তাকে খুঁজতে গিয়ে আমার ভাইকে বলেছি, ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তিনি তার স্মৃতি সমর্পণ করেছেন। অন্য সময়ে আমরা গরীবদের চোখে ফিরে যাবো। আমার বড় বাবা বলেছিলেন, আমার দাদা আমার ভাইয়ের সাথে প্রভুর ছায়াতে কথা বললেন, ঈশ্বরের অনুগ্রহের সাথে যাও। আর তাকে এক সময় বিনা মূল্যে উদ্ধার করা হবে.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أُخْبِرْتُ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏حَدَّثَنِي ‏ ‏مُرَقِّعُ بْنُ صَيْفِيٍّ التَّمِيمِيُّ ‏ ‏شَهِدَ عَلَى ‏ ‏جَدِّهِ ‏ ‏رِيَاحِ بْنِ رُبَيِّعٍ الْحَنْظَلِيِّ الْكَاتِبِ ‏ ‏أَنَّهُ أَخْبَرَهُ ‏ ‏أَنَّهُ خَرَجَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مِثْلَ حَدِيثِ ‏ ‏ابْنِ أَبِي الزِّنَادِ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏قَالَ ثَنَا ‏ ‏الْمُغِيرَةُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏الْمُرَقِّعُ بْنُ صَيْفِيٍّ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏رِيَاحِ بْنِ رُبَيِّعٍ ‏ ‏أَخِي ‏ ‏حَنْظَلَةَ الْكَاتِبِ ‏ ‏أَنَّهُ أَخْبَرَهُ ‏ ‏أَنَّهُ خَرَجَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ مَنْصُورٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْمُغِيرَةُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُرَقِّعُ بْنُ صَيْفِيٍّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏جَدِّي ‏ ‏رِيَاحُ بْنُ رُبَيِّعٍ ‏ ‏أَخِي ‏ ‏حَنْظَلَةَ الْكَاتِبِ ‏ ‏أَنَّهُ خَرَجَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي غَزَاةٍ عَلَى مُقَدِّمَتِهِ ‏ ‏خَالِدُ بْنُ الْوَلِيدِ ‏ ‏فَذَكَرَ رِيَاحًا وَأَصْلَهُ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[18268,18268,"","ঈশ্বর তাঁর জন্য প্রার্থনা করেছেন এবং যতক্ষণ না পর্যন্ত না পর্যন্ত আমরা আকাশে ও আগুনে আমাদের ঠিকানা দেব, ততক্ষণ পর্যন্ত তিনি আমাদের সমর্পণ করবেন আমি কখনো ঈশ্বরের কাছে তার দেখা সুযোগ পাইনি। সে বলেছিল, যদি আমি বলি আমরা লর্ডের ইচ্ছা পালন করতাম, সে যদি চলে যেত এবং আমরা মারা যেতাম। আমি তো মরে যেতাম। আমার ছেলের সাথে খেলা শুধু আমি বলবো আমরা এটা করবো না, যদি তুমি তোমার দুর্দশায় থাকো, এক ঘন্টা আর এক ঘন্টা সময় লাগবে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ الزُّبَيْرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْجُرَيْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ ‏ ‏عَنْ ‏ ‏حَنْظَلَةَ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرْنَا الْجَنَّةَ وَالنَّارَ حَتَّى كَانَا رَأْيَ عَيْنٍ فَقُمْتُ إِلَى أَهْلِي فَضَحِكْتُ وَلَعِبْتُ مَعَ أَهْلِي وَوَلَدِي فَذَكَرْتُ مَا كُنْتُ عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَخَرَجْتُ فَلَقِيتُ ‏ ‏أَبَا بَكْرٍ ‏ ‏فَقُلْتُ يَا ‏ ‏أَبَا بَكْرٍ ‏ ‏نَافَقَ ‏ ‏حَنْظَلَةُ ‏ ‏قَالَ وَمَاذَاكَ ذَاكَ قُلْتُ كُنَّا عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرْنَا الْجَنَّةَ وَالنَّارَ حَتَّى كَانَا رَأْيَ عَيْنٍ فَذَهَبْتُ إِلَى أَهْلِي فَضَحِكْتُ وَلَعِبْتُ مَعَ وَلَدِي وَأَهْلِي فَقَالَ إِنَّا لَنَفْعَلُ ذَاكَ قَالَ فَذَهَبْتُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرْتُ ذَلِكَ لَهُ فَقَالَ يَا ‏ ‏حَنْظَلَةُ ‏ ‏لَوْ كُنْتُمْ تَكُونُونَ فِي بُيُوتِكُمْ كَمَا تَكُونُونَ عِنْدِي لَصَافَحَتْكُمْ الْمَلَائِكَةُ وَأَنْتُمْ عَلَى فُرُشِكُمْ وَبِالطُّرُقِ يَا ‏ ‏حَنْظَلَةُ ‏ ‏سَاعَةً وَسَاعَةً ‏","","",""],[18269,18269,"","আমরা পাইলটদের সাথে কথা বলেছি, প্রভু, ঈশ্বর তাঁর জন্য প্রার্থনা করেছেন এবং আমরা আত্মসমর্পণ করব. যদি আপনি আমাদের কাজ করা উচিত. আমরা কি কি করা উচিত তা ভাল. আপনি ভাল. আমরা কি ভাল. আপনি ভাল. আমরা কি কি করা উচিত. আপনি ভাল. আপনি ভাল. আপনি ভাল. আমরা কি কি করা উচিত. আমরা কি. আমরা ভাল কাজ করা উচিত. আপনি ভাল. আমরা কি কি. আমরা ভাল. তার কাছে, যদি তোমাকে যেতে হয়, সে পাগল হয়ে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو دَاوُدَ الطَّيَالِسِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عِمْرَانُ يَعْنِي الْقَطَّانَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ عَبْدِ اللَّهِ بْنِ الشِّخِّيرِ ‏ ‏عَنْ ‏ ‏حَنْظَلَةَ الْأُسَيِّدِيِّ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّا إِذَا كُنَّا عِنْدَكَ كُنَّا فَإِذَا فَارَقْنَاكَ كُنَّا عَلَى غَيْرِ ذَلِكَ فَقَالَ وَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏لَوْ كُنْتُمْ تَكُونُونَ عَلَى الْحَالِ الَّذِي تَكُونُونَ عَلَيْهَا عِنْدِي لَصَافَحَتْكُمْ الْمَلَائِكَةُ وَلَأَظَلَّتْكُمْ بِأَجْنِحَتِهَا ‏","","",""],[18270,18270,"","আমরা একে অপরের বাবা-মা'র কথা বলেছি, কিন্তু ঈশ্বর হয়তো ঈশ্বরের পুত্র জিতে গেছেন। তিনি আমাদের মন পরিবর্তন করেছেন যেন তিনি ঈশ্বরের কাছে প্রার্থনা করেন। তিনি এই ঋতুর কথা বলতে পারেন অথবা সবচেয়ে দ্রুত। ঈশ্বর পর্দা ক্ষমা করতে পারবেন না এবং পৃথিবীর অধিকাংশ অংশকেই ক্ষমা করতে পারবেন না। ঈশ্বরের সেবা, ঈশ্বর তাকে উদ্ধার করেছেন এবং তিনি যখন কথা বলেছিলেন আমি আমার ছেলের কাছ থেকে আপনার টাকা ভুলে যাব, ঈশ্বর তাকে দাবি করেছেন এবং তাকে যা করতে বলা হয়েছে, তার কথা বলা হয়েছে। সে বলল যে খোদা আর সে এটা বলেছে, সে আবার এমন করবে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو هِلَالٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ سَوَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏رَجُلٍ مِنْ ‏ ‏بَنِي عَبْدِ اللَّهِ بْنِ كَعْبٍ ‏ ‏قَالَ ‏ ‏أَغَارَتْ ‏ ‏عَلَيْنَا خَيْلُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَتَيْتُهُ وَهُوَ يَتَغَدَّى فَقَالَ ادْنُ فَكُلْ قُلْتُ إِنِّي صَائِمٌ قَالَ اجْلِسْ أُحَدِّثْكَ عَنْ الصَّوْمِ ‏ ‏أَوْ الصِّيَامِ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ وَضَعَ عَنْ الْمُسَافِرِ ‏ ‏شَطْرَ ‏ ‏الصَّلَاةِ وَعَنْ الْمُسَافِرِ وَالْحَامِلِ وَالْمُرْضِعِ الصَّوْمَ ‏ ‏أَوْ الصِّيَامَ وَاللَّهِ لَقَدْ قَالَهُمَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كِلَاهُمَا أَوْ أَحَدُهُمَا ‏ ‏فَيَا لَهْفَ نَفْسِي هَلَّا كُنْتُ طَعِمْتُ مِنْ طَعَامِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو هِلَالٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ سَوَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏رَجُلٍ مِنْ ‏ ‏بَنِي عَبْدِ اللَّهِ بْنِ كَعْبٍ ‏ ‏وَلَيْسَ بِالْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏أَغَارَتْ ‏ ‏عَلَيْنَا خَيْلُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏و حَدَّثَنَاه ‏ ‏شَيْبَانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو هِلَالٍ ‏ ‏قَالَ ‏ ‏فَذَكَرَ نَحْوَهُ ‏","","",""],[18271,18271,"","আমি আমার প্রিয় জায়নের চেয়ে ভাল ছেলে হওয়ার কথা বলেছি, আমি আমার বাবার সাথে বাস করব, একজন ভালো মানুষ যে বলেছিল আমি ভাববাদীকে শুনেছি, ঈশ্বরের নিজের আর আমার ছেলে আছে এটা বলতে পারবে না সে খুবই ভয় পেয়েছে, তারা এটা করার অধিকার রাখে যাতে তারা এটা তার হাতে রেখে দেয়। আমাদের পরবর্তী ছেলের উপর আমাদের দায়িত্ব অর্পণ করতে হবে, কিন্তু আমরা কথা বলেছি। আমার বাবার বাসা আমাকে দয়া করে বলেছিল আর তিনি যেভাবে তার কাজ করতেন, সেভাবে তার স্মৃতিও তুলে ধরেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏الْحُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏وَيَزِيدُ بْنُ عَطَاءٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ يَعْنِي ابْنَ أَبِي زِيَادٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ سَابِطٍ ‏ ‏عَنْ ‏ ‏عَيَّاشِ بْنِ أَبِي رَبِيعَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا تَزَالُ هَذِهِ الْأُمَّةُ بِخَيْرٍ مَا عَظَّمُوا هَذِهِ الْحُرْمَةَ حَقَّ تَعْظِيمِهَا فَإِذَا تَرَكُوهَا وَضَيَّعُوهَا هَلَكُوا ‏ ‏وَقَالَ ‏ ‏فِي حَدِيثِ ‏ ‏يَزِيدَ بْنِ عَطَاءٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ ‏ ‏عَنِ ‏ ‏ابْنِ سَابِطٍ ‏ ‏عَنِ ‏ ‏الْمُطَّلِبِ ‏ ‏أَوْ ‏ ‏عَنِ ‏ ‏الْعَيَّاشِ بْنِ أَبِي رَبِيعَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[18272,18272,"","আমি একে অপরের কথা বলেছি, কিন্তু আমি যাচ্ছি না। কিন্তু, ঈশ্বর বধিরদের সমর্পণ করতে হবে। কারণ তিনি আমাকে বলেছেন, তিনি আমাকে বলেছেন, এটা বলা ভালো। আমি বলবো, এটা বলার জন্য, এটা সব শেষ। আমি জানি, আমি জানি, আমি যদি আমার কাছে এটা করি, আমি এটা করতে পারি, আমি কিন্তু আমি এটা করতে চাই, আমি কিন্তু আমি জানি, আমি জানি, আমি যদি আমি এটা করতে চাই, আমি এটা আমার কাছে একটা সহজ। কিন্তু আমি মনে করি, আমি যদি আমি এটা শুনতে চাই, আমি এটা আমার কাছে এটা একটা সহজ। কিন্তু আমি শুধু একটা প্রশ্ন করি, আমি যদি আমি এটা করতে চাই, আমি শুধু একটা জিনিস, আমি চাই। কিন্তু আমি শুধু একটা ছোট কাজ করি। কিন্তু আমি যদি আমার কাছে এটা একটা প্রশ্ন করি, আমি শুধু একটা জিনিস, আমি শুধু একটা জিনিস। কিন্তু আমি শুধু একটা প্রশ্ন করি। কিন্তু আমি চাই, আমি যদি আমি চাই, আমি শুধু একটা ছোট ছোট ছোট কাজ করি, মাসখানেক আগে, প্রতি মাসে আমাকে তিন দিনের সরবরাহ দেয়া হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَسْوَدُ بْنُ شَيْبَانَ ‏ ‏عَنْ ‏ ‏أَبِي نَوْفَلِ بْنِ أَبِي عَقْرَبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الصَّوْمِ فَقَالَ ‏ ‏صُمْ مِنْ الشَّهْرِ يَوْمًا قَالَ قُلْتُ يَا رَسُولَ اللَّهِ إِنِّي أَقْوَى فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي أَقْوَى إِنِّي أَقْوَى صُمْ يَوْمَيْنِ مِنْ كُلِّ شَهْرٍ قَالَ قُلْتُ يَا رَسُولَ اللَّهِ زِدْنِي فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏زِدْنِي زِدْنِي ثَلَاثَةَ أَيَّامٍ مِنْ كُلِّ شَهْرٍ ‏","","",""],[18273,18273,"","আমি ঈশ্বরকে খোঁজার জন্য তাদের কাছে ফিরে যেতে বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏مَكِّيُّ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏الْجَعْدُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ ‏ ‏عَمْرَو بْنَ عُبَيْدِ اللَّهِ ‏ ‏حَدَّثَهُ أَنَّهُ قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَكَلَ كَتِفًا ثُمَّ قَامَ فَمَضْمَضَ فَصَلَّى وَلَمْ يَتَوَضَّأْ ‏","","",""],[18274,18274,"","আমরা ইতিমধ্যেই তার বাবার সাথে একটা ছেলের কথা বলেছি... ...তাকে ঈশ্বরের কাছে জিজ্ঞেস করা হয়েছে, তুমি তাকে তিন বার মনে রাখবে... সে.","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏زَمْعَةُ ‏ ‏عَنْ ‏ ‏عِيسَى بْنِ يَزْدَادَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا بَالَ أَحَدُكُمْ ‏ ‏فَلْيَنْتُرْ ‏ ‏ذَكَرَهُ ثَلَاثًا ‏ ‏قَالَ ‏ ‏زَمْعَةُ ‏ ‏مَرَّةً فَإِنَّ ذَلِكَ يُجْزِئُ عَنْهُ ‏","","",""],[18275,18275,"","আমরা একজন ভদ্রলোকের সাথে কথা বলেছি যে কিনা আসবে না। ঈশ্বর তার কথা কখনো তিন বার বলে দিয়েছেন।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عِيسَى بْنِ يَزْدَادَ بْنِ فَسَاءَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا بَالَ أَحَدُكُمْ ‏ ‏فَلْيَنْتُرْ ‏ ‏ذَكَرَهُ ثَلَاثَ مَرَّاتٍ ‏","","",""],[18276,18276,"","আমি ঈশ্বরের জন্য আমার বাবার ছেলের কথা বলেছি, ঈশ্বরের জন্য আমার ছেলেকে প্রমাণ করতে, আমি আল্লাহ্‌র কাছে প্রার্থনা করেছি, সে তাকে জানত এবং সে কোন জায়গা বা আগুন জ্বালিয়ে পড়তে পারে। আগুন জ্বেলে.","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏ثَابِتٍ الْبُنَانِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏أَبِي لَيْلَى ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَأُ فِي صَلَاةٍ لَيْسَتْ بِفَرِيضَةٍ فَمَرَّ بِذِكْرِ الْجَنَّةِ وَالنَّارِ فَقَالَ ‏ ‏أَعُوذُ بِاللَّهِ مِنْ النَّارِ وَيْحٌ ‏ ‏أَوْ وَيْلٌ ‏ ‏لِأَهْلِ النَّارِ ‏","","",""],[18277,18277,"","আমি বাবার ছেলের কাছে বলেছি, তার ভাইয়ের কাছে লর্ডের পালনকরের চেয়ে তার ভাইয়ের কাছে প্রার্থনা করার বদলে। লর্ড তার জন্য প্রার্থনা করেছিলেন এবং তিনি তার চেয়ে ভালো কিছুর জন্য আত্মসমর্পণ করবেন। সে চলে যাওয়ার পর আমি তাকে তার কাছে প্রার্থনা করতে বলছি না... ...আর আমার ছেলে তার সাথে প্রার্থনা করবে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏أَخِيهِ ‏ ‏عِيسَى بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏كُنَّا عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَجَاءَ ‏ ‏الْحَسَنُ بْنُ عَلِيٍّ ‏ ‏يَحْبُو حَتَّى صَعِدَ عَلَى صَدْرِهِ فَبَالَ عَلَيْهِ قَالَ ‏ ‏فَابْتَدَرْنَاهُ ‏ ‏لِنَأْخُذَهُ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ابْنِي ابْنِي قَالَ ثُمَّ دَعَا بِمَاءٍ فَصَبَّهُ عَلَيْهِ ‏","","",""],[18278,18278,"","আমরা একটি ভাল বছর থাকার কথা বলেছি কিন্তু আমার ছেলের প্রতি আমার ক্ষমা থাকতে হবে। ঈশ্বরের কাছে এটা তার ইচ্ছা। প্রার্থনা করি আমার ছেলেকেও মেরে ফেলবে না। আমি তাকে এর মধ্যে দিয়ে দিলাম।","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عِيسَى ‏ ‏عَنْ ‏ ‏عِيسَى بْنِ عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏أَبِي لَيْلَى ‏ ‏أَنَّهُ ‏ ‏كَانَ عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَلَى بَطْنِهِ ‏ ‏الْحَسَنُ ‏ ‏أَوْ ‏ ‏الْحُسَيْنُ ‏ ‏شَكَّ ‏ ‏زُهَيْرٌ ‏ ‏قَالَ فَبَالَ حَتَّى رَأَيْتُ بَوْلَهُ عَلَى بَطْنِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَسَارِيعَ ‏ ‏قَالَ ‏ ‏فَوَثَبْنَا ‏ ‏إِلَيْهِ قَالَ فَقَالَ ‏ ‏عَلَيْهِ الصَّلَاة وَالسَّلَامُ ‏ ‏دَعُوا ابْنِي ‏ ‏أَوْ لَا تُفْزِعُوا ابْنِي ‏ ‏قَالَ ثُمَّ دَعَا بِمَاءٍ فَصَبَّهُ عَلَيْهِ قَالَ فَأَخَذَ تَمْرَةً مِنْ تَمْرِ ‏ ‏الصَّدَقَةِ ‏ ‏قَالَ فَأَدْخَلَهَا فِي ‏ ‏فِيهِ قَالَ فَانْتَزَعَهَا رَسُولُ اللَّهِ مِنْ ‏ ‏فِيهِ ‏","","",""],[18279,18279,"","আমরা আমার প্রিয় ছেলের কথা বলেছি, কিন্তু আমরা আমার বাবার জন্য ঈশ্বরের জন্য কাজ করেছি। ঈশ্বরের কাছে আমার বাবার আশীর্বাদ প্রার্থনা করছি। ঈশ্বর তাকে মৃত্যুর পরিণতির বিষয়ে বলতে বলেছিলেন, যা আমাদেরকে জগতের দশ ভাগের এক ভাগ ভাগ করে দিয়েছে ।","‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ عَدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَبِي أُنَيْسَةَ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏شَهِدْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَتْحَ ‏ ‏خَيْبَرَ ‏ ‏فَلَمَّا انْهَزَمُوا وَقَعْنَا فِي ‏ ‏رِحَالِهِمْ ‏ ‏فَأَخَذَ النَّاسُ مَا وَجَدُوا مِنْ ‏ ‏خُرْثِيٍّ ‏ ‏فَلَمْ يَكُنْ أَسْرَعَ مِنْ أَنْ ‏ ‏فَارَتْ ‏ ‏الْقُدُورُ قَالَ ‏ ‏فَأَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْقُدُورِ ‏ ‏فَأُكْفِئَتْ ‏ ‏وَقَسَمَ بَيْنَنَا فَجَعَلَ لِكُلِّ عَشَرَةٍ شَاةً ‏","","",""],[18280,18280,"","আমরা ঈশ্বরের কাছে আমার বাবার চেয়ে ভালো কিছু করেছি, আমি প্রভু তার কাছে প্রার্থনা করেছি এবং তিনি তার ভাগ্য বা তার দেশকে রক্ষা করতে পারতেন. আমি তার জন্য ভাল. আমি. আমি. আমি. আমি আমার বাবার কাছে আমার বাবার কাছে প্রার্থনা করেছি. আমি আমার পিতা. আমি তার কাছে প্রার্থনা করেছি. আমি তার কাছে প্রার্থনা করা উচিত. আমি. আমি. আমি. আমি. আমি. আমি. আমি. আমি. আমি. আমি. আমি. তাকে মেরে ফেলতে সাহায্য করবে, আমার ছেলে তাকে উড়িয়ে না দিতে দাও যতক্ষণ না সে তাকে ফেলে দেয়, সে মেঘের সাথে চলে যায়, সে দৌড়ে যায়, তাকে তার অনুসন্ধানের এক অন্যতম কারণ হিসেবে, তাকে উদ্ধার করতে হয়। স্ক্রিপ্ট থেকে বের হয়ে ঈশ্বরের কাছে প্রার্থনা কর, তুমি আমাদের সমাধান করতে চাচ্ছ।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عِيسَى ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏عَنْ ‏ ‏أَبِي لَيْلَى ‏ ‏قَالَ ‏ ‏كُنْتُ عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَلَى صَدْرِهِ ‏ ‏أَوْ بَطْنِهِ ‏ ‏الْحَسَنُ ‏ ‏أَوْ ‏ ‏الْحُسَيْنُ ‏ ‏قَالَ فَرَأَيْتُ بَوْلَهُ ‏ ‏أَسَارِيعَ ‏ ‏فَقُمْنَا إِلَيْهِ فَقَالَ ‏ ‏دَعُوا ابْنِي لَا تُفْزِعُوهُ حَتَّى يَقْضِيَ بَوْلَهُ ثُمَّ أَتْبَعَهُ الْمَاءَ ثُمَّ قَامَ فَدَخَلَ بَيْتَ تَمْرِ ‏ ‏الصَّدَقَةِ ‏ ‏وَدَخَلَ مَعَهُ الْغُلَامُ فَأَخَذَ تَمْرَةً فَجَعَلَهَا فِي ‏ ‏فِيهِ فَاسْتَخْرَجَهَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ إِنَّ ‏ ‏الصَّدَقَةَ ‏ ‏لَا تَحِلُّ لَنَا ‏","","",""],[18281,18281,"","আমরা ইশ্বরের সাথে কথা বলেছি, তার ছেলেও নেই, কিন্তু আমার বাবাও কখনো কখনো তার ছেলের কথা শোনেননি। আমার বাবার ছেলে সবসময় বলতো, আমি আমার বাবার সবচেয়ে ভালো ছেলের হিরো। সূর্যয় পাওয়া গৌরবের মধ্যে পাওয়া যায় । আত্মা বলেছে যখন তামাক বলা হয়,","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ هَاشِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏قَالَ ‏ ‏كُنْتُ جَالِسًا مَعَ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏فِي الْمَسْجِدِ فَأُتِيَ بِرَجُلٍ ضَخْمٍ فَقَالَ يَا ‏ ‏أَبَا عِيسَى ‏ ‏قَالَ نَعَمْ قَالَ حَدِّثْنَا مَا سَمِعْتَ فِي الْفِرَاءِ فَقَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏يَقُولُ كُنْتُ جَالِسًا عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَتَى رَجُلٌ فَقَالَ يَا رَسُولَ اللَّهِ ‏ ‏أُصَلِّي فِي الْفِرَاءِ قَالَ فَأَيْنَ ‏ ‏الدِّبَاغُ ‏ ‏فَلَمَّا وَلَّى قُلْتُ مَنْ هَذَا قَالَ هَذَا ‏ ‏سُوَيْدُ بْنُ غَفَلَةَ ‏","","",""],[18282,18282,"","তার বাবার কাছে যখন একটা মশার বিষয়ে আমি জানি, তখন ভাববাদী আপনার সাহায্য পেয়েছিলেন ওয়ারড্রি.","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَابِسٍ ‏ ‏عَنْ ‏ ‏أَبِي فَزَارَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏فِيمَا أَعْلَمُ شَكَّ ‏ ‏مُوسَى ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اعْتَكَفَ فِي ‏ ‏قُبَّةٍ ‏ ‏مِنْ خُوصٍ ‏","","",""],[18283,18283,"","আমি যখন তাকে জিজ্ঞেস করি যে, আমি কী করছি, তখন তিনি কী করেন?","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ مَعْرُوفٍ ‏ ‏وَأَبُو مَعْمَرٍ ‏ ‏وَمُحَمَّدُ بْنُ حَسَّانَ السَّمْتِيُّ ‏ ‏قَالُوا ثَنَا ‏ ‏عَلِيُّ بْنُ عَابِسٍ ‏ ‏عَنْ ‏ ‏أَبِي فَزَارَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اعْتَكَفَ فِي ‏ ‏قُبَّةٍ ‏ ‏مِنْ خُوصٍ ‏","","",""],[18284,18284,"","তিনি ঈশ্বরের কাছে প্রার্থনা করেছিলেন এবং বলেছিলেন যে, তিনি যদি তা করতেন, তা হলে আকাশ তাঁর সঙ্গে তুলনা করা হতো । সে তার হারিয়ে গিয়েছিল, ঘণ্টাখানেক.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ اللَّهِ الصُّنَابِحِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الشَّمْسَ تَطْلُعُ بَيْنَ قَرْنَيْ شَيْطَانٍ فَإِذَا ارْتَفَعَتْ فَارَقَهَا فَإِذَا كَانَتْ فِي وَسَطِ السَّمَاءِ قَارَنَهَا فَإِذَا ‏ ‏دَلَكَتْ ‏ ‏أَوْ قَالَ زَالَتْ ‏ ‏فَارَقَهَا فَإِذَا دَنَتْ لِلْغُرُوبِ قَارَنَهَا فَإِذَا غَرُبَتْ فَارَقَهَا فَلَا تُصَلُّوا هَذِهِ الثَّلَاثَ سَاعَاتٍ ‏","","",""],[18285,18285,"","আমার বাবা হয়তো ঈশ্বরকে তার নাকের কাছ থেকে এবং তার কাছ থেকে তার কাছ থেকে ঈশ্বরের কাছে প্রার্থনা করার সবচেয়ে ভাল সুযোগ পেয়েছিলেন । আমার সামনে তার সমস্ত সূত্র আমার দৃষ্টি থেকে চলে গেছে। তারপর আমাদের কাছে একটা জানালার খোঁজ নেয়ার প্ল্যান ছিলো, আমি আমার বাবাকে তার ছেলের সবচেয়ে ভাল প্ল্যানের আগে একটা গোপন কথা বলবো। তার নাক আর মুখের ভেতর, আর সে তার সাথে কথা বলেছে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُطَرِّفٍ أَبُو غَسَّانَ ‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ اللَّهِ الصُّنَابِحِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ مَضْمَضَ وَاسْتَنْشَقَ خَرَّتْ خَطَايَاهُ مِنْ ‏ ‏فِيهِ وَأَنْفِهِ وَمَنْ غَسَلَ وَجْهَهُ خَرَجَتْ خَطَايَاهُ مِنْ ‏ ‏أَشْفَارِ ‏ ‏عَيْنَيْهِ وَمَنْ غَسَلَ يَدَيْهِ خَرَجَتْ مِنْ أَظْفَارِهِ ‏ ‏أَوْ مِنْ تَحْتِ أَظْفَارِهِ ‏ ‏وَمَنْ مَسَحَ رَأْسَهُ وَأُذُنَيْهِ خَرَجَتْ خَطَايَاهُ مِنْ رَأْسِهِ أَوْ شَعَرِ أُذُنَيْهِ وَمَنْ غَسَلَ رِجْلَيْهِ خَرَجَتْ خَطَايَاهُ مِنْ أَظْفَارِهِ ‏ ‏أَوْ تَحْتَ أَظْفَارِهِ ‏ ‏ثُمَّ كَانَتْ خُطَاهُ إِلَى الْمَسْجِدِ ‏ ‏نَافِلَةً ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُطَرِّفٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ اللَّهِ الصُّنَابِحِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ تَمَضْمَضَ ‏ ‏وَاسْتَنْثَرَ ‏ ‏خَرَجَتْ خَطَايَاهُ مِنْ أَنْفِهِ وَفَمِهِ فَذَكَرَ مَعْنَاهُ ‏","","",""],[18286,18286,"","আমরা কয়েকটা ঘোড়া চেষ্টা করেছি কিন্তু সুসংবাদের কথা বলছি। ঐ লোক বললো যে সে ঈশ্বরকে প্রার্থনা করতে দেখেছে আর তাকে বন্ধুত্বের মধ্যে দিয়ে চলে গেছে। সে বলল, \"ঈশ্বর, আমি এটাকে দুইবার তৈরি করছি।\" সে বলল, \"ঈশ্বর, আমি এটাকে দ্বিগুণ করে দিচ্ছি।\" এবং আমি এটাকে দ্বিগুণ করে ফেলেছি। আর আমি যদি আমার বন্ধু হয়, আমি আমার মনে হয় যে আমি আমার কাছে \"আমি\" এবং আমি শুধু একটা জিনিস আছে, আমি শুধু একটা ছোট ছোট ঘোড়া চাই। আর আমি যদি আমি শুধু একটা জিনিসও বলি, আমি শুধু একটা ছোট জিনিস আছে, আমি শুধু একটা ছোট জিনিস। আর আমি শুধু একটা ঘোড়াও জানি, আমি জানি, আমি কি জানি, আমি জানি না? আমি কি জানি, আমি জানি না? আমি কি জানি, আমি জানি, আমি জানি, আমি জানি না? আমি জানি, আমি কি করবো? আমি জানি না? বন্ধুত্ব।","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابُ بْنُ زِيَادٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُبَارَكٍ ‏ ‏أَخْبَرَنَا ‏ ‏خَالِدُ بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ أَبِي حَازِمٍ ‏ ‏عَنِ ‏ ‏الصُّنَابِحِيِّ ‏ ‏قَالَ ‏ ‏رَأَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي إِبِلِ ‏ ‏الصَّدَقَةِ ‏ ‏نَاقَةً ‏ ‏مُسِنَّةً ‏ ‏فَغَضِبَ وَقَالَ ‏ ‏مَا هَذِهِ فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي ارْتَجَعْتُهَا بِبَعِيرَيْنِ مِنْ ‏ ‏حَاشِيَةِ ‏ ‏الصَّدَقَةِ ‏ ‏فَسَكَتَ ‏","","",""],[18287,18287,"","আমরা বড় হওয়ার বিষয়ে কথা বলেছিলাম, আমরা সেই ভাসমান মাটির চারপাশে শুয়ে বলেছিলাম যে নাবিক আমাকে প্রেমের আগুনে পুড়িয়ে দিয়েছে । তারা বিজয়ের বিরুদ্ধে লড়াই অথবা আত্মার মৃত্যুর দেরি করার জন্য অপেক্ষা করার জন্য দেরি করে এবং তারা অন্ত্যেষ্টিক্রিয়ার জন্য কিছু খায় নি। খেয়ে ফেলো।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏الصَّلْتُ يَعْنِي ابْنَ الْعَوَّامِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الْحَارِثُ بْنُ وَهْبٍ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ الصُّنَابِحِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَنْ تَزَالَ أُمَّتِي فِي ‏ ‏مَسَكَةٍ ‏ ‏مَا لَمْ يَعْمَلُوا بِثَلَاثٍ مَا لَمْ يُؤَخِّرُوا الْمَغْرِبَ بِانْتِظَارِ الْإِظْلَامِ ‏ ‏مُضَاهَاةَ ‏ ‏الْيَهُودِ ‏ ‏وَمَا لَمْ يُؤَخِّرُوا الْفَجْرَ ‏ ‏إِمْحَاقَ ‏ ‏النُّجُومِ ‏ ‏مُضَاهَاةَ ‏ ‏النَّصْرَانِيَّةِ وَمَا لَمْ ‏ ‏يَكِلُوا ‏ ‏الْجَنَائِزَ إِلَى أَهْلِهَا ‏","","",""],[18288,18288,"","সে বলেছিল আমরা আপনার টাকা একটা ছেলের ব্যাপারে বলার চেষ্টা করেছি, কিন্তু ঈশ্বর সবচেয়ে ভালো মানুষ বলেছেন যে যদি তিনি চলে যান, তাহলে সে হয়তো ভুল হয়ে যেতে পারে। পরিকল্পনাটা তার মুখ থেকে বের হয়ে যাচ্ছে। সে তার মাথা থেকে বের হয়ে চলে গেছে যতক্ষণ না পর্যন্ত না সে তার কান থেকে বের হয়ে যায়, তার লোক থেকে সে চলে যায়, তারপর সে তার পথ খুঁজে বের হয়। প্রার্থনা করি।","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏قَالَ ‏ ‏وَحَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏أَخْبَرَنِي ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ الصُّنَابِحِيِّ ‏ ‏قَالَ ‏ ‏إِذَا تَوَضَّأَ الْعَبْدُ فَمَضْمَضَ خَرَجَتْ الْخَطَايَا مِنْ أَنْفِهِ فَإِذَا غَسَلَ وَجْهَهُ خَرَجَتْ الْخَطَايَا مِنْ وَجْهِهِ حَتَّى تَخْرُجَ مِنْ تَحْتِ ‏ ‏أَشْفَارِ ‏ ‏عَيْنَيْهِ فَإِذَا غَسَلَ يَدَيْهِ خَرَجَتْ خَطَايَاهُ مِنْ يَدَيْهِ حَتَّى تَخْرُجَ مِنْ تَحْتِ أَظْفَارِ يَدَيْهِ فَإِذَا مَسَحَ رَأْسَهُ خَرَجَتْ الْخَطَايَا مِنْ رَأْسِهِ حَتَّى تَخْرُجَ مِنْ أُذُنَيْهِ وَإِذَا غَسَلَ رِجْلَيْهِ خَرَجَتْ الْخَطَايَا مِنْ رِجْلَيْهِ حَتَّى تَخْرُجَ مِنْ تَحْتِ أَظْفَارِ رِجْلَيْهِ ثُمَّ كَانَ مَشْيُهُ إِلَى الْمَسْجِدِ وَصَلَاتُهُ ‏ ‏نَافِلَةً ‏ ‏لَهُ ‏","","",""],[18289,18289,"","আমরা দুই বছর ধরে নেকড়ের কথা শুনেছি। আল্লাহ তার জন্য প্রার্থনা করেছেন এবং আমাকে বলবেন না যে তুমি এত শিক্ষিত হবে।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏قَيْسًا ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏الصُّنَابِحِيَّ الْأَحْمَسِيَّ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ أَلَا ‏ ‏إِنِّي ‏ ‏فَرَطُكُمْ ‏ ‏عَلَى ‏ ‏الْحَوْضِ ‏ ‏وَإِنِّي ‏ ‏مُكَاثِرٌ ‏ ‏بِكُمْ الْأُمَمَ فَلَا تَقْتَتِلُنَّ بَعْدِي ‏","","",""],[18290,18290,"","আমরা আপনার টাকা আর বেনের সাথে দেখা করার কথা বলেছিলাম। ঈশ্বরের গড বলছে যে তিনি ঈশ্বরের কাছে প্রার্থনা করেছেন যে সূর্য শপথ করছে, তিনি তার কাছে এসেছেন, তাই তিনি চলে গেছেন। সে হারিয়ে গেছে, সন্ধ্যার পর বাবার সাথে কথা বলার পর...","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏وَزُهَيْرُ بْنُ مُحَمَّدٍ ‏ ‏قَالَا ثَنَا ‏ ‏زَيْدُ بْنُ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ الصُّنَابِحِيَّ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ الشَّمْسَ تَطْلُعُ بَيْنَ قَرْنَيْ شَيْطَانٍ فَإِذَا طَلَعَتْ قَارَنَهَا فَإِذَا ارْتَفَعَتْ فَارَقَهَا وَيُقَارِنُهَا حِينَ ‏ ‏تَسْتَوِي فَإِذَا زَالَتْ فَارَقَهَا فَصَلُّوا غَيْرَ هَذِهِ السَّاعَاتِ الثَّلَاثِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ اللَّهِ ‏ ‏بِحَدِيثِ الشَّمْسِ ‏","","",""],[18291,18291,"","আমি আমার ভাইয়ের ছেলে যে কিনা বারবার চেষ্টা করেছিল, তার কাছে প্রার্থনা করলাম এবং যারা বলবে তাদের সে বলবে, এটা হবে সেই বিয়ের কথা। যদি গাছ এমন হত যে ঈশ্বরের প্রতি ভালবাসা বলবে, তাহলে সে তোমাকে বিয়ে দেবে, যখন সে রাতে চলে যায়। তার কাছে আমি আর ভুল লোকের সাথে আটকে আছি, আমি আমার লোক নিয়ে তার যাত্রা থেকে সূর্য পর্যন্ত আটকা পড়া নিয়ে তার ভয়ে আমি যাত্রা করছি। আমি তাকে বলছি, সে মুক্তির মূল্য অথবা রড দিয়ে কি করেছে। আমি বলেছিলাম, ঈশ্বর যদি আমি এই শপথটা ধরে রাখি, তা হলে আমি কিছু মনে করতে পারি না । হাঙ্গর থেকে মুখ ফিরিয়ে আমি একটা রহস্যের রহস্য সরিয়ে নেবো। আমার ভাই আমাকে আমার ভাইয়ের ছেলে, আমার বোকা যাজক, সে শুনতে অথবা শোনা। বিছানায় শুয়ে বললেন আমি ঈশ্বরের সাথে জিতি, আমার সাথে কথা বলার জন্য আমার কাছে তার কাছে মুক্তি আছে। সে বলল যে সে আমাকে খুন করতে চাচ্ছে। সে যা বলেছে তা প্রভুর কাছে ফিরিয়ে দিতে বলেছে, যে কিনা ভাই হিসেবে পরিচিত। আমরা আমার বাবাকে খুন করার চেষ্টা করেছি। এটা রহস্য যে তিনি তাদের সব শোনা বা তাদের সব দুই ঘোড়া সঙ্গে যারা ঈশ্বরকে জয় করার চেষ্টা করেছিল. তারা বলেছিল গাছ ঈশ্বরের ইচ্ছার সঙ্গে যাবে, ঈশ্বরের নিজস্ব বিয়ে আছে আর সে তোমাকে খেলতে বাধ্য করবে, আমি আমার শেষ লোককে খুন করার চেষ্টা করেছি... ...আর বলেছে সে দরিদ্রদের ভাগ্য থেকে পালিয়ে যেতে কি করেছে. আমি বলেছি এগুলো আমার মনের কথা বলতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏أَخْبَرَنِي ‏ ‏ابْنُ أَخِي أَبِي رُهْمٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا رُهْمٍ الْغِفَارِيَّ ‏ ‏وَكَانَ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الَّذِينَ بَايَعُوا تَحْتَ الشَّجَرَةِ ‏ ‏يَقُولُ ‏ ‏غَزَوْتُ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غَزْوَةَ ‏ ‏تَبُوكَ ‏ ‏فَلَمَّا ‏ ‏فَصَلَ ‏ ‏سَرَى ‏ ‏لَيْلَةً فَسِرْتُ قَرِيبًا مِنْهُ وَأُلْقِيَ عَلَيَّ النُّعَاسُ ‏ ‏فَطَفِقْتُ ‏ ‏أَسْتَيْقِظُ وَقَدْ ‏ ‏دَنَتْ ‏ ‏رَاحِلَتِي ‏ ‏مِنْ ‏ ‏رَاحِلَتِهِ ‏ ‏فَيُفْزِعُنِي ‏ ‏دُنُوُّهَا ‏ ‏خَشْيَةَ أَنْ أُصِيبَ رِجْلَهُ فِي ‏ ‏الْغَرْزِ ‏ ‏فَأُؤَخِّرُ ‏ ‏رَاحِلَتِي ‏ ‏حَتَّى غَلَبَتْنِي عَيْنِي فِي نِصْفِ اللَّيْلِ فَرَكِبَتْ ‏ ‏رَاحِلَتِي ‏ ‏رَاحِلَتَهُ ‏ ‏وَرِجْلُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏الْغَرْزِ ‏ ‏فَأَصَابَتْ رِجْلَهُ فَلَمْ أَسْتَيْقِظْ إِلَّا بِقَوْلِهِ ‏ ‏حَسِّ ‏ ‏فَرَفَعْتُ رَأْسِي فَقُلْتُ اسْتَغْفِرْ لِي يَا رَسُولَ اللَّهِ فَقَالَ ‏ ‏سَلْ فَقَالَ ‏ ‏فَطَفِقَ ‏ ‏يَسْأَلُنِي عَمَّنْ تَخَلَّفَ مِنْ ‏ ‏بَنِي غِفَارٍ ‏ ‏فَأُخْبِرُهُ فَإِذَا هُوَ يَسْأَلُنِي مَا فَعَلَ ‏ ‏النَّفَرُ ‏ ‏الْحُمْرُ ‏ ‏الطُّوَالُ ‏ ‏الْقِطَاطُ ‏ ‏أَوْ قَالَ ‏ ‏الْقِصَارُ ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏يَشُكُّ ‏ ‏الَّذِينَ لَهُمْ ‏ ‏نَعَمٌ ‏ ‏بِشَظِيَّةِ شَرْخٍ ‏ ‏قَالَ فَذَكَرْتُهُمْ فِي ‏ ‏بَنِي غِفَارٍ ‏ ‏فَلَمْ أَذْكُرْهُمْ حَتَّى ذَكَرْتُ ‏ ‏رَهْطًا ‏ ‏مِنْ ‏ ‏أَسْلَمَ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ مَا يَمْنَعُ أَحَدُ أُولَئِكَ حِينَ تَخَلَّفَ أَنْ يَحْمِلَ عَلَى بَعِيرٍ مِنْ إِبِلِهِ امْرَأً نَشِيطًا فِي سَبِيلِ اللَّهِ فَادْعُوا هَلْ أَنْ يَتَخَلَّفَ عَنْ ‏ ‏الْمُهَاجِرِينَ ‏ ‏مِنْ ‏ ‏قُرَيْشٍ ‏ ‏وَالْأَنْصَارِ ‏ ‏وَأَسْلَمَ ‏ ‏وَغِفَارٍ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏قَالَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏أَخْبَرَنِي ‏ ‏ابْنُ أَخِي أَبِي رُهْمٍ الْغِفَارِيِّ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا رُهْمٍ ‏ ‏وَكَانَ مِنْ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الَّذِينَ بَايَعُوا تَحْتَ الشَّجَرَةِ ‏ ‏يَقُولُ ‏ ‏غَزَوْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غَزْوَةَ ‏ ‏تَبُوكَ ‏ ‏فَنِمْتُ لَيْلَةً ‏ ‏بِالْأَخْصَرِ ‏ ‏فَسِرْتُ قَرِيبًا مِنْهُ فَذَكَرَ مَعْنَى حَدِيثِ ‏ ‏مَعْمَرٍ ‏ ‏إِلَّا أَنَّهُ قَالَ ‏ ‏فَطَفِقْتُ ‏ ‏أُؤَخِّرُ ‏ ‏رَاحِلَتِي ‏ ‏حَتَّى غَلَبَتْنِي عَيْنِي بَعْضَ اللَّيْلِ وَقَالَ مَا فَعَلَ ‏ ‏النَّفَرُ ‏ ‏السُّودُ ‏ ‏الْجِعَادُ ‏ ‏الْقِصَارُ ‏ ‏الَّذِينَ لَهُمْ ‏ ‏نَعَمٌ ‏ ‏بِشَظِيَّةِ شَرْخٍ ‏ ‏فَيَرَى أَنَّهُمْ مِنْ ‏ ‏بَنِي غِفَارٍ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏وَذَكَرَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنِ ‏ ‏ابْنِ أُكَيْمَةَ اللَّيْثِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ أَخِي أَبِي رُهْمٍ الْغِفَارِيِّ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا رُهْمٍ كُلْثُومَ بْنَ حُصَيْنٍ ‏ ‏وَكَانَ مِنْ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الَّذِينَ بَايَعُوا تَحْتَ الشَّجَرَةِ ‏ ‏يَقُولُ ‏ ‏غَزَوْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غَزْوَةَ ‏ ‏تَبُوكَ ‏ ‏فَذَكَرَ الْحَدِيثَ إِلَّا أَنَّهُ قَالَ ‏ ‏فَطَفِقْتُ ‏ ‏أُؤَخِّرُ ‏ ‏رَاحِلَتِي ‏ ‏عَنْهُ حَتَّى غَلَبَتْنِي عَيْنِي وَقَالَ مَا فَعَلَ ‏ ‏النَّفَرُ ‏ ‏السُّودُ ‏ ‏الْجِعَادُ ‏ ‏الْقِصَارُ ‏ ‏قَالَ قُلْتُ وَاللَّهِ مَا أَعْرِفُ هَؤُلَاءِ مِنَّا حَتَّى قَالَ بَلَى الَّذِينَ لَهُمْ ‏ ‏نَعَمٌ ‏ ‏بِشَبَكَةِ شَرْخٍ ‏ ‏قَالَ فَتَذَكَّرْتُهُمْ فِي ‏ ‏بَنِي غِفَارٍ ‏ ‏فَلَمْ أَذْكُرْهُمْ حَتَّى ذَكَرْتُ أَنَّهُمْ ‏ ‏رَهْطٌ ‏ ‏مِنْ ‏ ‏أَسْلَمَ ‏ ‏كَانُوا حِلْفًا فِينَا فَقُلْتُ يَا رَسُولَ اللَّهِ أُولَئِكَ ‏ ‏رَهْطٌ ‏ ‏مِنْ ‏ ‏أَسْلَمَ ‏ ‏كَانُوا حُلَفَاءَنَا ‏","","",""],[18292,18292,"","আমরা একটা সুখী ছেলের কথা বলেছি, যে আমার সাথে কথা বলেছে ঈশ্বরের দোহাইের জন্য, আমি ঈশ্বরের কাছে প্রার্থনা করব আর সে যে দিন ঘুমাবে, আর সে মারা যাবে। ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তিনি তার ঋণের কথা বলতে বা তার সবচেয়ে ভালো পরাজয় থেকে মুক্তি পেতে রাজি হবেন। যখন তার কাপুরুষরা বলল, গোপন একটা শব্দ আমি বুঝতে পারিনি, সে আমার কিছু কিছু প্রশ্ন জিজ্ঞেস করেছে। লোকেরা যা বলে","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏ثَوْرٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏رَاشِدُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ لُحَيٍّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ قُرْطٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَعْظَمُ الْأَيَّامِ عِنْدَ اللَّهِ ‏ ‏يَوْمُ النَّحْرِ ‏ ‏ثُمَّ ‏ ‏يَوْمُ النَّفْرِ ‏ ‏وَقُرِّبَ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَمْسُ ‏ ‏بَدَنَاتٍ ‏ ‏أَوْ سِتٌّ ‏ ‏يَنْحَرُهُنَّ ‏ ‏فَطَفِقْنَ ‏ ‏يَزْدَلِفْنَ ‏ ‏إِلَيْهِ أَيَّتُهُنَّ يَبْدَأُ بِهَا فَلَمَّا وَجَبَتْ ‏ ‏جُنُوبُهَا ‏ ‏قَالَ كَلِمَةً خَفِيَّةً لَمْ أَفْهَمْهَا فَسَأَلْتُ بَعْضَ مَنْ ‏ ‏يَلِينِي مَا قَالَ قَالُوا قَالَ مَنْ شَاءَ اقْتَطَعَ ‏","","",""],[18293,18293,"","স্বপ্নের অধিকারী হওয়ার জন্য আমি কতটা ভয় পেয়েছিলাম, সে আমার হৃদয়ের উপর ঈশ্বরের কাছে প্রার্থনা করে ঈশ্বরের কাছে প্রার্থনা করে... ...আর তার কাছে ঈশ্বরের কাছে প্রার্থনা করতে হবে। আর তুমি হবে। ভগবানকে ছেড়ে দাও.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏بَكْرِ بْنِ زُرْعَةَ الْخَوْلَانِيِّ ‏ ‏عَنْ ‏ ‏مُسْلِمِ بْنِ عَبْدِ اللَّهِ الْأَزْدِيِّ ‏ ‏قَالَ ‏ ‏جَاءَ ‏ ‏عَبْدُ اللَّهِ بْنُ قُرْطٍ الْأَزْدِيُّ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْتَ ‏ ‏عَبْدُ اللَّهِ بْنُ قُرْطٍ ‏","","",""],[18294,18294,"","আমরা একটি নির্দিষ্ট খারাপ সঙ্গে কথা বলেছি আমরা আমাদের কাছে বলার মাধ্যমে বলছি যে আমার বাবার ব্যাপারে আমি কতটা কথা বলেছি, ঈশ্বর প্রভুর কাছে এসে তার কাছে প্রার্থনা করতে এসেছেন এবং তাকে আত্মসমর্পণ করতে হবে আমি, অপরাধী বলেছে তাকে কোন ঋণ না দিতে হবে... ...রাতের মধ্যেই আমাকে আটকে রাখতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بِشْرٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو كَثِيرٍ ‏ ‏مَوْلَى ‏ ‏اللَّيْثِيِّينَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ اللَّهِ بْنِ جَحْشٍ ‏ ‏أَنَّ رَجُلًا جَاءَ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ مَا لِي يَا رَسُولَ اللَّهِ إِنْ قُتِلْتُ فِي سَبِيلِ اللَّهِ قَالَ ‏ ‏الْجَنَّةُ قَالَ فَلَمَّا وَلَّى قَالَ إِلَّا الدَّيْنَ ‏ ‏سَارَّنِي ‏ ‏بِهِ ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏آنِفًا ‏","","",""],[18295,18295,"","আমরা ছেলেদের কথা বলেছি কিন্তু আমার ছেলে অনেক কথা বলেছে। একজন ছেলের জন্য যিনি ঈশ্বরের কাছে প্রার্থনা করছেন, তার বাবা বলেছেন, তিনি ঈশ্বরের কাছে এসেছেন, ঈশ্বরের পথে আমি খুন করিনি যতক্ষণ না সে বলেছে যে সে এটা করেছে, ঋণ আমাকে এক গ্লাস সালম নিয়ে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏عَبَّادُ بْنُ عَبَّادٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي كَثِيرٍ ‏ ‏مَوْلَى ‏ ‏الْهِلَالِيِّينَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ اللَّهِ بْنِ جَحْشٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ مَاذَا لِي إِنْ قَاتَلْتُ فِي سَبِيلِ اللَّهِ حَتَّى أُقْتَلَ قَالَ ‏ ‏الْجَنَّةُ قَالَ فَلَمَّا ‏ ‏وَلَّى ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَّا الدَّيْنَ ‏ ‏سَارَّنِي ‏ ‏بِهِ ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏","","",""],[18296,18296,"","আমরা প্রেমের কথা বলেছি যখন আমরা সবচেয়ে ভালো ক্ষমার কথা বলেছি, ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং প্রভুর শোকের মাধ্যমে যারা শপথ নেবে তাদের কাছে আত্মসমর্পণ করবেন। হাত দিয়ে তাকে আঘাত করার সময় তার সাথে.","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏حَدَّثَنَا ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَزْهَرَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَخَلَّلُ ‏ ‏النَّاسَ يَوْمَ ‏ ‏حُنَيْنٍ ‏ ‏يَسْأَلُ عَنْ مَنْزِلِ ‏ ‏خَالِدِ بْنِ الْوَلِيدِ ‏ ‏فَأُتِيَ بِسَكْرَانَ فَأَمَرَ مَنْ كَانَ مَعَهُ أَنْ يَضْرِبُوهُ بِمَا كَانَ فِي أَيْدِيهِمْ ‏","","",""],[18297,18297,"","আমরা দুই বছর আগে কথা বলেছিলাম যে, আমরা আনন্দের এক অতিথি হিসেবে অতিথি হয়ে উঠতে পারি । আমি তার আঙ্গুল দিয়ে মদ খাই, হাত দিয়ে তাকে পেটাতে পারি, যে তার নিজের হাতে মার খায়, সে তার কাছে প্রার্থনা করে তার কাছে প্রার্থনা করে। দূরবীক্ষণ যন্ত্রের কাছে চলে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ أَزْهَرَ ‏ ‏يَقُولُ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غَزَاةَ الْفَتْحِ وَأَنَا غُلَامٌ شَابٌّ ‏ ‏يَتَخَلَّلُ ‏ ‏النَّاسَ ‏ ‏يَسْأَلُ عَنْ مَنْزِلِ ‏ ‏خَالِدِ بْنِ الْوَلِيدِ ‏ ‏فَأُتِيَ بِشَارِبٍ فَأَمَرَ بِهِ فَضَرَبُوهُ بِمَا فِي أَيْدِيهِمْ فَمِنْهُمْ مَنْ ضَرَبَهُ بِنَعْلِهِ وَمِنْهُمْ مَنْ ضَرَبَهُ بِعَصًا وَمِنْهُمْ مَنْ ضَرَبَهُ بِسَوْطٍ ‏ ‏وَحَثَا ‏ ‏عَلَيْهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏التُّرَابَ ‏","","",""],[18298,18298,"","আমরা হ্যাকারদের ভিড়ের কথা বলেছিলাম যে সে হয়তো একজন পরাজিত ব্যক্তি হিসেবে বেঁচেছিল । ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন এবং আল্লাহ্‌র কাছে আত্মসমর্পণ করেছেন, আর তাদের শান্তি ফিরিয়ে আনবেন। হাত দিয়ে এবং স্বপ্ন দেখে সে চলে গেলে সে হার মানতে পারে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ ‏ ‏وَكَانَ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَزْهَرَ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ الْوَلِيدِ بْنِ الْمُغِيرَةِ ‏ ‏خَرَجَ يَوْمَئِذٍ وَكَانَ عَلَى الْخَيْلِ خَيْلِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏ابْنُ أَزْهَرَ ‏ ‏فَرَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعْدَمَا هَزَمَ اللَّهُ الْكُفَّارَ وَرَجَعَ الْمُسْلِمُونَ إِلَى ‏ ‏رِحَالِهِمْ ‏ ‏يَمْشِي فِي الْمُسْلِمِينَ وَيَقُولُ ‏ ‏مَنْ يَدُلُّ عَلَى ‏ ‏رَحْلِ ‏ ‏خَالِدِ بْنِ الْوَلِيدِ ‏ ‏قَالَ فَمَشَيْتُ ‏ ‏أَوْ فَسَعَيْتُ ‏ ‏بَيْنَ يَدَيْهِ وَأَنَا مُحْتَلِمٌ أَقُولُ مَنْ يَدُلُّ عَلَى ‏ ‏رَحْلِ ‏ ‏خَالِدِ بْنِ الْوَلِيدِ ‏ ‏حَتَّى تَخَلَّلْنَا عَلَى ‏ ‏رَحْلِهِ ‏ ‏فَإِذَا ‏ ‏خَالِدٌ ‏ ‏مُسْتَنِدٌ إِلَى ‏ ‏مُؤْخِرَةِ ‏ ‏رَحْلِهِ ‏ ‏فَأَتَاهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَنَظَرَ إِلَى جُرْحِهِ ‏ ‏قَالَ ‏ ‏الزُّهْرِيُّ ‏ ‏وَحَسِبْتُ أَنَّهُ قَالَ ‏ ‏وَنَفَثَ ‏ ‏فِيهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[18299,18299,"","তিনি যখন আমাদের সঙ্গে কথা বলেছিলেন, তখন আমরা করুণা দেখানোর বিষয়ে কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏وَحَدَّثَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏أَنَّ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ أَزْهَرَ ‏ ‏كَانَ ‏ ‏يُحَدِّثُ ‏ ‏أَنَّهُ حَضَرَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ كَانَ ‏ ‏يَحْثِي فِي وُجُوهِهِمْ التُّرَابَ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏وَهَذَا يَتْلُو حَدِيثَ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ قَبِيصَةَ فِي شَارِبِ الْخَمْرِ ‏","","",""],[18300,18300,"","আমরা সুখী এবং আরো অনেক লোক কথা বলেছি, “আমরা সূর্যাস্তের কথা শুনেছি”। তার দুর্ঘটনার সময় সে ঈশ্বরকে তার ইচ্ছার কথা জিজ্ঞেস করে আত্মসমর্পণ করে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏وَوَكِيعٌ ‏ ‏قَالَا ثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏قَيْسٌ ‏ ‏عَنِ ‏ ‏الصُّنَابِحِيِّ الْأَحْمَسِيِّ ‏ ‏قَالَ ‏ ‏وَكِيعٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏الصُّنَابِحِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَا ‏ ‏فَرَطُكُمْ ‏ ‏عَلَى ‏ ‏الْحَوْضِ ‏ ‏وَإِنِّي مُكَاثِرٌ بِكُمْ الْأُمَمَ فَلَا تَقْتَتِلُنَّ بَعْدِي ‏","","",""],[18301,18301,"","আমরা আবেগে বাপ্তাইজিত হয়েছি... ...আমার বাবার একটা আদর্শের জন্য... ...যে কিনা একটা পর্দার জন্য প্রার্থনা করছিল. সে বলল আমি তোমার হৃদয় ভেঙ্গে ফেলব, যখন আমরা জন্ম নিয়েছি, সবচেয়ে ভালো মানুষ তাকে স্পর্শ করব।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ أَبِي خَالِدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَيْسَ بْنَ أَبِي حَازِمٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الصُّنَابِحِيَّ الْبَجَلِيَّ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏أَنَا ‏ ‏فَرَطُكُمْ ‏ ‏عَلَى ‏ ‏الْحَوْضِ ‏ ‏وَمُكَاثِرٌ بِكُمْ الْأُمَمَ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏أَوْ قَالَ النَّاسَ ‏ ‏فَلَا تَقْتَتِلُنَّ بَعْدِي ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ ‏ ‏عَنْ ‏ ‏قَيْسٍ ‏ ‏عَنِ ‏ ‏الصُّنَابِحِيِّ الْأَحْمَسِيِّ ‏ ‏مِثْلَهُ ‏","","",""],[18302,18302,"","আমার বাবার উত্তম গুণগুলোর প্রতি আমার প্রেমের দাসের বিষয়ে আমরা কথা বলেছিলাম । সে তোমাদের মধ্যে কাউকে মারছে... ...আমাদের সাথে দেখা করার জন্য যারা এক জোড়া শক্ত বাজি ধরে ঐ ছেলেটার ব্যাপারে কথা বলেছে.","‏ ‏حَدَّثَنَا ‏ ‏عَبَّادُ بْنُ عَبَّادِ بْنِ حَبِيبِ بْنِ الْمُهَلَّبِ بْنِ أَبِي صُفْرَةَ الْمُهَلَّبِيِّ أَبُو مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏مُجَالِدِ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ أَبِي حَازِمٍ ‏ ‏عَنِ ‏ ‏الصُّنَابِحِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي مُكَاثِرٌ بِكُمْ الْأُمَمَ فَلَا تَرْجِعُنَّ بَعْدِي كُفَّارًا يَضْرِبُ بَعْضُكُمْ رِقَابَ بَعْضٍ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏حَمَّادِ بْنِ زَيْدٍ ‏ ‏عَنِ ‏ ‏الصُّنَابِحِيِّ ‏ ‏وَرُبَّمَا قَالَ ‏ ‏الصُّنَابِحِ ‏","","",""],[18303,18303,"","সে দুটো তলোয়ার পড়ে এবং আমি সাক্ষী যে আমাকে ভাল কিছুর ফুল সম্পর্কে বলতে শুনেছেন, তার জন্য ঈশ্বরের কাছে প্রার্থনা করতে দেখা গেছে তিনি মারা যান, যিনি আহত হয়েছেন আর তার সঙ্গে পালিয়ে যাওয়ার সুযোগ ছিল ।","‏ ‏قَالَ ‏ ‏قُرِئَ عَلَى ‏ ‏سُفْيَانَ ‏ ‏وَأَنَا شَاهِدٌ ‏ ‏سَمِعْتُ ‏ ‏مَعْمَرًا ‏ ‏يُحَدِّثُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَزْهَرَ ‏ ‏قَالَ ‏ ‏جُرِحَ ‏ ‏خَالِدُ بْنُ الْوَلِيدِ ‏ ‏فَرَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسْأَلُ عَنْ ‏ ‏رَحْلِهِ ‏ ‏قُلْتُ وَأَنَا غُلَامٌ مَنْ يَدُلُّ عَلَى ‏ ‏رَحْلِ ‏ ‏خَالِدٍ ‏ ‏فَأَتَاهُ وَهُوَ مَجْرُوحٌ فَجَلَسَ عِنْدَهُ ‏","","",""],[18304,18304,"","ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং লোকেদের সেই ব্যক্তিদের অপসারণের জন্য নিজেকে সমর্পণ করেছেন, যারা মনের মধ্যে রয়েছে । যারা মানুষের উপর লোক-তাদের হাত আছে , যা তারা অর ্ জন করেছে ; মানুষের হাত থেকে , -- তারাই তো হচ ্ ছে লোক যারা আল ্ লাহ ্ ‌ র নির ্ দেশাবলী অর ্ জন করে , আর এরা নিজেরাই হচ ্ ছে সফলকাম । ''আর এদের মধ্যের যে কেউ এখানে রয়েছে, সে তো হলো তারাই তো আসল লোক, যারা এ ব্যাপারে অন্য দল।’’ এরাই তারা যাদের সত ্ যনিষ ্ ঠ লোক আছে তারা এখানে আছে সেইসব লোকদের জন ্ য যারা ঈমান এনেছে । ''আর যাদের তোমরা আহ্বান কর তাঁকে ছাড়া অন্য কিছু লোক তারাই পুরুষ ও নারী যাদের সন্বন্ধে তারা কথা বলে।’’ যারা ঈশ্বরের ইচ্ছা পালন করছে, তারা তাকে ছেড়ে দেবে আর তাকে কষ্ট দিতে হবে। ঈশ্বর আমাদের দিনগুলোর জন্য আমাদের অনেক কষ্ট নিয়ে এসেছেন। সে তাকে বলেছিল, কি ঘটেছে সে সম্পর্কে আমরা কথা বলেছি। আমার বাবা, যিনি তোমার মাথায় দিয়ে গিয়েছিলেন, তিনি তোমার বাবার অমরতা সম্বন্ধে শুনুন, যিনি প্রভুর অভিভাবকে স্থিরকৃত একজন যাজক হওয়ার জন্য আমার পিতার কাছে। সে একজন পলাতকের চেয়ে বেশি কিছু... ...যে এক প্রজন্ম দ্বারা সুরক্ষিত ছিল... ...আমি রক্ষা করার চেয়ে.","‏ ‏حَدَّثَنَا ‏ ‏صَفْوَانُ بْنُ عِيسَى ‏ ‏أَخْبَرَنَا ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَزْهَرَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏حُنَيْنٍ ‏ ‏وَهُوَ ‏ ‏يَتَخَلَّلُ ‏ ‏النَّاسَ ‏ ‏يَسْأَلُ عَنْ ‏ ‏رَحْلِ ‏ ‏خَالِدِ بْنِ الْوَلِيدِ ‏ ‏فَأُتِيَ بِسَكْرَانَ فَأَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ كَانَ عِنْدَهُ أَنْ يَضْرِبُوهُ بِمَا كَانَ فِي أَيْدِيهِمْ ‏ ‏وَحَثَا ‏ ‏عَلَيْهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏التُّرَابَ ‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏الزُّهْرِيُّ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَزْهَرَ الزُّهْرِيُّ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَخَلَّلُ ‏ ‏النَّاسَ يَسْأَلُ عَنْ مَنْزِلِ ‏ ‏خَالِدِ بْنِ الْوَلِيدِ ‏ ‏فَذَكَرَهُ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏وَثَنَا ‏ ‏عَبْدُ اللَّهِ يَعْنِي ابْنَ الْمُبَارَكِ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْمَاعِيلُ بْنُ أَبِي خَالِدٍ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ أَبِي حَازِمٍ ‏ ‏عَنِ ‏ ‏الصُّنَابِحِيِّ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏فَذَكَرَهُ ‏ ‏قَالَ ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏الصُّنَابِحِيُّ ‏ ‏رَجُلٌ مِنْ ‏ ‏بَجِيلَةَ ‏ ‏مِنْ ‏ ‏أَحْمَسَ ‏","","",""],[18305,18305,"","আমরা কথা বলেছি তুমি তোমার টাকা কি করে ভুলে গেলে, লর্ড, আমাকে এভাবে ব্যবহার না করতে, আর তুমি আমার পিছনে প্রভাব ফেলতে পারবে, কাল পর্যন্ত তারা আমাকে একই সুরে অভিবাদন না দেয়।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏أُسَيْدِ بْنِ حُضَيْرٍ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏يَا رَسُولَ اللَّهِ أَلَا تَسْتَعْمِلُنِي كَمَا اسْتَعْمَلْتَ فُلَانًا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَتَلْقَوْنَ بَعْدِي ‏ ‏أَثَرَةً ‏ ‏فَاصْبِرُوا حَتَّى تَلْقَوْنِي غَدًا عَلَى ‏ ‏الْحَوْضِ ‏","","",""],[18306,18306,"","আমরা আমাদের বলতে চেয়েছিলাম, কী করব । আমি শুনেছি, আমি শুনেছি, আর যদি ঈশ্বরের দোহাইর একটা সাহসী নকশা শুনেছি, ঈশ্বরের কাছে তার শান্তি থাকবে এবং তাকে কাপুরুষ হিসেবে দেখা হবে। যাই হোক না কেন, এটা তার জন্য যা করা হয়েছে এবং এটা কি হয় শিকারী হতে হয়.","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْمُبَارَكِ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ أَيُّوبَ ‏ ‏عَنْ ‏ ‏عُمَارَةَ بْنِ غَزِيَّةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏فَاطِمَةَ ابْنَةِ حُسَيْنٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا ‏ ‏كَانَتْ ‏ ‏تَقُولُ ‏ ‏كَانَ ‏ ‏أُسَيْدُ بْنُ حُضَيْرٍ ‏ ‏مِنْ أَفَاضِلِ النَّاسِ وَكَانَ يَقُولُ ‏ ‏لَوْ أَنِّي أَكُونُ كَمَا أَكُونُ عَلَى أَحْوَالٍ ثَلَاثٍ مِنْ أَحْوَالِي لَكُنْتُ حِينَ أَقْرَأُ الْقُرْآنَ وَحِينَ أَسْمَعُهُ يُقْرَأُ وَإِذَا سَمِعْتُ خُطْبَةَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَإِذَا شَهِدْتُ جِنَازَةً وَمَا شَهِدْتُ جِنَازَةً قَطُّ فَحَدَّثْتُ نَفْسِي بِسِوَى مَا هُوَ مَفْعُولٌ بِهَا وَمَا هِيَ صَائِرَةٌ إِلَيْهِ ‏","","",""],[18307,18307,"","আমরা একটা প্রথা নিয়ে কথা বলেছি যা আমি শুনেছি তোমার ব্যাপারে কথা বলা নিয়ে। ঈশ্বর তাকে বলতে বলেছেন যে ঈশ্বরের আছে ব্যর্থ হয়েছি, আমাদের ছেলেরা কিভাবে বলবে যে তুমি একটা পার্থক্য করতে পারবে?","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏أُسَيْدِ بْنِ حُضَيْرٍ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏قَالَ ‏ ‏إِنَّ رَجُلًا مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏تَخَلَّى بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ أَلَا تَسْتَعْمِلُنِي كَمَا اسْتَعْمَلْتَ فُلَانًا قَالَ ‏ ‏إِنَّكُمْ سَتَلْقَوْنَ بَعْدِي ‏ ‏أَثَرَةً ‏ ‏فَاصْبِرُوا حَتَّى تَلْقَوْنِي عَلَى ‏ ‏الْحَوْضِ ‏","","",""],[18308,18308,"","আমরা তার দাদাকে বলেছিলাম একটা বাসা খুঁজে বের করতে, অথবা একটা বাসা খুঁজেছি, অথবা আমরা একটা ঘোড়ার সাথে আটকে আছি আর একটা শয়তানী কণ্ঠের মত। সে বলেছে, সে তার ক্ষমা করেছে, তুমি হয়ত তার সামনে এগিয়ে যেতে ব্যর্থ হয়েছ এবং বলতে পারো তুমি মুক্ত। সে বলেছে, সে তার কাছে প্রার্থনা করছে এবং সে যা বলেছে তা ছেড়ে দিয়েছে। সে আমাকে সাহায্য করার জন্য একটা জীবন্ত ব্যবস্থা করবে, সে আমাকে দিয়ে চলে যাবে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَدِمْنَا مِنْ حَجٍّ ‏ ‏أَوْ عُمْرَةٍ ‏ ‏فَتُلُقِّينَا ‏ ‏بِذِي الْحُلَيْفَةِ ‏ ‏وَكَانَ غِلْمَانٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏تَلَقَّوْا أَهْلِيهِمْ فَلَقُوا ‏ ‏أُسَيْدَ بْنَ حُضَيْرٍ ‏ ‏فَنَعَوْا ‏ ‏لَهُ امْرَأَتَهُ ‏ ‏فَتَقَنَّعَ ‏ ‏وَجَعَلَ يَبْكِي قَالَتْ فَقُلْتُ لَهُ غَفَرَ اللَّهُ لَكَ أَنْتَ صَاحِبُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَكَ مِنْ السَّابِقَةِ وَالْقِدَمِ مَا لَكَ تَبْكِي عَلَى امْرَأَةٍ فَكَشَفَ عَنْ رَأْسِهِ وَقَالَ صَدَقْتِ لَعَمْرِي حَقِّي أَنْ لَا أَبْكِي عَلَى أَحَدٍ بَعْدَ ‏ ‏سَعْدِ بْنِ مُعَاذٍ ‏ ‏وَقَدْ قَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا قَالَ قَالَتْ قُلْتُ لَهُ مَا قَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَقَدْ اهْتَزَّ الْعَرْشُ لِوَفَاةِ ‏ ‏سَعْدِ بْنِ مُعَاذٍ ‏ ‏قَالَتْ وَهُوَ يَسِيرُ بَيْنِي وَبَيْنَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[18309,18309,"","আমরা পরের বাপ্তিস্মের কথা বলেছিলাম, ঈশ্বরের অনুগ্রহে আমার বাবার সব থেকে ভালো ইচ্ছা পূরণ করা হয়েছে। তারা গান গেয়েছে নার্সরা আর তোমরা দরজার কাছে ফোন দাওনি.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ ثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَنْبَأَنَا ‏ ‏الْحَجَّاجُ بْنُ أَرْطَأَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏أُسَيْدِ بْنِ حُضَيْرٍ ‏ ‏قَالَ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تَوَضَّئُوا مِنْ لُحُومِ الْإِبِلِ وَلَا تَوَضَّئُوا مِنْ لُحُومِ الْغَنَمِ وَصَلُّوا فِي ‏ ‏مَرَابِضِ ‏ ‏الْغَنَمِ وَلَا تُصَلُّوا فِي مَبَارِكِ الْإِبِلِ ‏","","",""],[18310,18310,"","আমরা সেই ভয়ঙ্কর খুনিদের কথা বলেছি... ...যে ভালোবাসা করতে চেয়েছিলাম, আমার ছেলে শপথ নিয়েছিল আর বলেছিল যে লর্ড তার ছেলের প্রতি দয়া করে। তাকে বলো আমি কে. সে বলল তুমি তার মেয়ের কাছ থেকে আলো চাইবে না.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُقَاتِلٍ الْمَرْوَزِيُّ ‏ ‏أَخْبَرَنَا ‏ ‏عَبَّادُ بْنُ الْعَوَّامِ ‏ ‏حَدَّثَنَا ‏ ‏الْحَجَّاجُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏قَالَ ‏ ‏وَكَانَ ثِقَةً قَالَ وَكَانَ ‏ ‏الْحَكَمُ ‏ ‏يَأْخُذُ عَنْهُ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏أُسَيْدِ بْنِ حُضَيْرٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ سُئِلَ عَنْ أَلْبَانِ الْإِبِلِ قَالَ ‏ ‏تَوَضَّئُوا مِنْ أَلْبَانِهَا وَسُئِلَ عَنْ أَلْبَانِ الْغَنَمِ فَقَالَ لَا تَوَضَّئُوا مِنْ أَلْبَانِهَا ‏","","",""],[18311,18311,"","আমরা অনেক বছর ধরে একজন যাজকের সাথে কথা বলেছি... ...আমরা এখানে এসেছি আর বিক্রি করেছি. এবং জয়.","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏سُوَيْدِ بْنِ قَيْسٍ ‏ ‏قَالَ ‏ ‏جَلَبْتُ أَنَا ‏ ‏وَمَخْرَمَةُ الْعَبْدِيُّ ‏ ‏ثِيَابًا مِنْ ‏ ‏هَجَرَ ‏ ‏قَالَ فَأَتَانَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَاوَمَنَا ‏ ‏فِي ‏ ‏سَرَاوِيلَ ‏ ‏وَعِنْدَنَا وَزَّانُونَ يَزِنُونَ بِالْأَجْرِ فَقَالَ لِلْوَزَّانِ زِنْ وَأَرْجِحْ ‏","","",""],[18312,18312,"","আমরা তোমার টাকা নিয়ে তর্ক করেছি... ...আমার বাবা এটা করতে বলেছে, সে একজন মানুষের গোপন জিনিস দিয়েছে...","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏مَالِكٍ أَبِي صَفْوَانَ بْنِ عَمِيرَةَ ‏ ‏قَالَ ‏ ‏بِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رِجْلَ ‏ ‏سَرَاوِيلَ ‏ ‏قَبْلَ الْهِجْرَةِ فَأَرْجَحَ لِي ‏","","",""],[18313,18313,"","আমরা বাবার ছেলে, যার অমর, তার কথা শুনেছি, ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং ডাক্তারকে উদ্ধার করেছেন। আমি বললাম, তিনি আমাদের সাথে আছেন।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ يَعْنِي ابْنَ أَبِي خَالِدٍ ‏ ‏عَنْ ‏ ‏حَكِيمِ بْنِ جَابِرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعِنْدَهُ ‏ ‏الدُّبَّاءُ ‏ ‏فَقُلْتُ مَا هَذَا قَالَ ‏ ‏نُكَثِّرُ بِهِ طَعَامَنَا ‏","","",""],[18314,18314,"","আমরা আমার বাবার মুক্তির কথা শুনেছি তার বাবার রাগের জন্য উত্তর শোনার পর, তাকে তার বাসায় আত্মসমর্পণ করতে হবে, আর আমার অনেক কিছু বলার আছে, ঈশ্বর, সে যা বলেছে, সে তোমার সেরাটা করেছে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ أَبِي خَالِدٍ ‏ ‏عَنْ ‏ ‏حَكِيمِ بْنِ جَابِرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَيْتِهِ فَرَأَيْتُ عِنْدَهُ قَرْعًا فَقُلْتُ يَا رَسُولَ اللَّهِ مَا هَذَا قَالَ هَذَا ‏ ‏قَرْعٌ نُكَثِّرُ بِهِ طَعَامَنَا ‏","","",""],[18315,18315,"","আমরা কথা বলেছিলাম তুমি আমার ছেলে বা বাবার জন্য জন্ম নিয়েছ. ঈশ্বর এটা উদ্ধার করতে হবে আর সে এটা পান করবে না যতক্ষণ না সে এটা পান করবে আর এটা সুরক্ষিত আর নিরাপদ থাকবে. এটা সম্মানিত বা গোপন বিষয়. এবং এটা নিরাপদ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى هُوَ ابْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏فِرَاسٍ ‏ ‏عَنْ ‏ ‏مُدْرِكِ بْنِ عُمَارَةَ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي أَوْفَى ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَشْرَبُ الْخَمْرَ حِينَ يَشْرَبُهَا وَهُوَ مُؤْمِنٌ وَلَا يَزْنِي حِينَ يَزْنِي وَهُوَ مُؤْمِنٌ وَلَا ‏ ‏يَنْتَهِبُ ‏ ‏نُهْبَةً ‏ ‏ذَاتَ ‏ ‏شَرَفٍ ‏ ‏أَوْ سَرَفٍ ‏ ‏وَهُوَ مُؤْمِنٌ ‏","","",""],[18316,18316,"","আমরা আমার যুবকের কথা বলেছি আমার বাবা অথবা ঈশ্বরের প্রতি ভালোবাসার ব্যাপারে। সে বলেছিল, আমার বাবার ছেলে ঈশ্বরের কাছে আসছে। সে ঈশ্বরের কাছে আসছে। বাচ্চা জন্ম দেওয়ার পর, সে সাদা, সে বলল আমি জানি না।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنِي ‏ ‏الشَّيْبَانِيُّ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي أَوْفَى ‏ ‏وَعَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنِ ‏ ‏الشَّيْبَانِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ أَبِي أَوْفَى ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏نَبِيذِ ‏ ‏الْجَرِّ ‏ ‏الْأَخْضَرِ ‏ ‏قَالَ ‏ ‏قُلْتُ فَالْأَبْيَضُ قَالَ لَا أَدْرِي ‏","","",""],[18317,18317,"","ঈশ্বর আদেশ দিয়েছেন, যদি তিনি প্রভুর কাছ থেকে তার মাথা উঁচু করে নেন... ...তাহলে তিনি ঈশ্বরের প্রতি তার ভালবাসার কথা শুনেছেন। আমি আমার ছেলেকে সাহায্য করার কথা বলেছি অথবা তিনি কীভাবে আমাকে বলতেন। আমরা কথা বলার পর অসুস্থ কিছু একটা করে ফেলেছি আর আমরা চেষ্টা করেছি, লর্ড প্রার্থনা করেছেন তার কাছে প্রার্থনা করেছেন আর বলেছেন যে তিনি প্রার্থনা করেছেন না","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏عُبَيْدِ بْنِ الْحَسَنِ الْمُزَنِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ أَبِي أَوْفَى ‏ ‏يَقُولُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا رَفَعَ رَأْسَهُ مِنْ الرُّكُوعِ قَالَ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ اللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ مِلْءَ السَّمَاوَاتِ وَمِلْءَ الْأَرْضِ وَمِلْءَ مَا شِئْتَ مِنْ شَيْءٍ بَعْدُ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏مِسْعَرٌ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ بْنُ حَسَنٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي أَوْفَى ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ذَلِكَ وَلَمْ يَقُلْ فِي الصَّلَاةِ ‏","","",""],[18318,18318,"","আমরা একে অপরের ছেলের কথা বলেছি অথবা বলেছি এটা আমার প্রভুর অনুগ্রহ। সবুজ মানুষের আগের কথা আমি কখনো জানি না।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏حَدَّثَنِي ‏ ‏الشَّيْبَانِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ أَبِي أَوْفَى ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏نَبِيذِ ‏ ‏الْجَرِّ ‏ ‏الْأَخْضَرِ ‏ ‏قَالَ ‏ ‏قُلْتُ فَالْأَبْيَضُ قَالَ لَا أَدْرِي ‏","","",""],[18319,18319,"","আমরা কথা বলেছি এবং সে একজন পিতার ছেলে, তার জন্য প্রার্থনা করছে এবং তারা হতাশা থেকে তাদের হত্যা করার জন্য আত্মসমর্পণ করছে। তাদের.","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏وَيَعْلَى هُوَ ابْنُ عُبَيْدٍ ‏ ‏قَالَا ثَنَا ‏ ‏ابْنُ أَبِي خَالِدٍ وَهُوَ إِسْمَاعِيلُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ أَبِي أَوْفَى ‏ ‏يَقُولُ ‏ ‏دَعَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى الْأَحْزَابِ فَقَالَ ‏ ‏اللَّهُمَّ مُنْزِلَ الْكِتَابِ سَرِيعَ الْحِسَابِ ‏ ‏اهْزِمْ ‏ ‏الْأَحْزَابِ اهْزِمْهُمْ وَزَلْزِلْهُمْ ‏","","",""],[18320,18320,"","আমরা আমার বাবার ছেলে খালেদের কথা বলেছিলাম তিনি বলেছিলেন যে আমার বাবা তার সাথে আসবেন বলে তিনি শুনেছেন, তিনি শুধু উলের পিছনে পড়েন এবং তার জন্য একজন খারাপ ব্যক্তি হবেন অন্ধকারে মানে... ...আমাদের ভুলে যাওয়া হবে.","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي خَالِدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ أَبِي أَوْفَى ‏ ‏يَقُولُ ‏ ‏قَدِمْنَا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَطَافَ ‏ ‏بِالْبَيْتِ ‏ ‏وَسَعَى بَيْنَ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏يَعْنِي فِي الْعُمْرَةِ ‏ ‏وَنَحْنُ نَسْتُرُهُ مِنْ الْمُشْرِكِينَ أَنْ يُؤْذُوهُ بِشَيْءٍ ‏","","",""],[18321,18321,"","আমরা বাবার ছেলেকে বলেছিলাম যে যদি সে আমার ভালবাসার কারণে পড়ে যায়, সে একটা ভবিষ্যদ্বাণী দিয়েছে যে তার ছেলে কি মারা গেছে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي خَالِدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ أَبِي أَوْفَى ‏ ‏يَقُولُ ‏ ‏لَوْ كَانَ بَعْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَبِيٌّ مَا مَاتَ ابْنُهُ ‏ ‏إِبْرَاهِيمُ ‏","","",""],[18322,18322,"","আমরা অনেক বছর ধরে আমার বাবার কথা বলেছি, আমার বাবার কাছে আপনার ছেলের অমরতা আছে। ঈশ্বরের কাছে প্রার্থনা করা হয়েছে, ঈশ্বরকে বলতে, আমি কিছু করতে পারব না এবং ঈশ্বর ও তাকে বলেও আমি কিছুই করতে পারি না। আল্লাহ তাঁর উপর দয়া করুন এবং আল্লাহ না থাকেন, অথবা তিনি ক্ষমতাহীন নন। আমার বাবার ছেলে বা ছেলে ঈশ্বরের কাছে প্রার্থনা করে... ...তিনি আমার আত্মা দিয়েছেন আর আমার ঈর্ষার প্রমাণ দিয়েছেন।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏يَزِيدَ أَبِي خَالِدٍ الدَّالَانِيِّ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ السَّكْسَكِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي أَوْفَى ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي لَا أَسْتَطِيعُ أَخْذَ شَيْءٍ مِنْ الْقُرْآنِ فَعَلِّمْنِي مَا يُجْزِئُنِي قَالَ قُلْ ‏ ‏سُبْحَانَ اللَّهِ وَالْحَمْدُ لِلَّهِ وَلَا إِلَهَ إِلَّا اللَّهُ وَاللَّهُ أَكْبَرُ وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ قَالَ يَا رَسُولَ اللَّهِ هَذَا لِلَّهِ عَزَّ وَجَلَّ فَمَا لِي قَالَ قُلْ اللَّهُمَّ اغْفِرْ لِي وَارْحَمْنِي وَعَافِنِي وَاهْدِنِي وَارْزُقْنِي ثُمَّ أَدْبَرَ وَهُوَ مُمْسِكُ كَفَّيْهِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَّا هَذَا فَقَدْ مَلَأَ يَدَيْهِ مِنْ الْخَيْرِ ‏ ‏قَالَ ‏ ‏مِسْعَرٌ ‏ ‏فَسَمِعْتُ ‏ ‏هَذَا الْحَدِيثَ مِنْ ‏ ‏إِبْرَاهِيمَ السَّكْسَكِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي أَوْفَى ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَثَبَّتَنِي فِيهِ غَيْرِي ‏","","",""],[18323,18323,"","ঈশ্বর তার টাকাপয়সা সঞ্চয় করেছেন এবং আমার বাবা তা - ই করেছেন ।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ أَبِي أَوْفَى ‏ ‏يَقُولُ ‏ ‏كَانَ الرَّجُلُ إِذَا أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِصَدَقَةِ ‏ ‏مَالِهِ ‏ ‏صَلَّى عَلَيْهِ ‏ ‏فَأَتَيْتُهُ ‏ ‏بِصَدَقَةِ ‏ ‏مَالِ أَبِي فَقَالَ ‏ ‏اللَّهُمَّ ‏ ‏صَلِّ ‏ ‏عَلَى آلِ ‏ ‏أَبِي أَوْفَى ‏","","",""],[18324,18324,"","আমরা অনেক বছর ধরে আমার বাবার ক্ষমা প্রার্থনা করেছি, অথবা আমার বাবার ছেলে বা বলতে চাই সে হবে না। ঈশ্বর তাকে জিজ্ঞেস করেছেন এবং সে তার প্রান্তরে আমাদের বিয়ে করতে পারবে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي يَعْفُورٍ الْعَبْدِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ أَبِي أَوْفَى ‏ ‏قَالَ ‏ ‏غَزَوْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَبْعَ غَزَوَاتٍ فَكُنَّا نَأْكُلُ فِيهَا ‏ ‏الْجَرَادَ ‏","","",""],[18325,18325,"","আমরা এমন কিছু কথা বলেছিলাম যে আমার বাবার সাথে কথা বলেছে, আমি ঈশ্বরকে খুশি করতে পারব তুমি তার সাথে ঈশ্বরের সাথে কথা বলতে পারবে আর ঈশ্বরের নিজের আর তার নিজের দেবী এবং তার ছেলের মধ্যে দেবী আছে, আমি আমার সন্তুষ্টতা ছেড়ে দেব... ...তারপর ঈশ্বর আপনাকে এটা গ্রহণ করতে বলে দেবেন। ঈশ্বর তাঁর জন্য প্রার্থনা করেন এবং তিনি তার জন্য প্রার্থনা করেন যে দুটো জীবন দিয়েছে। মাতাল।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ هُوَ ابْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏شَيْخٍ ‏ ‏مِنْ ‏ ‏بَجِيلَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ أَبِي أَوْفَى ‏ ‏يَقُولُ ‏ ‏اسْتَأْذَنَ ‏ ‏أَبُو بَكْرٍ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعِنْدَهُ ‏ ‏جَارِيَةٌ تَضْرِبُ بِالدُّفِّ ‏ ‏ثُمَّ ‏ ‏اسْتَأْذَنَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏فَدَخَلَ ثُمَّ اسْتَأْذَنَ ‏ ‏عُثْمَانُ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏فَأَمْسَكَتْ قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ‏ ‏عُثْمَانَ ‏ ‏رَجُلٌ حَيِيٌّ ‏","","",""],[18326,18326,"","বাবা যখন আমাকে বলেছিল যে আমি একটা শহর সম্পর্কে কিছু শুনেছি, তখন আমার বাবা ঈশ্বরের কর্ত্তার কাছে চিঠি লিখেছিলেন, তিনি হ্রদ জয়ের জন্য তার হৃদয়ের কাছে গিয়েছিলেন। ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তিনি তার জন্য প্রার্থনা করেছেন। তারা জানত যে, স্বর্গ সূর্যের দৃষ্টিতে বলা তরবারিকে ছায়া দেওয়া হয়েছিল, তখনও তিনি তা জানতেন । মৃত্যুদণ্ডের ভয় ।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ هُوَ ابْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو حَيَّانَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏شَيْخًا ‏ ‏بِالْمَدِينَةِ ‏ ‏يُحَدِّثُ أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ أَبِي أَوْفَى ‏ ‏كَتَبَ إِلَى ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏إِذْ أَرَادَ أَنْ يَغْزُوَ ‏ ‏الْحَرُورِيَّةَ ‏ ‏فَقُلْتُ لِكَاتِبِهِ وَكَانَ لِي صَدِيقًا انْسَخْهُ لِي فَفَعَلَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏لَا تَمَنَّوْا لِقَاءَ الْعَدُوِّ وَسَلُوا اللَّهَ عَزَّ وَجَلَّ الْعَافِيَةَ فَإِذَا لَقِيتُمُوهُمْ ‏ ‏فَاصْبِرُوا وَاعْلَمُوا أَنَّ الْجَنَّةَ تَحْتَ ظِلَالِ السُّيُوفِ قَالَ فَيَنْظُرُ إِذَا زَالَتْ الشَّمْسُ ‏ ‏نَهَدَ ‏ ‏إِلَى عَدُوِّهِ ثُمَّ قَالَ اللَّهُمَّ مُنْزِلَ الْكِتَابِ وَمُجْرِيَ السَّحَابِ وَهَازِمَ الْأَحْزَابِ اهْزِمْهُمْ وَانْصُرْنَا عَلَيْهِمْ ‏","","",""],[18327,18327,"","আমরা আবেগ নিয়ে কথা বলেছি, একবার শুনে যে আমি হয়ত যুদ্ধ করেছি, সে ঈশ্বরের কাছে যাবে, তার তাকে উদ্ধার করতে হবে। আমি তাকে ভুলে গেছি। আমি মনে করি, আমি এটা শুনতে পাচ্ছি। আমি যদি আমার জীবনের জন্য একটি উদ্দেশ্য ছিল, আমি যা শুনেছি, তা হলে আমি আপনাকে করতে হবে। আমি আপনাকে বলছি, আমি যদি আমার জীবনের জন্য কিছু করতে পারি, তাহলে আমি আপনাকে সাহায্য করতে হবে। আমি আপনাকে বলছি, আমি আপনাকে বলছি, আমি আপনার কাছে এটা একটা কঠিন কাজ করতে হবে। আমি আপনার জন্য করতে চাই। আমি আপনাকে বলছি, আমি আপনার কাছে এটা করতে হবে। আমি চাই। আমি চাই, আমি চাই, আমি চাই, আমি চাই, আমি চাই, আমি এটা করতে চাই। আমি যদি আমার মনে করি, আমি এটা করতে পারি, আমি এটা আমার জীবনের জন্য অনেক কিছু করতে পারি। আমি এটা করতে পারি। আমি আপনার জন্য অনেক ধন্যবাদ দিতে চাই। আমি এটা আমার কাছে এটা আমার জীবনের একটি বিষয় হবে। আমি আপনাকে সাহায্য করতে পারি। কিন্তু আমি যদি আপনি আমার জীবনের জন্য ধন্যবাদ দিতে পারি, আমি আপনাকে সাহায্য করতে পারি। আমি আপনাকে সাহায্য করতে পারি। আমি আপনাকে সাহায্য করতে পারি। আমি কি করবো। আমি এটা করতে পারি। আমি এটা করতে পারি। আমি কি করবো? তারা আমার বাবার বাবা-মা'র সাথে বন্ধুত্ব করেছে.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ أَبِي أَوْفَى ‏ ‏وَكَانَ مِنْ ‏ ‏أَصْحَابِ الشَّجَرَةِ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أُتِيَ ‏ ‏بِصَدَقَةٍ ‏ ‏قَالَ اللَّهُمَّ ‏ ‏صَلِّ ‏ ‏عَلَيْهِمْ وَإِنَّ أَبِي أَتَاهُ ‏ ‏بِصَدَقَتِهِ ‏ ‏فَقَالَ اللَّهُمَّ ‏ ‏صَلِّ ‏ ‏عَلَى آلِ ‏ ‏أَبِي أَوْفَى ‏","","",""],[18328,18328,"","আমরা কামনা এবং পরবর্তী সময়ে আমার ভাইয়ের সম্পর্কে আমাদের অনুভূতি ছিল, আমি আমার বাবার নির্দোষ ছেলে অথবা বাবার ছেলে হতে শুনেছি যে একজন দাস হতে ভয় পাবে। তাকে ভাগ্য ছেড়ে দিতে হবে আর বলতে হবে যে সে আমার ছেলে বা বাবাকে ছেড়ে দেবে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَبَهْزٌ ‏ ‏قَالَا ثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَدِيٍّ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏أَخْبَرَنِي ‏ ‏عَدِيُّ بْنُ ثَابِتٍ ‏ ‏قَالَ ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏سَمِعْتُ ‏ ‏الْبَرَاءَ بْنَ عَازِبٍ ‏ ‏وَابْنَ أَبِي أَوْفَى ‏ ‏قَالَا ‏ ‏أَصَابُوا حُمُرًا يَوْمَ ‏ ‏خَيْبَرَ ‏ ‏فَنَادَى مُنَادِي رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يُكْفِئُوا الْقُدُورَ ‏ ‏وَقَالَ ‏ ‏بَهْزٌ ‏ ‏عَنْ ‏ ‏عَدِيٍّ ‏ ‏عَنِ ‏ ‏الْبَرَاءِ ‏ ‏وَابْنِ أَبِي أوْفَى ‏","","",""],[18329,18329,"","আমরা আবেগ দিয়ে বাপ্তাইজিত হয়েছি... ...আমি একজন মানুষ যার দ্বারা নিহত হয়েছে... ...সে এমন একজন মানুষ যার নাম একজন মানুষ যাকে বলা হয়েছে মানুষ হিসাবে তার যে মৃত ্ যু হয় , সে ব ্ যক ্ তি থেকে নিবৃত ্ ত থাকে । সে ছিল একজন প্রতিবেশী যে প্রভুর ইচ্ছার সাথে রক্ত খায় এবং তারপর তার নিজের শান্তির জন্য এসেছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنِي ‏ ‏رَجُلٌ ‏ ‏مِنْ ‏ ‏بَجِيلَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ أَبِي أَوْفَى ‏ ‏يَقُولُ ‏ ‏كَانَتْ ‏ ‏جَارِيَةٌ ‏ ‏تَضْرِبُ بِالدُّفِّ عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَجَاءَ ‏ ‏أَبُو بَكْرٍ ‏ ‏ثُمَّ جَاءَ ‏ ‏عُمَرُ ‏ ‏ثُمَّ جَاءَ ‏ ‏عُثْمَانُ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏فَأَمْسَكَتْ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ‏ ‏عُثْمَانَ ‏ ‏رَجُلٌ حَيِيٌّ ‏","","",""],[18330,18330,"","আমরা প্রবল আবেগে বাপ্তাইজিত হয়েছি, একদল জনতা আমাকে বিস্মিত করেছে, আর তারপর আমি একটি দাঙ্গার কথা শুনলাম, আমার নিজের অতিথি হওয়ার ব্যাপারে। সে বলছে, সে বলছে ভালো কিছু করার আছে, বরফ এবং ঠাণ্ডা পানি দিয়ে চলচ্চিত্র তৈরি করা, যা অন্য সব থেকে ভালো।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَجْزَأَةَ بْنِ زَاهِرٍ ‏ ‏وَحَجَّاجٌ ‏ ‏حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَجْزَأَةَ بْنِ زَاهِرٍ ‏ ‏وَرَوْحٍ ‏ ‏قَالَا ثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَجْزَأَةَ بْنِ زَاهِرٍ ‏ ‏مَوْلًى ‏ ‏لِقُرَيْشٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ أَبِي أَوْفَى ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ يَقُولُ ‏ ‏اللَّهُمَّ لَكَ الْحَمْدُ مِلْءَ السَّمَاءِ وَمِلْءَ الْأَرْضِ وَمِلْءَ مَا شِئْتَ مِنْ شَيْءٍ بَعْدُ اللَّهُمَّ طَهِّرْنِي بِالثَّلْجِ وَالْبَرَدِ وَالْمَاءِ الْبَارِدِ اللَّهُمَّ طَهِّرْنِي مِنْ الذُّنُوبِ وَنَقِّنِي مِنْهَا كَمَا يُنَقَّى الثَّوْبُ الْأَبْيَضُ مِنْ الْوَسَخِ ‏","","",""],[18331,18331,"","আমরা চেষ্টা করেছি কিছু সময় ধরে যুদ্ধ শোনার চেষ্টা করেছি। ঈশ্বর আমার বাবা অথবা তিনি বলেছিলেন যে, ঈশ্বর তাঁর জন্য প্রার্থনা করবেন এবং আপনার জন্য প্রার্থনা করবেন। গর্ভপাত বলে আকাশের যুক্তি আর ব্যথা ভরা কিছু দিয়ে সে আমাকে ঈশ্বরের ছেলের সাথে ঘুমাত। যদি সে তার নাম হাঁটু থেকে উঠে যায় তাহলে ফোন করবে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُبَيْدًا أَبَا الْحَسَنِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ أَبِي أَوْفَى ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدْعُو بِهَذَا الدُّعَاءِ ‏ ‏اللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ مِلْءَ السَّمَاءِ وَمِلْءَ الْأَرْضِ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏مِلْءَ السَّمَاءِ وَمِلْءَ الْأَرْضِ وَمِلْءَ مَا شِئْتَ مِنْ شَيْءٍ بَعْدُ ‏ ‏قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏وَحَدَّثَنِي ‏ ‏أَبُو عِصْمَةَ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏عُبَيْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى ‏ ‏قَالَ ‏ ‏إِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَدْعُو إِذَا رَفَعَ رَأْسَهُ مِنْ الرُّكُوعِ ‏","","",""],[18332,18332,"","আমরা একটা আবেগ দিয়ে চেষ্টা করেছি যে, আমি শয়তান সম্পর্কে কথা বলেছি। ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং আমি ভাগ্য ছেড়ে দেব। আমি বলবো অথবা আমি তাকে বলবো, কে তার কথা শুনুক। আমি জানি, আমি তাকে বলছি, আমি কি তাকে বলছি, আমার বাবার ছেলে অথবা আমার বাবা।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ الشَّيْبَانِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ أَبِي أَوْفَى ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَكْفِئُوا الْقُدُورَ وَمَا فِيهَا ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏إِمَّا أَنْ يَكُونَ قَالَهُ ‏ ‏سُلَيْمَانُ ‏ ‏وَمَا فِيهَا أَوْ أَخْبَرَنِي مَنْ سَمِعَهُ مِنْ ‏ ‏ابْنِ أَبِي أَوْفَى ‏","","",""],[18333,18333,"","আমার ছেলের কাছ থেকে নির্বাচিত হওয়া বাবার কথা বলেছিলাম, হয়তো আমি একটা বন্যা শুনেছি, আমরা পানি পাইনি, তারপর তারা আমাদের উপর হামলা করেছে তাদের উপর, যারা তারা ঈশ্বর হবার পর. ( গীত.","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي الْمُخْتَارِ ‏ ‏مَنْ ‏ ‏بَنِي أَسَدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ أَبِي أَوْفَى ‏ ‏قَالَ ‏ ‏كُنَّا فِي سَفَرٍ فَلَمْ نَجِدْ الْمَاءَ قَالَ ثُمَّ هَجَمْنَا عَلَى الْمَاءِ بَعْدُ قَالَ فَجَعَلُوا يَسْقُونَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَكُلَّمَا أَتَوْهُ بِالشَّرَابِ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَاقِي الْقَوْمِ آخِرُهُمْ ثَلَاثَ مَرَّاتٍ حَتَّى شَرِبُوا كُلُّهُمْ ‏","","",""],[18334,18334,"","আমরা আমাদের আবেগ-অনুভূতি নিয়ে একটা রীতি তৈরি করেছি যা দুই বার একটা কথা বলার জন্য দরকার ছিল... ...আমরা যে কথাগুলো শুনেছি, তা শুনতে পেয়েছি। আমি যে কথা শুনেছি তা শুনেছি। আমি যা শুনেছি তা শুনে আমি তা শুনেছি। কসম আল্লাহ্‌র নামে কসম, আমি অনেক ঠান্ডা। কিন্তু আমি তো লর্ডের কাছে অনেক ঠান্ডা। কিন্তু আমি এই কথাগুলো শুনেছি। আমার বাবা বা বাবা হতে হবে, আমরা কথা দিচ্ছি ঈশ্বর তাকে ঠিক যেমন আমার বাবা দেবেন. আর কাস্টমার বা কাস্টমারের কাছে যেতে হবে. ষড়যন্ত্রগুলো পাশ দিয়ে যাওয়া ও ক্রেতাদের প্রশ্ন করছে আর তারা হয়তো দেখেছে বা দেখেছে ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ أَبِي الْمُجَالِدِ ‏ ‏قَالَ ‏ ‏اخْتَلَفَ ‏ ‏عَبْدُ اللَّهِ بْنُ شَدَّادٍ ‏ ‏وَأَبُو بُرْدَةَ ‏ ‏فِي ‏ ‏السَّلَفِ ‏ ‏فَبَعَثَانِي إِلَى ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى ‏ ‏فَسَأَلْتُهُ فَقَالَ ‏ ‏كُنَّا ‏ ‏نُسْلِفُ ‏ ‏فِي عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبِي بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏فِي ‏ ‏الْحِنْطَةِ ‏ ‏وَالشَّعِيرِ وَالزَّبِيبِ ‏ ‏أَوْ التَّمْرِ شَكَّ فِي التَّمْرِ وَالزَّبِيبِ ‏ ‏وَمَا هُوَ عِنْدَهُمْ ‏ ‏أَوْ مَا ‏ ‏نَرَاهُ عِنْدَهُمْ ‏ ‏ثُمَّ أَتَيْتُ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ أَبْزَى ‏ ‏فَقَالَ ‏ ‏مِثْلَ ذَلِكَ ‏","","",""],[18335,18335,"","আমরা তোমার টাকা দিয়ে বলছি, আমার বাবার সাথে খেলতে বলা একটা কুত্তার বাচ্চা। ঈশ্বর তার কাছে প্রার্থনা করেছিলেন আর তিনি বলেছিলেন যে তিনি এই ব্যাপারে আদেশ দিয়েছেন বধির এবং বধিরদের।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ قَالَ ‏ ‏مَالِكٌ يَعْنِي ابْنَ مِغْوَلٍ ‏ ‏أَخْبَرَنِي ‏ ‏طَلْحَةُ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِعَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى ‏ ‏أَوْصَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَا قُلْتُ فَكَيْفَ أَمَرَ الْمُؤْمِنِينَ بِالْوَصِيَّةِ وَلَمْ يُوصِ قَالَ ‏ ‏أَوْصَى بِكِتَابِ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[18336,18336,"","আমি আমার বাবাকে নিয়ে কথা বলেছি যে কিনা ভালো কাজ করেছে। আমি তাকে জিজ্ঞাসা করি নবী কি করেছেন এবং তিনি তার পছন্দ অনুযায়ী এটা করবেন। আমি তার চেয়ে কম কিছু। আমি তাকে জিজ্ঞাসা করলাম, আমি আমার বাবার সাথে কথা বলেছি। আমি বলেছিলাম, আমি জানি, আমি জানি, আমি আমার বাবা ভালো আছি। আমি যদি আমার বাবা, আমি তাকে বলেছিলাম, আমি আমার বাবা, আমি আমার কাছে জিজ্ঞেস করি, আমি তাকে বলেছিলাম, আমি যদি আমি আমার ছেলের সাথে কথা বলি, আমি তাকে বলেছিলাম। আমি জিজ্ঞেস করি, আমি আমার বাবা, আমি তাকে বলেছিলাম, আমি তাকে জিজ্ঞেস করি। আমি বলেছিলাম, আমি যদি আমার বাবাও না। আমি তাকে বলেছিলাম, আমি আমার বাবা আমার কাছে জিজ্ঞেস করি, আমি জানি যে, আমি তাকে বলেছিলাম, আমি কি করবো। আমি তাকে আমি জিজ্ঞেস করি, আমি জানি না যে, আমি তাকে আমি কি করবো। আমি জানি না। তোমার কথা আর আমি ছিলাম আমাদের একজন যদি সে কিছু নিতে চায়।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏الشَّيْبَانِيُّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ أَبِي الْمُجَالِدِ ‏ ‏قَالَ ‏ ‏بَعَثَنِي أَهْلُ الْمَسْجِدِ إِلَى ‏ ‏ابْنِ أَبِي أَوْفَى ‏ ‏أَسْأَلُهُ مَا صَنَعَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي طَعَامِ ‏ ‏خَيْبَرَ ‏ ‏فَأَتَيْتُهُ فَسَأَلْتُهُ عَنْ ذَلِكَ قَالَ وَقُلْتُ هَلْ خَمَّسَهُ قَالَ لَا كَانَ أَقَلَّ مِنْ ذَلِكَ قَالَ وَكَانَ أَحَدُنَا ‏ ‏إِذَا أَرَادَ مِنْهُ شَيْئًا أَخَذَ مِنْهُ حَاجَتَهُ ‏","","",""],[18337,18337,"","আমরা আমার বাবাকে কীভাবে বলেছিলাম, তা আমরা বলেছিলাম কিন্তু তিনি আমার ভাই ।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْمَاعِيلُ بْنُ أَبِي خَالِدٍ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِعَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى صَاحِبِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَدَخَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْبَيْتَ ‏ ‏فِي عُمْرَتِهِ قَالَ لَا ‏","","",""],[18338,18338,"","আমরা সবচেয়ে ছোট জিনিস নিয়ে কথা বলেছি যেটা আমাকে বলেছিলাম, আমি বাবার ছেলেকে বলেছি বা ঈশ্বরের কাছে প্রার্থনা করেছি। তিনি বলেছিলেন আমরা হুমকি দেই এবং ফিরে এসে বলি যে আমি জানি না।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏قَالَ ‏ ‏الشَّيْبَانِيُّ ‏ ‏أَخْبَرَنِي قَالَ ‏ ‏قُلْتُ ‏ ‏لِابْنِ أَبِي أَوْفَى ‏ ‏رَجَمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ نَعَمْ يَهُودِيًّا وَيَهُودِيَّةً قَالَ قُلْتُ بَعْدَ نُزُولِ ‏ ‏النُّورِ ‏ ‏أَوْ قَبْلَهَا قَالَ لَا أَدْرِي ‏","","",""],[18339,18339,"","বাবা, ঈশ্বরের দোহাই দিয়ে বাবার জয়ের কথা বলেছিলাম, সে ঈশ্বরের কাছে প্রার্থনা করছে, যেন সে আমাদের সমাজের সকল শক্তি দিয়ে তার উদ্ধার করতে পারে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ يَعْنِي الشَّيْبَانِيَّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ أَكْلِ لُحُومِ الْحُمُرِ الْأَهْلِيَّةِ ‏","","",""],[18340,18340,"","ঈশ্বর তাকে আদেশ দিয়েছেন এবং তিনি আমাদের যে - কাজ দিয়েছেন, সেটার প্রতি আমার গালের অঙ্গীকার করেছেন । তাকে মাংসে বকছে, সে বলবে না সে একবার বলেছিল সে গুলি করছে না, এমনকি সে আর নেই।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏وَيَعْلَى ‏ ‏الْمَعْنَى ‏ ‏قَالَا ثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِعَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى ‏ ‏أَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَشَّرَ ‏ ‏خَدِيجَةَ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهَا ‏ ‏قَالَ نَعَمْ ‏ ‏بَشَّرَهَا بِبَيْتٍ فِي الْجَنَّةِ مِنْ ‏ ‏قَصَبٍ ‏ ‏لَا ‏ ‏صَخَبَ ‏ ‏فِيهِ وَلَا ‏ ‏نَصَبَ ‏ ‏قَالَ ‏ ‏يَعْلَى ‏ ‏وَقَالَ ‏ ‏مَرَّةً لَا ‏ ‏صَخَبَ ‏ ‏أَوْ لَا ‏ ‏لَغْوَ ‏ ‏فِيهِ وَلَا ‏ ‏نَصَبَ ‏","","",""],[18341,18341,"","আমরা আমার বাবার সাথে ঈশ্বরের সাথে কথা বলেছিলাম সে আমাদের একটু আগুন দেবে আর আমরা ওর সাথে থাকব আর সে খুশি হবে। ওর সাথে আর চুপ করে থাকো, এটা কোন ব্যাপারই না।","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ أَبِي أَوْفَى ‏ ‏يَقُولُ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ اعْتَمَرَ ‏ ‏فَطَافَ وَطُفْنَا مَعَهُ وَصَلَّى وَصَلَّيْنَا مَعَهُ وَسَعَى بَيْنَ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏وَكُنَّا نَسْتُرُهُ مِنْ أَهْلِ ‏ ‏مَكَّةَ ‏ ‏لَا يُصِيبُهُ أَحَدٌ بِشَيْءٍ ‏","","",""],[18342,18342,"","আমরা বাবার ছেলে সম্পর্কে কথা বলেছি অথবা সে শুনে ঈশ্বরের ইচ্ছার কথা শুনতে পেত, প্রস্থান হল আগুন।","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ يُوسُفَ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي أَوْفَى ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الْخَوَارِجُ ‏ ‏هُمْ كِلَابُ النَّارِ ‏","","",""],[18343,18343,"","আমরা ঈশ্বরের ছেলে বা ছেলে বলেছিল সে একটা ভালো ছেলে ছিল আর আমরা তার সাথে ছিলাম, আর তার সাথে আমরা গর্ভবতী হয়ে পড়ি। অথবা তার আঙ্গুল আমাদের মধ্যে একজনকে সংকেত দেবে, সে জিতবেই, সে তাদের মেরে ফেলবে। আমি বলেছি, মাঝে মাঝে আমি তাকে দেখেছি, তুমি আগে যা বলেছ,","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى ‏ ‏قَالَ ‏ ‏اعْتَمَرَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَطَافَ ‏ ‏بِالْبَيْتِ ‏ ‏وَطُفْنَا مَعَهُ وَصَلَّى خَلْفَ ‏ ‏الْمَقَامِ ‏ ‏وَصَلَّيْنَا مَعَهُ ثُمَّ خَرَجَ فَطَافَ بَيْنَ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏وَنَحْنُ مَعَهُ نَسْتُرُهُ مِنْ أَهْلِ ‏ ‏مَكَّةَ ‏ ‏لَا يَرْمِيهِ أَحَدٌ ‏ ‏أَوْ يُصِيبُهُ أَحَدٌ ‏ ‏بِشَيْءٍ قَالَ فَدَعَا عَلَى الْأَحْزَابِ فَقَالَ ‏ ‏اللَّهُمَّ مُنْزِلَ الْكِتَابِ سَرِيعَ الْحِسَابِ هَازِمَ الْأَحْزَابِ اللَّهُمَّ اهْزِمْهُمْ وَزَلْزِلْهُمْ قَالَ وَرَأَيْتُ بِيَدِهِ ضَرْبَةً عَلَى سَاعِدِهِ فَقُلْتُ مَا هَذِهِ قَالَ ضُرِبْتُهَا يَوْمَ ‏ ‏حُنَيْنٍ ‏ ‏فَقُلْتُ لَهُ أَشَهِدْتَ مَعَهُ ‏ ‏حُنَيْنًا ‏ ‏قَالَ نَعَمْ وَقَبْلَ ذَلِكَ ‏","","",""],[18344,18344,"","আমরা একটা শিকারীর কথা বলেছি যে হয়তো আমাকে বলতে সক্ষম ছিল যে ভগবান আছে আর বলবে তোমার অনেক কারণ আছে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏مِسْعَرٌ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ فَيَّاضٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏اللَّهُمَّ لَكَ الْحَمْدُ كَثِيرًا طَيِّبًا مُبَارَكًا فِيهِ ‏","","",""],[18345,18345,"","আমরা কথা বলেছিলাম, আমার বাবা বা বাবা ছিল, নবী ঈশ্বরের কাছে প্রার্থনা করছিলেন যদি তিনি ভুল করেছেন। তিনি আমার বাবার বাবা-মা'র কাছে বলেছেন।","‏ ‏حَدَّثَنَا ‏ ‏وَهْبُ بْنُ جَرِيرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى ‏ ‏وَكَانَ مِنْ ‏ ‏أَصْحَابِ الشَّجَرَةِ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَتَاهُ قَوْمٌ ‏ ‏بِصَدَقَةٍ ‏ ‏قَالَ اللَّهُمَّ ‏ ‏صَلِّ ‏ ‏عَلَيْهِمْ فَأَتَاهُ أَبِي ‏ ‏بِصَدَقَةٍ ‏ ‏فَقَالَ اللَّهُمَّ ‏ ‏صَلِّ ‏ ‏عَلَى آلِ ‏ ‏أَبِي أَوْفَى ‏","","",""],[18346,18346,"","আমরা রাজার পর্দার কথা বলেছি... ...কিন্তু আমরা একটা সময় অতিবাহিত করেছি, ঈশ্বর হয়তো আমার বাবা অথবা তিনি বলেন যে একজন মানুষ প্রভুর প্রভুর প্রভুর গর্ভে এসেছেন। প্রভু তার কাছে প্রার্থনা করেছেন এবং লর্ডের শান্তি জয় করেছেন। আমি বড় হয়েছি এবং সৃষ্টিকর্তা তার কাছে প্রার্থনা করছি, তার মহিমা এবং মহান মহান প্রভু তাঁর নীরবতার আলো আছে। ঈশ্বরের অনুগ্রহে সে ব্যর্থ হয়েছে, তার ইচ্ছা প্রভু তার কাছে পেশ করা হবে. সবচেয়ে জোরে যেটা আপনি আগে কখনও দেখেননি তার উপর ভয় পাওয়ার আগ পর্যন্ত, মনে হয় আমরা একটু বেশিই করতে পেরেছি, ঈশ্বরের পুত্র বা বাবার ছেলে সম্পর্কে ঈশ্বর খুশি।","‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عَبْدِ الْمَلِكِ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ إِيَادِ بْنِ لَقِيطٍ ‏ ‏حَدَّثَنَا ‏ ‏إِيَادٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ وَنَحْنُ فِي الصَّفِّ خَلْفَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَدَخَلَ فِي الصَّفِّ فَقَالَ اللَّهُ أَكْبَرُ كَبِيرًا وَسُبْحَانَ اللَّهِ ‏ ‏بُكْرَةً ‏ ‏وَأَصِيلًا ‏ ‏قَالَ فَرَفَعَ الْمُسْلِمُونَ رُءُوسَهُمْ وَاسْتَنْكَرُوا الرَّجُلَ وَقَالُوا مَنْ الَّذِي يَرْفَعُ صَوْتَهُ فَوْقَ صَوْتِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمَّا انْصَرَفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ مَنْ هَذَا ‏ ‏الْعَالِي ‏ ‏الصَّوْتَ فَقِيلَ هُوَ ذَا يَا رَسُولَ اللَّهِ فَقَالَ وَاللَّهِ لَقَدْ ‏ ‏رَأَيْتُ كَلَامَكَ يَصْعَدُ فِي السَّمَاءِ حَتَّى فُتِحَ بَابٌ فَدَخَلَ فِيهِ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏حَدَّثَنَاه ‏ ‏جَعْفَرُ بْنُ حُمَيْدٍ الْكُوفِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ إِيَادِ بْنِ لَقِيطٍ ‏ ‏عَنْ ‏ ‏إِيَادٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى ‏ ‏مِثْلَهُ ‏","","",""],[18347,18347,"","আমার জীবনের সবচেয়ে গুরুত্বপূর্ণ বিষয় হল, আমি যিহোবার কাছে প্রার্থনা করি । চোর বলে অথবা পরামর্শ দেয় যে, ঈশ্বর একজন ব্যক্তিকে জয় করেছেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنِي ‏ ‏مَالِكٌ يَعْنِي ابْنَ مِغْوَلٍ ‏ ‏عَنْ ‏ ‏طَلْحَةَ بْنِ مُصَرِّفٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ أَبِي أَوْفَى ‏ ‏هَلْ أَوْصَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَا قُلْتُ فَلِمَ كُتِبَ عَلَى الْمُسْلِمِينَ الْوَصِيَّةُ ‏ ‏أَوْ لِمَ أُمِرُوا بِالْوَصِيَّةِ ‏ ‏قَالَ أَوْصَى بِكِتَابِ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[18348,18348,"","আমরা বাবা-মা'র সাথে কথা বলেছি, না হয় আমরা আমার ছেলে সম্পর্কে এত ভালো হয়ে গেছি, বা সে কিভাবে ঈশ্বরের পথে যাবে, সে বলবে, তোমাকে কিছু একটা ছেড়ে দিতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏مِسْعَرٌ ‏ ‏عَنْ ‏ ‏عُبَيْدِ بْنِ حَسَنٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي أَوْفَى ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏اللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ مِلْءَ السَّمَاوَاتِ وَمِلْءَ الْأَرْضِ وَمِلْءَ مَا شِئْتَ مِنْ شَيْءٍ بَعْدُ ‏","","",""],[18349,18349,"","আমরা বাবার ছেলে বা কি ভাবে সে বলেছে, ঈশ্বর বলে দিয়েছেন আমি পবিত্র পিতার কাছ থেকে এমন কিছু নিতে পারবো না যা আমার ভালোর জন্য করতে পারবে না। ঈশ্বর কখনো বলেন নি বা কখনো করেন নি। সে আমাকে আমার সাহস দেখতে দেবে না, হয়তো সে বলেছে আমি আমার বাবার কিছু বুঝতে পারব।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏مِسْعَرٌ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ السَّكْسَكِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي أَوْفَى ‏ ‏قَالَ ‏ ‏أَتَى رَجُلٌ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ إِنِّي لَا أَسْتَطِيعُ أَنْ آخُذَ مِنْ الْقُرْآنِ شَيْئًا فَعَلِّمْنِي شَيْئًا يُجْزِئُنِي مِنْ الْقُرْآنِ قَالَ ‏ ‏سُبْحَانَ اللَّهِ وَالْحَمْدُ لِلَّهِ وَلَا إِلَهَ إِلَّا اللَّهُ وَاللَّهُ أَكْبَرُ وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ قَالَ فَذَهَبَ ‏ ‏أَوْ قَامَ أَوْ نَحْوَ ذَا ‏ ‏قَالَ هَذَا لِلَّهِ عَزَّ وَجَلَّ فَمَا لِي قَالَ قُلْ اللَّهُمَّ اغْفِرْ لِي وَارْحَمْنِي وَعَافِنِي وَاهْدِنِي وَارْزُقْنِي ‏ ‏أَوْ ارْزُقْنِي وَاهْدِنِي وَعَافِنِي ‏ ‏قَالَ ‏ ‏مِسْعَرٌ ‏ ‏وَرُبَّمَا قَالَ اسْتَفْهَمْتُ بَعْضَهُ مِنْ ‏ ‏أَبِي خَالِدٍ يَعْنِي الدَّالَانِيَّ ‏","","",""],[18350,18350,"","ঈশ্বর তা করতে পারেন এবং বলবেন যে, তাদেরকে এমন কিছু পূর্ণ করতে হবে, যা পৃথিবীকে পরিপূর্ণ করবে ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏مِسْعَرٌ ‏ ‏عَنْ ‏ ‏عُبَيْدِ بْنِ حَسَنٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ أَبِي أَوْفَى ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏اللَّهُمَّ لَكَ الْحَمْدُ مِلْءَ السَّمَاءِ وَمِلْءَ الْأَرْضِ وَمِلْءَ مَا شِئْتَ مِنْ شَيْءٍ بَعْدُ ‏","","",""],[18351,18351,"","আমরা সবাই ঈশ্বর বা বাবা হবার জন্য বোকা হওয়ার কথা বলেছি, যে মেয়ে তার অন্ত্যেষ্টিক্রিয়ার সময় এমন কিছু করতে পারেনি, যা সে করতে পারত. তাকে আদেশ দেওয়া হয়েছিল, আর তারপর তাদের মধ্যে একজন এটা পার হয়ে গেল।","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ الْهَجَرِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى ‏ ‏وَكَانَ مِنْ ‏ ‏أَصْحَابِ الشَّجَرَةِ ‏ ‏فَمَاتَتْ ابْنَةٌ لَهُ وَكَانَ يَتْبَعُ جِنَازَتَهَا عَلَى بَغْلَةٍ خَلْفَهَا فَجَعَلَ النِّسَاءُ يَبْكِينَ فَقَالَ لَا ‏ ‏تَرْثِينَ ‏ ‏فَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏الْمَرَاثِي ‏ ‏فَتُفِيضُ إِحْدَاكُنَّ مِنْ عَبْرَتِهَا مَا شَاءَتْ ثُمَّ كَبَّرَ عَلَيْهَا أَرْبَعًا ثُمَّ قَامَ بَعْدَ الرَّابِعَةِ قَدْرَ مَا بَيْنَ التَّكْبِيرَتَيْنِ يَدْعُو ثُمَّ قَالَ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَصْنَعُ فِي الْجِنَازَةِ هَكَذَا ‏","","",""],[18352,18352,"","আমরা একটা Moos বিচারকের জন্য চেষ্টা করেছি যে আমার বাবা হয়তো তার নাম শুনেছেন. আমার Monadon পুত্র আমার বাবার একটি ছেলে যে ছেলে আছে তার সাথে ঈশ্বরের কথা জিততে পারে ঈশ্বরের পুত্র, তাঁর যোগ্যতা অর্জন করতে ঈশ্বরের ইচ্ছা আছে।","‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ مُوسَى ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏الْحَكَمِ ‏ ‏قَالَ ثَنَا ‏ ‏ابْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏أَبِي النَّضْرِ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ مَعْمَرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُحِبُّ أَنْ يَنْهَضَ إِلَى عَدُوِّهِ عِنْدَ زَوَالِ الشَّمْسِ ‏","","",""],[18353,18353,"","আমরা আবেগ দিয়ে বাপ্তাইজিত হয়েছি... ...আমার প্রভুর ইচ্ছার অন্ধকার নিয়ে। ঈশ্বরের আদেশ হলো তার আদেশ, আর তিনি সবুজদের জন্য আত্মসমর্পণ করেছেন... আমি চাইনি।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ الشَّيْبَانِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ أَبِي أَوْفَى ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْجَرِّ ‏ ‏الْأَخْضَرِ ‏ ‏قَالَ ‏ ‏قُلْتُ الْأَبْيَضُ قَالَ لَا أَدْرِي ‏","","",""],[18354,18354,"","আমরা ইশ্বরের সাথে কথা বলেছি, কিন্তু আমার বাবা, আমার হিপপোকে নিয়ে আমি ভীত। ভালো প্রভু, আমার বাবা অথবা বাবা, ঈশ্বরের অনুগ্রহে ঈশ্বর তাকে আদেশ দিয়েছেন এবং তার চাকরের কাছে সমর্পণ করেছেন। তাকে হতাশ করেছি, আমরা নই।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ صَاحِبُ الْهَرَوِيِّ وَاسْمُهُ عُبَيْدُ اللَّهِ بْنُ زِيَادٍ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْمَاعِيلُ بْنُ أَبِي خَالِدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى ‏ ‏قَالَ ‏ ‏بَشَّرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَدِيجَةَ ‏ ‏بِبَيْتٍ فِي الْجَنَّةِ مِنْ ‏ ‏قَصَبٍ ‏ ‏لَا ‏ ‏صَخَبَ ‏ ‏فِيهِ وَلَا ‏ ‏نَصَبَ ‏","","",""],[18355,18355,"","আমি বলেছিলাম, আমার বাবা অথবা বাবা ঈশ্বরের কাছে প্রার্থনা করেছেন আর সেই প্রতিবেশীদের কাছে পৌঁছে দেওয়া হবে, যারা আগুনের পথ থেকে কষ্ট ভোগ করবে । জানি না।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ الشَّيْبَانِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْهَى عَنْ ‏ ‏الْجَرِّ ‏ ‏الْأَخْضَرِ ‏ ‏يَعْنِي ‏ ‏النَّبِيذَ ‏ ‏فِي ‏ ‏الْجَرِّ ‏ ‏الْأَخْضَرِ ‏ ‏قَالَ ‏ ‏قُلْتُ فَالْأَبْيَضُ قَالَ لَا أَدْرِي ‏","","",""],[18356,18356,"","আমরা আমার বাবাকে ঈশ্বরের কাছে বলা হয়েছে। ঈশ্বর দাবি করেছেন, তিনি একজন অভিজ্ঞ ছেলের মৃত্যুতে জিতে গেছেন। আমরা একটি ছেলের সাথে ঘুমাবো।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْمَاعِيلُ بْنُ أَبِي خَالِدٍ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِعَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى ‏ ‏أَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَشَّرَ ‏ ‏خَدِيجَةَ ‏ ‏قَالَ نَعَمْ ‏ ‏بِبَيْتٍ مِنْ ‏ ‏قَصَبٍ ‏ ‏لَا ‏ ‏صَخَبَ ‏ ‏فِيهِ وَلَا ‏ ‏نَصَبَ ‏","","",""],[18357,18357,"","ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তিনি বিকেলের প্রথম স্থানে দাঁড়িয়ে আছেন । যতক্ষণ না তাকে বিষ দেয়া হয়।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جُحَادَةَ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَقُومُ فِي الرَّكْعَةِ الْأُولَى مِنْ صَلَاةِ الظُّهْرِ حَتَّى لَا يُسْمَعَ وَقْعُ قَدَمٍ ‏","","",""],[18358,18358,"","আমরা একটা ছেলের কথা বলেছিলাম যে আমার বাবা অথবা বাবা ঈশ্বরের সাথে খারাপ কথা বলছিল... ...অথবা সে তার নামে ঈশ্বরের কাছে প্রার্থনা করলো... ...তারা তার শান্তি কামনা করলো আর তারা হাল ছেড়ে দিত প্রভুর ভাগ্যের.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ ثَابِتٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْبَرَاءَ ‏ ‏وَعَبْدَ اللَّهِ بْنَ أَبِي أَوْفَى ‏ ‏أَنَّهُمْ ‏ ‏أَصَابُوا حُمُرًا فَطَبَخُوهَا قَالَ فَنَادَى مُنَادِي رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَكْفِئُوا الْقُدُورَ ‏","","",""],[18359,18359,"","আমরা আমাদের ভগবানের দাসকে বাঁচাতে চেষ্টা করেছি... ...আমরা ঈশ্বরের সেবা করার জন্য, আমি হাসপাতালে যাচ্ছি, তারপর লর্ডকে মুভিতে পরিণত করবো, ঈশ্বর বড় হয়েছেন, আর আল্লাহ বড় হয়েছেন। তার নীরবতা ঈশ্বরের কাছে ঘোষণা করে যে, ভাববাদী হিসেবে তিনি নিজেকে উৎসর্গ করেছেন । ইঞ্জেকশন, ঈশ্বরের বলা হয়েছে, তিনি নির্বাচিত না হওয়া পর্যন্ত ঈশ্বর আপনার মুখ উদিত হতে দেখেছেন।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ إِيَادٍ ‏ ‏حَدَّثَنَا ‏ ‏إِيَادٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ نَابِي ‏ ‏يَعْنِي ‏ ‏نَائِي ‏ ‏وَنَحْنُ فِي الصَّفِّ خَلْفَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَدَخَلَ فِي الصَّفِّ ثُمَّ قَالَ اللَّهُ أَكْبَرُ كَبِيرًا وَسُبْحَانَ اللَّهِ ‏ ‏بُكْرَةً ‏ ‏وَأَصِيلًا ‏ ‏فَرَفَعَ الْمُسْلِمُونَ رُءُوسَهُمْ وَاسْتَنْكَرُوا الرَّجُلَ فَقَالُوا مَنْ الَّذِي يَرْفَعُ صَوْتَهُ فَوْقَ صَوْتِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمَّا انْصَرَفَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ مَنْ هَذَا ‏ ‏الْعَالِي ‏ ‏الصَّوْتَ قَالَ هُوَ ذَا يَا رَسُولَ اللَّهِ قَالَ وَاللَّهِ لَقَدْ ‏ ‏رَأَيْتُ كَلَامَكَ يَصْعَدُ فِي السَّمَاءِ حَتَّى فُتِحَ بَابٌ مِنْهَا فَدَخَلَ فِيهِ ‏","","",""],[18360,18360,"","ঈশ্বর আমার বাবা অথবা আমার বাবা হয়তো সেখানে একটা শকুন থাকতে পারেন । যদি তুমি বলো সে ঘুমিয়ে আছে, সে হয়তো বলবে সে কি বলে সে অন্ধ, যদি সে যুদ্ধ করে, সে বলে সে আমাকে ঈশ্বরের অনুগ্রহের উপর পাথর ছুঁড়তে, সে ঈশ্বরের কাছে প্রার্থনা করে, সে অবশ্যই করবে। আর সে আত্মসমর্পণ করবে, ঈশ্বরের কাছে আছে আর আমাকে আদেশ করবে যেন তাদের হত্যা করা হয়।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنِي ‏ ‏سَعِيدُ بْنُ جُمْهَانٍَ ‏ ‏قَالَ ‏ ‏كُنَّا نُقَاتِلُ ‏ ‏الْخَوَارِجَ ‏ ‏وَفِينَا ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي أَوْفَى ‏ ‏وَقَدْ لَحِقَ لَهُ غُلَامٌ ‏ ‏بِالْخَوَارِجِ ‏ ‏وَهُمْ مِنْ ذَلِكَ الشَّطِّ وَنَحْنُ مِنْ ذَا الشَّطِّ فَنَادَيْنَاهُ ‏ ‏أَبَا فَيْرُوزَ ‏ ‏أَبَا فَيْرُوزَ ‏ ‏وَيْحَكَ ‏ ‏هَذَا مَوْلَاكَ ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي أَوْفَى ‏ ‏قَالَ نِعْمَ الرَّجُلُ هُوَ لَوْ هَاجَرَ قَالَ مَا يَقُولُ عَدُوُّ اللَّهِ قَالَ قُلْنَا يَقُولُ نِعْمَ الرَّجُلُ لَوْ هَاجَرَ قَالَ فَقَالَ أَهِجْرَةٌ بَعْدَ هِجْرَتِي مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏طُوبَى ‏ ‏لِمَنْ قَتَلَهُمْ وَقَتَلُوهُ ‏","","",""],[18361,18361,"","আমরা বাবার কথা বলেছিলাম আমি তোমার মুখ ভেঙ্গে ফেলব আর আমাকে যেতে হবে। কারণ সে বলেছে তার প্রভুর দয়ায় তার হৃদয় আঘাত পেয়েছে। গান।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي يَعْفُورٍ ‏ ‏قَالَ ‏ ‏سَأَلَ شَرِيكِي وَأَنَا مَعَهُ ‏ ‏عَبْدَ اللَّهِ بْنَ أَبِي أَوْفَى ‏ ‏عَنْ الْجَرَادِ فَقَالَ لَا بَأْسَ بِهِ وَقَالَ ‏ ‏غَزَوْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَبْعَ غَزَوَاتٍ فَكُنَّا نَأْكُلُهُ ‏","","",""],[18362,18362,"","আমি বাবার কাছে সাহায্য চেয়েছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ الشَّيْبَانِيِّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏قَالَ ‏ ‏ذَكَرْتُ ‏ ‏لِعَبْدِ اللَّهِ ‏ ‏حَدِيثًا حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي أَوْفَى ‏ ‏فِي لُحُومِ الْحُمُرِ فَقَالَ ‏ ‏سَعِيدٌ ‏ ‏حَرَّمَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْبَتَّةَ ‏","","",""],[18363,18363,"","আমার বাবার কথা বলেছিলাম যে তার কান দিয়ে একটা ছেলেকে শিকার করতে হবে । সে হয়তো আমাকে যেতে বা বলতে পছন্দ করে। আমি তোমাকে বলছি তার সকল ববের কাছে যাওয়ার জন্য। আর আমরা নিচে নেমে পরবো।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏عَنْ ‏ ‏أَبِي عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏زِيَادُ بْنُ عِلَاقَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏جَرِيرَ بْنَ عَبْدِ اللَّهِ ‏ ‏قَامَ يَخْطُبُ يَوْمَ تُوُفِّيَ ‏ ‏الْمُغِيرَةُ بْنُ شُعْبَةَ ‏ ‏فَقَالَ عَلَيْكُمْ بِاتِّقَاءِ اللَّهِ عَزَّ وَجَلَّ وَالْوَقَارِ ‏ ‏وَالسَّكِينَةِ ‏ ‏حَتَّى يَأْتِيَكُمْ أَمِيرٌ فَإِنَّمَا ‏ ‏يَأْتِيكُمْ الْآنَ ثُمَّ قَالَ اشْفَعُوا لِأَمِيرِكُمْ فَإِنَّهُ كَانَ يُحِبُّ الْعَفْوَ وَقَالَ أَمَّا بَعْدُ فَإِنِّي أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ أُبَايِعُكَ عَلَى الْإِسْلَامِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَشْتَرِطُ عَلَى النُّصْحِ لِكُلِّ مُسْلِمٍ فَبَايَعْتُهُ عَلَى هَذَا وَرَبِّ هَذَا الْمَسْجِدِ إِنِّي لَكُمْ لَنَاصِحٌ جَمِيعًا ثُمَّ اسْتَغْفَرَ وَنَزَلَ ‏","","",""],[18364,18364,"","আমি বলেছিলাম, ঈশ্বর আমাকে খেলা ছেড়ে চলে যাবেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏عَاصِمُ بْنُ بَهْدَلَةَ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏جَرِيرِ بْنِ عَبْدِ اللَّهِ الْبَجَلِيِّ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ اشْتَرِطْ عَلَيَّ فَقَالَ ‏ ‏تَعْبُدُ اللَّهَ وَلَا تُشْرِكُ بِهِ شَيْئًا وَتُصَلِّي الصَّلَاةَ الْمَكْتُوبَةَ وَتُؤَدِّي الزَّكَاةَ الْمَفْرُوضَةَ وَتَنْصَحُ لِلْمُسْلِمِ وَتَبْرَأُ مِنْ الْكَافِرِ ‏","","",""],[18365,18365,"","আমরা একটা আবেগ নিয়ে কথা বলেছি যে একজন পাহাড়ীমানবের সাথে যুদ্ধ করেছে যে আমার সাথে কথা বলেছে, ঈশ্বর তার জন্য প্রার্থনা করেছেন আর তাদের শান্তির নামে আত্মসমর্পণ করেছেন।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏رَجُلٌ ‏ ‏عَنْ ‏ ‏طَارِقٍ التَّمِيمِيِّ ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّ بِنِسَاءٍ فَسَلَّمَ عَلَيْهِنَّ ‏","","",""],[18366,18366,"","আমরা কথা বলেছি দুই ছেলে বা ছেলে-মেয়েদের মধ্যে আমরা নই। মানে, আমরা নাকি একটা পুতুলের ছেলে। এটা থেকে.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏حَبِيبٍ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ شُبَيْلٍ ‏ ‏أَوْ ‏ ‏شِبْلٍ ‏ ‏قَالَ ‏ ‏أَبُو نُعَيْمٍ ‏ ‏الْمُغِيرَةُ بْنُ شُبَيْلٍ يَعْنِي ابْنَ عَوْفٍ ‏ ‏فِي هَذَا الْحَدِيثِ ‏ ‏عَنْ ‏ ‏جَرِيرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَيُّمَا عَبْدٍ ‏ ‏أَبَقَ ‏ ‏فَقَدْ بَرِئَتْ مِنْهُ ‏ ‏الذِّمَّةُ ‏","","",""],[18367,18367,"","আমি যখন তাকে বলি যে, আমি একজন যিহোবার সাক্ষি, তখন আমি তাকে জিজ্ঞেস করি, ‘ কেন? ’ আমরা যা বলছি তার সাথে আমরা যা কথা বলেছি তা না। আমার বাবার সাথে আমাদের বাবার মত কথা হয়েছে। তিনি দরজা দিয়ে প্রবেশ করেন, তারপর ভিতরে যান এবং বের হয়ে আসেন এবং বলেন, তিনি চলে যান ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَوْنِ بْنِ أَبِي جُحَيْفَةَ ‏ ‏عَنِ ‏ ‏الْمُنْذِرِ بْنِ جَرِيرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ سَنَّ فِي الْإِسْلَامِ سُنَّةً حَسَنَةً كَانَ لَهُ أَجْرُهَا وَأَجْرُ مَنْ عَمِلَ بِهَا مِنْ بَعْدِهِ مِنْ غَيْرِ أَنْ يُنْتَقَصَ مِنْ أُجُورِهِمْ شَيْءٌ وَمَنْ سَنَّ فِي الْإِسْلَامِ سُنَّةً سَيِّئَةً كَانَ عَلَيْهِ ‏ ‏وِزْرُهَا ‏ ‏وَوِزْرُ ‏ ‏مَنْ عَمِلَ بِهَا مِنْ بَعْدِهِ مِنْ غَيْرِ أَنْ يُنْتَقَصَ مِنْ ‏ ‏أَوْزَارِهِمْ ‏ ‏شَيْءٌ ‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَوْنَ بْنَ أَبِي جَحْفَةَ ‏ ‏عَنِ ‏ ‏الْمُنْذِرِ بْنِ جَرِيرٍ الْبَجَلِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كُنَّا عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي صَدْرِ النَّهَارِ فَذَكَرَهُ إِلَّا أَنَّهُ قَالَ فَأَمَرَ ‏ ‏بِلَالًا ‏ ‏فَأَذَّنَ ثُمَّ دَخَلَ ثُمَّ خَرَجَ ‏ ‏يُصَلِّي وَقَالَ كَأَنَّهُ مُذْهَبَةٌ ‏","","",""],[18368,18368,"","আমরা একটি কলসি জন্য একটি ছেলেকে একবারের জন্য পেতে চেষ্টা করা. আমরা যে যুক্তিগুলো নিয়ে কথা বলেছিলাম, সেগুলো নিয়ে আমরা কথা বলেছিলাম । ঘটনা সম্পর্কে.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنِ ‏ ‏الْحَجَّاجِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏زَاذَانَ ‏ ‏عَنْ ‏ ‏جَرِيرِ بْنِ عَبْدِ اللَّهِ الْبَجَلِيِّ ‏ ‏أَنَّ رَجُلًا جَاءَ فَدَخَلَ فِي الْإِسْلَامِ فَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُعَلِّمُهُ الْإِسْلَامَ وَهُوَ فِي مَسِيرِهِ فَدَخَلَ ‏ ‏خُفُّ ‏ ‏بَعِيرِهِ فِي ‏ ‏جُحْرِ ‏ ‏يَرْبُوعٍ ‏ ‏فَوَقَصَهُ ‏ ‏بَعِيرُهُ فَمَاتَ فَأَتَى عَلَيْهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏عَمِلَ قَلِيلًا وَأُجِرَ كَثِيرًا ‏ ‏قَالَهَا ‏ ‏حَمَّادٌ ‏ ‏ثَلَاثًا ‏ ‏اللَّحْدُ ‏ ‏لَنَا ‏ ‏وَالشَّقُّ ‏ ‏لِغَيْرِنَا ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجُ بْنُ أَرْطَاةَ ‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ الْبَجَلِيُّ ‏ ‏عَنْ ‏ ‏زَاذَانَ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[18369,18369,"","আমরা বাবার সাথে একটি ছেলের সঙ্গে একটি প্রান্তরে একটি ছেলেকে নক করতে আমার বাবার সঙ্গে একটি ভাল সময় কাটা সম্পর্কে কথা বলেছি। ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং আমার কমান্ডের হঠাৎ চেহারার জন্য তিনি আত্মসমর্পণ করবেন।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي زُرْعَةَ بْنِ عَمْرِو بْنِ جَرِيرٍ ‏ ‏قَالَ قَالَ ‏ ‏جَرِيرٌ ‏ ‏سَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ نَظْرَةِ ‏ ‏الْفَجْأَةِ ‏ ‏فَأَمَرَنِي أَنْ أَصْرِفَ بَصَرِي ‏","","",""],[18370,18370,"","আমরা একটা আবেগ দ্বারা বাপ্তাইজিত হয়েছি... ...যে তোমার বিষের সাথে ঈশ্বরের প্রেম নিয়ে একটা যুদ্ধের মধ্যে তোমার বিষ নিয়ে এসেছে, ঈশ্বর তার জন্য প্রার্থনা করেছেন আর আশ্বস্ত করেছেন তোমার বাবার কাছে আছে ঈশ্বর এটা দাবি করেছেন এবং সেই অসন্তুষ্ট লোকেদের কাছ থেকে এটা গ্রহণ করেছেন, যারা ঈশ্বরের প্রতি তার প্রিয় ও নিরস্ত্র লোকেদের প্রতি করুণা দেখায়নি ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سِمَاكِ بْنِ حَرْبٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ جَرِيرٍ ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏قَالَ ‏ ‏أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ أُبَايِعُكَ عَلَى الْإِسْلَامِ فَقَبَضَ يَدَهُ وَقَالَ ‏ ‏النُّصْحُ لِكُلِّ مُسْلِمٍ ثُمَّ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهُ مَنْ لَمْ يَرْحَمْ النَّاسَ لَمْ يَرْحَمْهُ اللَّهُ عَزَّ وَجَلَّ ‏","","",""],[18371,18371,"","আমরা একটি নির্দিষ্ট আবেগ তৈরি করেছি যা আমরা একটি ধারণা নিয়ে এসেছি যা একটি ধারণায় তুলে ধরেছি যা আমি একটি ভবিষ্যত সম্পর্কে শুনেছি। তিনি ঈশ্বরের ইচ্ছা এবং ইচ্ছার প্রতি তাঁর ইচ্ছার প্রতি প্রার্থনা করেছেন। প্রার্থনা করুন এবং শান্তির জন্য দয়া করুন।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا وَائِلٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏بَايَعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى إِقَامِ الصَّلَاةِ وَإِيتَاءِ الزَّكَاةِ وَالنُّصْحِ لِلْمُسْلِمِ وَعَلَى فِرَاقِ الْمُشْرِكِ ‏","","",""],[18372,18372,"","আমরা আবেগ নিয়ে কথা বলেছি যে আমার বাবা আর বড় বড়দের দেয়াল আর সম্মানের একটা কারণ নিয়ে এসেছি, ঈশ্বরের প্রার্থনা আর আপনার সব আত্মার আত্মাকে ঘৃণা করা উচিত।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏قَالَ ‏ ‏بَايَعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى إِقَامِ الصَّلَاةِ وَإِيتَاءِ الزَّكَاةِ وَالنُّصْحِ لِكُلِّ مُسْلِمٍ وَعَلَى فِرَاقِ الْمُشْرِكِ ‏ ‏أَوْ كَلِمَةٍ مَعْنَاهَا ‏","","",""],[18373,18373,"","আমরা আমাদের আবেগ দিয়ে বাপ্তাইজিত হয়েছি... ...আমরা যা শুনেছি তা শোনার রীতি নিয়ে... ...যা আমি বলি... ...এক বড় ভালুক, আল্লাহ তার জন্য প্রার্থনা করেছেন এবং যিনি তাকে আত্মসমর্পণ করেছেন মানুষকে সান্ত্বনা দাও.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا ظَبْيَانَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏جَرِيرٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ لَمْ يَرْحَمْ النَّاسَ لَمْ يَرْحَمْهُ اللَّهُ عَزَّ وَجَلَّ ‏","","",""],[18374,18374,"","আমরা বাবার দেয়ালের কথা বলেছিলাম, আল্লাহ জানেন তুমি কি বলতে চাচ্ছ তুমি তার সাথে এমন কিছু ভাগাভাগি করো না যেটা দিয়ে তুমি উল আর রঙ্গীন হবে না। আর সে শুরু থেকেই শুরু করে। ক্যাফার.","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمُ بْنُ بَهْدَلَةَ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏أَنَّ ‏ ‏جَرِيرًا ‏ ‏قَالَ ‏ ‏يَا رَسُولَ اللَّهِ اشْتَرِطْ عَلَيَّ قَالَ ‏ ‏تَعْبُدُ اللَّهَ لَا تُشْرِكُ بِهِ شَيْئًا وَتُصَلِّي الصَّلَاةَ الْمَكْتُوبَةَ وَتُؤَدِّي الزَّكَاةَ الْمَفْرُوضَةَ وَتَنْصَحُ الْمُسْلِمَ وَتَبْرَأُ مِنْ الْكَافِرِ ‏","","",""],[18375,18375,"","আমরা একটা স্বপ্নের জয় করার চেষ্টা করছিলাম... ...তোমার কাঁধে একটা বিশাল নখ থাকার জন্য, ভগবানের কাছে প্রার্থনা করতে শুনেছি, সে তাকে জানে আর সে বলবে যে খোদা মানুষকে মাফ করে দেবে না।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ جَرِيرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ لَا يَرْحَمُ مَنْ لَا يَرْحَمُ النَّاسَ ‏","","",""],[18376,18376,"","আমরা আপনার শিক্ষক সম্পর্কে তর্ক করেছি যে বাবা জাররা কাপুরুষের কথা শুনেছেন। আর তারপর সে তার পরিকল্পনা অনুযায়ী বলল, সে তোমাকে মারছে, কিছু লোক, কিছু লোক।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ مُدْرِكٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا زُرْعَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏جَرِيرٍ ‏ ‏وَهُوَ جَدُّهُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فِي حَجَّةِ الْوَدَاعِ يَا ‏ ‏جَرِيرُ ‏ ‏اسْتَنْصِتْ النَّاسَ ثُمَّ قَالَ فِي خُطْبَتِهِ ‏ ‏لَا تَرْجِعُوا بَعْدِي كُفَّارًا يَضْرِبُ بَعْضُكُمْ رِقَابَ بَعْضٍ ‏","","",""],[18377,18377,"","আমরা একটা সাধারণ লড়াই সম্বন্ধে কথা বলেছিলাম, যার অন্তর্ভুক্ত ছিল এবং সেই সময় আমরা কথা বলেছিলাম । তাদের দেখা উচিত ছিল পিছন দিক থেকে চালু করা।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏هَمَّامٍ ‏ ‏قَالَ ‏ ‏بَالَ ‏ ‏جَرِيرُ بْنُ عَبْدِ اللَّهِ ‏ ‏ثُمَّ تَوَضَّأَ وَمَسَحَ عَلَى خُفَّيْهِ فَقِيلَ لَهُ تَفْعَلُ هَذَا وَقَدْ بُلْتَ قَالَ نَعَمْ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَالَ ثُمَّ تَوَضَّأَ وَمَسَحَ عَلَى خُفَّيْهِ ‏ ‏قَالَ ‏ ‏إِبْرَاهِيمُ ‏ ‏فَكَانَ يُعْجِبُهُمْ هَذَا الْحَدِيثُ لِأَنَّ إِسْلَامَ ‏ ‏جَرِيرٍ ‏ ‏كَانَ بَعْدَ نُزُولِ ‏ ‏الْمَائِدَةِ ‏","","",""],[18378,18378,"","আমরা একটি ছেলে সম্পর্কে কথা বলেছি যে বেনকে শিকার করার ব্যাপারে কথা বলেছি এবং একজন প্রতিবেশীকে বলতে হবে, \"ঈশ্বর,\" তাকে আত্মসমর্পণ করতে হবে, যারা মানুষকে ঈশ্বরের প্রশংসা করতে পারবে না এবং আমরা করেছি। আমরা কারা, তা জানার চেষ্টা করেছি ।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ وَهْبٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏جَرِيرًا ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ لَا يَرْحَمْ النَّاسَ لَا يَرْحَمْهُ اللَّهُ عَزَّ وَجَلَّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ وَهْبٍ ‏ ‏عَنْ ‏ ‏جَرِيرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[18379,18379,"","আমরা এমন এক দাসের কথা বলেছি যার হাত একটি ভালো ছেলে সম্পর্কে কথা বলেছি এবং একটি দেয়ালে গিয়ে একটি দেয়ালে গিয়ে বলতে পারি ঈশ্বর যেন তা উদ্ধার করেছেন এবং উদ্ধার করেছেন যে মানুষদের সান্ত্বনা প্রদান করা হবে না। ঈশ্বর সেই সময় থেকে রক্ষা করেছেন, যখন আমরা রাজতন্ত্র তৈরি করেছি ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ وَهْبٍ ‏ ‏عَنْ ‏ ‏جَرِيرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ لَا يَرْحَمْ النَّاسَ لَا يَرْحَمْهُ اللَّهُ عَزَّ وَجَلَّ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي ظَبْيَانَ ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏مِثْلَ ذَلِكَ ‏","","",""],[18380,18380,"","আমি একজন চাকরের কথা বলেছিলাম যে আমাকে সাহায্য করার চেষ্টা করেছে, আমাকে না দেখার পর থেকে তাকে দেওয়া হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏قَيْسٍ ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏قَالَ ‏ ‏مَا حَجَبَنِي عَنْهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُنْذُ أَسْلَمْتُ وَلَا رَآنِي إِلَّا تَبَسَّمَ ‏","","",""],[18381,18381,"","আমরা আবেগে বাপ্তাইজিত হয়েছি, আমার বাবার জন্য নরকের জীবনের ভালোবাসা নিয়ে। ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তিনি যেদিন বলেছিলেন, সেদিনই তিনি আত্মসমর্পণ করবেন। ( প্রকাশিত বাক্য ১২: ৯) সেই ব্যক্তি হলেন যিশু খ্রিস্ট । তারা ভন্ডের থেকে এসেছে... ...আর তারপর সে বাইরে যায়... ...আর তারপর কান দিয়ে বের হল... ...আর যে তোমাকে শেষ নিঃশ্বাস থেকে ছেড়ে চলে যায়। তিনি কখনো তার বাড়ি থেকে একজন ব্যক্তিকে বিশ্বাস করতে পারেননি । ( খ) কীভাবে যিহোবা তাঁর লোকেদের জন্য তাঁর উদ্দেশ্য পরিপূর্ণ করার জন্য সাহায্য করেছেন? তার সেরা শপথের মাধ্যমে আমি এক বছরে এর সাথে কিছু করতে হবে. বাবার কবর, তার বাবার বাবা বলেছিলেন, আমরা লর্ডের লর্ডশিপে ওর কাছে প্রার্থনা করেছি... ...আর যেই দিন সে কথা বলেছিল, সে উঠে আসল, আর সে বললো যে সে নাকি তার বাবা। চলে যাচ্ছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَوْنِ بْنِ أَبِي جُحَيْفَةَ ‏ ‏عَنِ ‏ ‏الْمُنْذِرِ بْنِ جَرِيرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كُنَّا عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي صَدْرِ النَّهَارِ قَالَ فَجَاءَهُ قَوْمٌ حُفَاةٌ عُرَاةٌ ‏ ‏مُجْتَابِي ‏ ‏النِّمَارِ ‏ ‏أَوْ الْعَبَاءِ ‏ ‏مُتَقَلِّدِي ‏ ‏السُّيُوفِ عَامَّتُهُمْ مِنْ ‏ ‏مُضَرَ ‏ ‏بَلْ كُلُّهُمْ مِنْ ‏ ‏مُضَرَ ‏ ‏فَتَغَيَّرَ وَجْهُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِمَا رَأَى بِهِمْ مِنْ ‏ ‏الْفَاقَةِ ‏ ‏قَالَ فَدَخَلَ ثُمَّ خَرَجَ فَأَمَرَ ‏ ‏بِلَالًا ‏ ‏فَأَذَّنَ وَأَقَامَ فَصَلَّى ثُمَّ خَطَبَ فَقَالَ ‏ { ‏يَا أَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمْ الَّذِي خَلَقَكُمْ مِنْ نَفْسٍ وَاحِدَةٍ ‏ ‏إِلَى آخِرِ الْآيَةِ ‏ ‏إِنَّ اللَّهَ كَانَ عَلَيْكُمْ رَقِيبًا ‏} ‏وَقَرَأَ الْآيَةَ الَّتِي فِي ‏ ‏الْحَشْرِ ‏ { ‏وَلْتَنْظُرْ نَفْسٌ مَا قَدَّمَتْ لِغَدٍ ‏} ‏تَصَدَّقَ رَجُلٌ مِنْ دِينَارِهِ مِنْ دِرْهَمِهِ مِنْ ثَوْبِهِ مِنْ ‏ ‏صَاعِ ‏ ‏بُرِّهِ ‏ ‏مِنْ ‏ ‏صَاعِ ‏ ‏تَمْرِهِ حَتَّى قَالَ وَلَوْ ‏ ‏بِشِقِّ ‏ ‏تَمْرَةٍ قَالَ فَجَاءَ رَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏بِصُرَّةٍ كَادَتْ كَفُّهُ تَعْجِزُ عَنْهَا بَلْ قَدْ عَجَزَتْ ثُمَّ تَتَابَعَ النَّاسُ حَتَّى رَأَيْتُ كَوْمَيْنِ مِنْ طَعَامٍ وَثِيَابٍ حَتَّى رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَهَلَّلُ وَجْهُهُ ‏ ‏يَعْنِي كَأَنَّهُ ‏ ‏مُذْهَبَةٌ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ سَنَّ فِي الْإِسْلَامِ سُنَّةً حَسَنَةً فَلَهُ أَجْرُهَا وَأَجْرُ مَنْ عَمِلَ بِهَا بَعْدَهُ مِنْ غَيْرِ أَنْ يُنْتَقَصَ مِنْ أُجُورِهِمْ شَيْءٌ وَمَنْ سَنَّ فِي الْإِسْلَامِ سُنَّةً سَيِّئَةً كَانَ عَلَيْهِ ‏ ‏وِزْرُهَا ‏ ‏وَوِزْرُ ‏ ‏مَنْ عَمِلَ بِهَا بَعْدَهُ مِنْ غَيْرِ أَنْ يُنْتَقَصَ مِنْ ‏ ‏أَوْزَارِهِمْ ‏ ‏شَيْءٌ ‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَوْنَ بْنَ أَبِي جَحْفَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُنْذِرَ بْنَ جَرِيرٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كُنَّا عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَدْرَ النَّهَارِ فَذَكَرَهُ إِلَّا أَنَّهُ قَالَ وَأَمَرَ ‏ ‏بِلَالًا ‏ ‏فَأَذَّنَ ثُمَّ دَخَلَ ثُمَّ خَرَجَ فَصَلَّى وَقَالَ كَأَنَّهُ ‏ ‏مُذْهَبَةٌ ‏","","",""],[18382,18382,"","আমরা ঈশ্বরের কথা শোনার জন্য পাগল হয়ে যাচ্ছি, ঈশ্বর তাকে আদেশ দিয়েছেন আর আত্মসমর্পণ করেছেন যখন আমরা শহর থেকে জিতেছিলাম... ...যদি তাকে তার আদেশের আকৃতিতে রাখতে হয়। যাত্রীরা বলতে চায় যে লোকটি তাকে আত্মসমর্পণ করেছে। আমি তোমাকে চুমু দিতাম আমি তোমাকে বলতে চাই যে আমি ঈশ্বরকে বলতে চাই। তুমি কখনো দেখবে না যে ঈশ্বর আমাকে বিশ্বাস করে কি বলে। সে তার হাত দিয়ে রঙ করে আর সমাধিক্ষেত্র নিয়ে ব্যস্ত। তাকে মারার কথা দেয়া হয়েছিল, সে আগে কখনো বলেনি সে বলেছে সে শেষ হয়ে গেছে। সে আবার বলে যাবে, ঈশ্বরের কাছে প্রার্থনা করবে, নাকি সে দেখবে। সে শহরের পিছন থেকে এসেছে, আমি জানতাম সে ক্ষুধার্ত আর তার পর সে বলেছে ঈশ্বর এটা করেছেন। যারা বিশ্বাস করে তারা তাদের বিশ্বাস নরছে না। আমরা তাকে ধরে নিয়ে গিয়েছিলাম এবং তার প্রহরীর সঙ্গে দেখা করার জন্য তাকে রক্ষা করেছি । একমাত্র যদি একমাত্র মানুষ মুক্ত হত, আমরা বাবার করুণা নিয়ে কথা বলছিলাম, তার জীবনের মঙ্গলের ব্যাপারে যে ক্রোধ, আমরা ঈশ্বরের অনুগ্রহ নিয়ে বাইরে গিয়েছিলাম, আর সে শহর থেকে চলে যাবে যখন আমরা উড়িয়ে দেব তখন সে বলেছিল তার হাত দিয়ে হাত গুটিয়ে যায়, যারা ভাবে প্রতিবেশীরা তাকে তাই বলে।","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو جَنَابٍ ‏ ‏عَنْ ‏ ‏زَاذَانَ ‏ ‏عَنْ ‏ ‏جَرِيرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏خَرَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمَّا بَرَزْنَا مِنْ ‏ ‏الْمَدِينَةِ ‏ ‏إِذَا رَاكِبٌ يُوضِعُ نَحْوَنَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَأَنَّ هَذَا الرَّاكِبَ إِيَّاكُمْ يُرِيدُ قَالَ فَانْتَهَى الرَّجُلُ إِلَيْنَا فَسَلَّمَ فَرَدَدْنَا عَلَيْهِ فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ أَيْنَ أَقْبَلْتَ قَالَ مِنْ أَهْلِي وَوَلَدِي وَعَشِيرَتِي قَالَ فَأَيْنَ تُرِيدُ قَالَ أُرِيدُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَقَدْ أَصَبْتَهُ قَالَ يَا رَسُولَ اللَّهِ عَلِّمْنِي ‏ ‏مَا الْإِيمَانُ قَالَ تَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّ ‏ ‏مُحَمَّدًا ‏ ‏رَسُولُ اللَّهِ وَتُقِيمُ الصَّلَاةَ ‏ ‏وَتُؤْتِي الزَّكَاةَ وَتَصُومُ رَمَضَانَ وَتَحُجُّ ‏ ‏الْبَيْتَ ‏ ‏قَالَ قَدْ أَقْرَرْتُ قَالَ ثُمَّ إِنَّ بَعِيرَهُ دَخَلَتْ يَدُهُ فِي شَبَكَةِ ‏ ‏جُرْذَانٍ ‏ ‏فَهَوَى بَعِيرُهُ وَهَوَى الرَّجُلُ فَوَقَعَ عَلَى ‏ ‏هَامَتِهِ ‏ ‏فَمَاتَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَيَّ بِالرَّجُلِ قَالَ ‏ ‏فَوَثَبَ ‏ ‏إِلَيْهِ ‏ ‏عَمَّارُ بْنُ يَاسِرٍ ‏ ‏وَحُذَيْفَةُ ‏ ‏فَأَقْعَدَاهُ فَقَالَا يَا رَسُولَ اللَّهِ قُبِضَ الرَّجُلُ قَالَ فَأَعْرَضَ عَنْهُمَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ قَالَ لَهُمَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَا رَأَيْتُمَا إِعْرَاضِي عَنْ الرَّجُلَيْنِ فَإِنِّي رَأَيْتُ مَلَكَيْنِ يَدُسَّانِ فِي ‏ ‏فِيهِ مِنْ ثِمَارِ الْجَنَّةِ فَعَلِمْتُ أَنَّهُ مَاتَ جَائِعًا ثُمَّ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَذَا وَاللَّهِ مِنْ الَّذِينَ قَالَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏الَّذِينَ آمَنُوا وَلَمْ يَلْبِسُوا إِيمَانَهُمْ بِظُلْمٍ أُولَئِكَ لَهُمْ الْأَمْنُ وَهُمْ مُهْتَدُونَ ‏} ‏قَالَ ثُمَّ قَالَ دُونَكُمْ أَخَاكُمْ قَالَ فَاحْتَمَلْنَاهُ إِلَى الْمَاءِ فَغَسَّلْنَاهُ وَحَنَّطْنَاهُ وَكَفَّنَّاهُ وَحَمَلْنَاهُ إِلَى الْقَبْرِ قَالَ فَجَاءَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى جَلَسَ عَلَى شَفِيرِ الْقَبْرِ قَالَ فَقَالَ ‏ ‏أَلْحِدُوا ‏ ‏وَلَا ‏ ‏تَشُقُّوا ‏ ‏فَإِنَّ ‏ ‏اللَّحْدَ ‏ ‏لَنَا ‏ ‏وَالشَّقَّ ‏ ‏لِغَيْرِنَا ‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْحَمِيدِ بْنُ أَبِي جَعْفَرٍ الْفَرَّاءُ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏زَاذَانَ ‏ ‏عَنْ ‏ ‏جَرِيرِ بْنِ عَبْدِ اللَّهِ الْبَجَلِيِّ ‏ ‏قَالَ ‏ ‏خَرَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏الْمَدِينَةِ ‏ ‏فَبَيْنَا نَحْنُ نَسِيرُ إِذْ رَفَعَ لَنَا شَخْصٌ فَذَكَرَ نَحْوَهُ إِلَّا أَنَّهُ قَالَ وَقَعَتْ يَدُ ‏ ‏بَكْرِهِ ‏ ‏فِي بَعْضِ تِلْكَ الَّتِي تَحْفِرُ ‏ ‏الْجُرْذَانُ ‏ ‏وَقَالَ فِيهِ هَذَا مِمَّنْ عَمِلَ قَلِيلًا وَأُجِرَ كَثِيرًا ‏","","",""],[18383,18383,"","আমি আত্মসমর্পণ করার পর থেকে ঈশ্বর আমাকে উদ্ধার করেছেন এবং আমাকে বিষ খেতে দেখেননি ।","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏حَدَّثَنَا ‏ ‏بَيَانُ ‏ ‏عَنْ ‏ ‏قَيْسٍ ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏قَالَ ‏ ‏مَا حَجَبَنِي النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُنْذُ أَسْلَمْتُ وَلَا رَآنِي إِلَّا تَبَسَّمَ ‏","","",""],[18384,18384,"","আমি যখন আত্মসমর্পণ করার সময় থেকে ঈশ্বর আমাকে উদ্ধার করেছেন এবং আমার মুখে হাসি না দেখেও আমার প্রতি খুশি হয়নি ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنِي ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏قَيْسٍ ‏ ‏عَنْ ‏ ‏جَرِيرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏مَا حَجَبَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُنْذُ أَسْلَمْتُ وَلَا رَآنِي إِلَّا تَبَسَّمَ فِي وَجْهِي ‏","","",""],[18385,18385,"","আমার স্বামী আমার পোশাক পরে আমার পোশাক পরেছিল এবং আমি আমার পোশাক পরতে পেরেছিলাম আর এরপর ঈশ্বর যদি তা - ই করতেন, তা হলে আমি সেই ব্যক্তির ঈর্ষা সম্বন্ধে কথা বলতাম । আমি আমার গ্রেসকে আগেই বলেছি, কিন্তু আমি ভেবেছিলাম ঈশ্বর এটা করতে পারতেন। যখন সে তাকে তার ডিজাইনে প্রস্তাব দিতে চায়... ...আর বলে সে তোমাকে এই দরজা থেকে বের হতে দেবে না, না হয় আমি চলে যাবো। আমার রাজাকে ক্ষমা করে দিতে হবে আর বলতে চাই আমি এটা পছন্দ করি, অথবা আমরা একটি হিংসার ছেলে, যে আমাদের সাথে কথা বলেছে, যখন আমরা বড় বাবা হওয়ার চেষ্টা করেছি, তখন আমি তাকে ক্ষমা করতে চাই। কিন্তু তারপর আমি আমার বাবার মত করে বলি। হে আমার ভালোবাসা ফিরে গেল, সে ঈশ্বরের কাছে গেল, আর তিনি তার মঙ্গলের জন্য তোমাদের কাছে সমর্পণ করবেন, আর তিনি আমার কাছে প্রতিজ্ঞা করেছেন, তিনি আমার অনুগ্রহের কথা বলেছেন। তিনি কি প্রভুর টাকা উল্লেখ করেছেন? তাকে আমার আদেশ থেকে উদ্ধার করতে বলেছে?","‏ ‏حَدَّثَنَا ‏ ‏أَبُو قَطَنٍ ‏ ‏حَدَّثَنِي ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ شِبْلٍ ‏ ‏قَالَ وَقَالَ ‏ ‏جَرِيرٌ ‏ ‏لَمَّا ‏ ‏دَنَوْتُ ‏ ‏مِنْ ‏ ‏الْمَدِينَةِ ‏ ‏أَنَخْتُ ‏ ‏رَاحِلَتِي ‏ ‏ثُمَّ حَلَلْتُ عَيْبَتِي ثُمَّ لَبِسْتُ ‏ ‏حُلَّتِي ‏ ‏ثُمَّ دَخَلْتُ فَإِذَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْطُبُ فَرَمَانِي النَّاسُ ‏ ‏بِالْحَدَقِ ‏ ‏فَقُلْتُ لِجَلِيسِي يَا عَبْدَ اللَّهِ ذَكَرَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ نَعَمْ ذَكَرَكَ ‏ ‏آنِفًا ‏ ‏بِأَحْسَنِ ذِكْرٍ فَبَيْنَمَا هُوَ يَخْطُبُ إِذْ عَرَضَ ‏ ‏لَهُ فِي خُطْبَتِهِ وَقَالَ ‏ ‏يَدْخُلُ عَلَيْكُمْ مِنْ هَذَا الْبَابِ ‏ ‏أَوْ مِنْ هَذَا ‏ ‏الْفَجِّ ‏ ‏مِنْ خَيْرِ ذِي يَمَنٍ إِلَّا أَنَّ عَلَى وَجْهِهِ ‏ ‏مَسْحَةَ مَلَكٍ ‏ ‏قَالَ ‏ ‏جَرِيرٌ ‏ ‏فَحَمِدْتُ اللَّهَ عَزَّ وَجَلَّ عَلَى مَا أَبْلَانِي ‏ ‏و قَالَ ‏ ‏أَبُو قَطَنٍ ‏ ‏فَقُلْتُ لَهُ سَمِعْتَهُ مِنْهُ ‏ ‏أَوْ سَمِعْتَهُ مِنْ ‏ ‏الْمُغِيرَةِ بْنِ شِبْلٍ ‏ ‏قَالَ نَعَمْ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ شُبَيْلِ بْنِ عَوْفٍ ‏ ‏عَنْ ‏ ‏جَرِيرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏لَمَّا ‏ ‏دَنَوْتُ ‏ ‏مِنْ ‏ ‏الْمَدِينَةِ ‏ ‏أَنَخْتُ ‏ ‏رَاحِلَتِي ‏ ‏ثُمَّ حَلَلْتُ ‏ ‏عَيْبَتِي ‏ ‏ثُمَّ لَبِسْتُ ‏ ‏حُلَّتِي ‏ ‏قَالَ فَدَخَلْتُ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْطُبُ فَسَلَّمْتُ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَرَمَانِي الْقَوْمُ ‏ ‏بِالْحَدَقِ ‏ ‏فَقُلْتُ لِجَلِيسِي هَلْ ذَكَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ أَمْرِي شَيْئًا ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[18386,18386,"","আমরা বাবার সবচেয়ে ভালোটার ব্যাপারে কথা বলেছি, আমাদের সাথে তার মন্দ সম্পর্কে আমাদের কথা বলেছি। ঈশ্বর জানেন আর আমি এটা নিয়ে নেব যে সিংহাসনের সাথে ভাগ করা হবে না। তোমার রাজত্বের রাজা হবে পৃথিবীর রাজা.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏أَنَّهُ ‏ ‏حِينَ بَايَعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخَذَ عَلَيْهِ أَنْ ‏ ‏لَا يُشْرِكَ بِاللَّهِ شَيْئًا وَيُقِيمَ الصَّلَاةَ وَيُؤْتِيَ الزَّكَاةَ وَيَنْصَحَ الْمُسْلِمَ وَيُفَارِقَ الْمُشْرِكَ ‏","","",""],[18387,18387,"","আমরা আলোচনা করেছিলাম যে, ঈশ্বর কেমন হবেন, সেই বিষয়ে আমরা কীভাবে একে অন্যকে বলেছিলাম । ''তুমি নিশ্চয়ই সেই, হে সঠিক পথে অবস্থান, ''নিঃসন্দেহ তোমরা, হে তোমাদের সম্প্রদায়! কে তোমাদের মৃত্যুমুখে? তবে পাছে তোমরা সীমা ছাড়িয়ে যাবে।’’ আঘাতপ্রাপ্ত আঘাতপ্রাপ্ত আঘাতপ্রাপ্ত আঘাতপ্রাপ্ত আঘাত হে হেব ্ যক ্ ত বয়স ্ ক - > বিপরীত দিশায় পুনরায় আঘাত আঘাত কর । এরপর তোমরা থ থ থ থ থ থ থ থ থ থ দাও , পুনরায় আঘাত কর । তের জন ত ত তেরী ত তপ্ত তের উপর আঘাত কর থ থ থ থ থ থকে তর ত তের উপর থ থ থো ত ত ত ত ত ত ত ত ত ত ত ত ত ত ত ত তেরেরের উপর থ থ থ থো ত ত ত ত ত ত ত তরেরেরের ত ত ত ত ত ত ত ত ত ত তবারেরেরেরেরেরেরেরেরের ত তারপর তারপর তারা ভুল করেছিল, তারা বলেছিল, তারা বলেছিল, তারা বলেছিল, \"ঈশ্বরের সামনে প্রার্থনা কর, তিনি শান্তিতে আছেন।\" তিনি পাগল হয়ে যান এবং তারপর বলেন, তিনি অন্ধকার অন্ধকারে তার পরে কিছু করেছেন। যা আমি কলমে পেয়েছি। আমি তার পেছনে কিছু একটা আছে। আমি তাকে বলি, আমি তাকে বলি, \"আমি আল্লাহ্‌র কাছে প্রার্থনা করি, \"সে শান্তিতে\" এবং তার মনের কথা বলতে চাই।\" এবং তারপর তিনি পাগল হয়ে গেল, \"আমি আমার মনের কথা বলি, \"আমি জানি না যে,\" এবং আমি যদি আমার মনের কথা বলি, \"আমি তাকে বলি,\" এবং আমি যদি আমার মনের কথা বলি, তাহলে আমি যদি আমার মনের কথা বলি, তাহলে আমি আমার মনের কথা বলি, \"আমি শুধু বিশ্বাস করি,\" এবং আমার মনের কথা বলি, আমি যদি আমার মনের মধ্যে শান্তি পাই, তাহলে আমি আমার মনের কথা বলি,\" এবং আমার মনের মধ্যে শান্তি এবং আমার মনের শান্তি যেন আমি যদি আমার মনের মধ্যে শান্তি পায়, তাহলে আমি আমার মনের শান্তি ফিরে যাই।\" বছরটা দিয়ে চলবে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ هِلَالٍ ‏ ‏عَنْ ‏ ‏جَرِيرِ بْنِ عَبْدِ اللَّهِ الْبَجَلِيِّ ‏ ‏أَنَّ رَجُلًا مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏جَاءَ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِصُرَّةٍ ‏ ‏مِنْ ذَهَبٍ تَمْلَأُ مَا بَيْنَ أَصَابِعِهِ فَقَالَ هَذِهِ فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ ثُمَّ قَامَ ‏ ‏أَبُو بَكْرٍ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏فَأَعْطَوْا فَأَعْطَى ثُمَّ قَامَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏فَأَعْطَوْا فَأَعْطَى ثُمَّ قَامَ ‏ ‏الْمُهَاجِرُونَ ‏ ‏فَأَعْطَوْا قَالَ فَأَشْرَقَ وَجْهُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى رَأَيْتُ الْإِشْرَاقَ فِي ‏ ‏وَجْنَتَيْهِ ‏ ‏ثُمَّ قَالَ ‏ ‏مَنْ سَنَّ سُنَّةً صَالِحَةً فِي الْإِسْلَامِ فَعُمِلَ بِهَا بَعْدَهُ كَانَ لَهُ مِثْلُ أُجُورِهِمْ مِنْ غَيْرِ أَنْ يُنْتَقَصَ مِنْ أُجُورِهِمْ شَيْءٌ وَمَنْ سَنَّ فِي الْإِسْلَامِ سُنَّةً سَيِّئَةً فَعُمِلَ بِهَا بَعْدَهُ كَانَ عَلَيْهِ مِثْلُ ‏ ‏أَوْزَارِهِمْ ‏ ‏مِنْ غَيْرِ أَنْ يُنْتَقَصَ مِنْ ‏ ‏أَوْزَارِهِمْ ‏ ‏شَيْءٌ ‏","","",""],[18388,18388,"","আমরা একজন অতিথিকে বলেছি আর এটা আমার বাবার ছেলে, আমরা এমনকি আহত হবার পরেও বেঁচে থাকার চেষ্টা করেছি। খোদা তাকে ঈশ্বরের দোহাই দিয়ে বলেছে, যুদ্ধ করো।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ زَكَرِيَّا وَهُوَ ابْنُ أَبِي زَائِدَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو حَيَّانَ التَّيْمِيُّ ‏ ‏عَنِ ‏ ‏الضَّحَّاكِ ‏ ‏خَالِ ‏ ‏الْمُنْذِرِ ‏ ‏عَنْ ‏ ‏مُنْذِرِ بْنِ جَرِيرٍ ‏ ‏عَنْ ‏ ‏جَرِيرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا يَأْوِي الضَّالَّةَ إِلَّا ضَالٌّ ‏","","",""],[18389,18389,"","আমরা কুমারী হওয়ার ব্যাপারে কথা বলেছি, বাবার ছেলের ব্যাপারে আমরা কথা বলেছি, সে তার উত্তরাধিকারীকে আগুনের এই ক্ষতিকরতা থেকে রক্ষা করতে চেয়েছিল আর তারপর সে একজন মানুষকে তার মুখ থেকে বের করে দেবে। তার কাছে প্রার্থনা কর এবং আত্মসমর্পণ করো।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ زَكَرِيَّا ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي خَالِدٍ ‏ ‏عَنْ ‏ ‏قَيْسٍ ‏ ‏عَنْ ‏ ‏جَرِيرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعَثَهُ إِلَى ‏ ‏ذِي الْخَلَصَةِ ‏ ‏فَكَسَرَهَا وَحَرَّقَهَا بِالنَّارِ ثُمَّ بَعَثَ رَجُلًا مِنْ ‏ ‏أَحْمَسَ ‏ ‏يُقَالُ لَهُ ‏ ‏بُشَيْرٌ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُبَشِّرُهُ ‏","","",""],[18390,18390,"","আমরা বাবার সাথে কথা বলেছিলাম, সে ছিল আমার বাবার ছেলে আর সে আমার বাবার ছেলে ছিল। সে তার কাছে ঈশ্বরের কাছে প্রার্থনা করলো আর সে তোমার কাছে আত্মসমর্পণ করবে। বেঁচে যাওয়া ভাই হয়তো মারা যেতে পারে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ وَهُوَ الزُّبَيْرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ وَهُوَ ابْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ أَخَاكُمْ ‏ ‏النَّجَاشِيَّ ‏ ‏قَدْ مَاتَ فَاسْتَغْفِرُوا لَهُ ‏","","",""],[18391,18391,"","আমরা একটি জীবন কাহিনী বলেছি, যা ঈশ্বর বলেছেন, তার কাছে একটা মই আছে লাঠিটিকে আটকে রাখার জন্য আর তার রোগ আছে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏دَاوُدُ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏عَنْ ‏ ‏جَرِيرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِيَصْدُرْ ‏ ‏الْمُصَدِّقُ وَهُوَ عَنْكُمْ رَاضٍ ‏","","",""],[18392,18392,"","আমরা একজন যাজককে বলেছিলাম যে সাহসী কিন্তু ঈশ্বর আমাকে বলেছেন। আমি কখনও এমন এক ছবিতে থেকে বের হতে দেব না যাকে বলা হয় \"ফাত্তার\"। আর ঈশ্বরের কাছে মানুষের মত হয়ে গেল, তোমার অনুসন্ধান তোমাকে ছেড়ে দিতে চাই... ... যেন সে তোমাকে তোমার দু:খ দিয়ে চলে যায়।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏قَيْسٍ ‏ ‏قَالَ قَالَ ‏ ‏جَرِيرُ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَا تُرِيحُنِي مِنْ ‏ ‏ذِي الْخَلَصَةِ ‏ ‏وَكَانَ بَيْتًا فِي ‏ ‏خَثْعَمَ ‏ ‏يُسَمَّى كَعْبَةَ الْيَمَانِيَةِ ‏ ‏فَنَفَرْتُ ‏ ‏إِلَيْهِ فِي سَبْعِينَ وَمِائَةِ فَارِسٍ مِنْ ‏ ‏أَحْمَسَ ‏ ‏قَالَ فَأَتَاهَا فَحَرَّقَهَا بِالنَّارِ وَبَعَثَ ‏ ‏جَرِيرٌ ‏ ‏بَشِيرًا إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ وَالَّذِي بَعَثَكَ بِالْحَقِّ مَا أَتَيْتُكَ حَتَّى تَرَكْتُهَا كَأَنَّهَا جَمَلٌ أَجْرَبُ فَبَرَّكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى خَيْلِ ‏ ‏أَحْمَسَ ‏ ‏وَرِجَالِهَا خَمْسَ مَرَّاتٍ ‏","","",""],[18393,18393,"","আমরা আমার বাবার এই দৃঢ় চিন্তার কথা বলেছি যে ঈশ্বর আমাকে বলেছেন, তার জন্য প্রার্থনা করেছেন এবং তিনি বলবেন কে মানুষকে সান্ত্বনা দেবে না। ঈশ্বর জিতে গেছেন এবং তিনি বিয়ে করেছেন।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْمَاعِيلُ بْنُ أَبِي خَالِدٍ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ أَبِي حَازِمٍ ‏ ‏قَالَ قَالَ ‏ ‏لِي ‏ ‏جَرِيرٌ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ لَا يَرْحَمْ النَّاسَ لَا يَرْحَمْهُ اللَّهُ عَزَّ وَجَلَّ ‏","","",""],[18394,18394,"","আমরা আমাদের আবেগ নিয়ে কথা বলেছি যা শুনে আমরা মন জয় করেছি, আমি শুনেছি একটি উদ্যোগী ভালবাসা। ঈশ্বরকে আমরা জিজ্ঞেস করেছি, তিনি কি জানেন এবং ঈশ্বর যেমন বলেছেন, তিনি যদি চাইতেন তাহলে তিনি তা করতেন আপনি তাকে দেখতে পান যে, আপনি তাকে ছেড়ে যেতে পারেন কি না এবং তাকে হতাশ করতে পারেন না ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَيْسَ بْنَ أَبِي حَازِمٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏جَرِيرٍ ‏ ‏قَالَ ‏ ‏كُنَّا عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْلَةَ الْبَدْرِ فَقَالَ إِنَّكُمْ ‏ ‏سَتَرَوْنَ رَبَّكُمْ عَزَّ وَجَلَّ كَمَا تَرَوْنَ الْقَمَرَ لَا ‏ ‏تُضَامُونَ ‏ ‏فِي رُؤْيَتِهِ فَإِنْ اسْتَطَعْتُمْ أَنْ لَا ‏ ‏تُغْلَبُوا ‏ ‏عَلَى هَاتَيْنِ الصَّلَاتَيْنِ قَبْلَ طُلُوعِ الشَّمْسِ وَقَبْلَ الْغُرُوبِ ثُمَّ تَلَا هَذِهِ الْآيَةَ فَ ‏ { ‏سَبِّحْ بِحَمْدِ رَبِّكَ قَبْلَ طُلُوعِ الشَّمْسِ وَقَبْلَ الْغُرُوبِ ‏} ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏لَا أَدْرِي قَالَ فَإِنْ اسْتَطَعْتُمْ أَوْ لَمْ يَقُلْ ‏","","",""],[18395,18395,"","আমি কথা বলেছি আমার কিছু বলার কথা শোনার চেষ্টা করে, ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং তার কাছে প্রার্থনা করেছেন এবং শিক্ষক ও সব শান্তির উপদেশের প্রতি","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَيْسًا ‏ ‏يُحَدِّثُ عَنْ ‏ ‏جَرِيرٍ ‏ ‏قَالَ ‏ ‏بَايَعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى إِقَامِ الصَّلَاةِ وَإِيتَاءِ الزَّكَاةِ وَالنُّصْحِ لِكُلِّ مُسْلِمٍ ‏","","",""],[18396,18396,"","ঈশ্বর তাকে তাঁর লোকেদের কাছ থেকে আদেশ দিয়েছেন এবং যারা তাঁর সর্বোচ্চ কাজ করবে তাদের কাছ থেকে নিজেকে আত্মসমর্পণ করতে আদেশ দিয়েছেন । তবে তারা যে ভাবে কথা বলেছে এবং বলছে, তারা ধরা পড়েছে।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجُ بْنُ مُحَمَّدٍ ‏ ‏أَخْبَرَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْمُنْذِرِ بْنِ جَرِيرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْ قَوْمٍ يَعْمَلُونَ بِالْمَعَاصِي وَفِيهِمْ رَجُلٌ أَعَزُّ مِنْهُمْ وَأَمْنَعُ لَا يُغَيِّرُونَ إِلَّا عَمَّهُمْ اللَّهُ عَزَّ وَجَلَّ بِعِقَابٍ ‏ ‏أَوْ قَالَ أَصَابَهُمْ الْعِقَابُ ‏","","",""],[18397,18397,"","আমরা একটা দাঙ্গার কথা বলছি যেখানে গান বলা হয়, তার ক্যাপ্টেন তোমার বন্ধু আর তার আত্মা ধ্বংস হয়ে যাবে. ঈশ্বরের ক্ষমার জন্য আমাকে ক্ষমা করবেন, ঈশ্বর আমার সাথে আমার বাবার সাথে খেলেন না।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ عِلَاقَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏جَرِيرًا ‏ ‏يَقُولُ ‏ ‏حِينَ مَاتَ ‏ ‏الْمُغِيرَةُ ‏ ‏وَاسْتَعْمَلَ قَرَابَتَهُ يَخْطُبُ فَقَامَ ‏ ‏جَرِيرٌ ‏ ‏فَقَالَ أُوصِيكُمْ بِتَقْوَى اللَّهِ وَحْدَهُ لَا شَرِيكَ لَهُ وَأَنْ تَسْمَعُوا وَتُطِيعُوا حَتَّى يَأْتِيَكُمْ أَمِيرٌ اسْتَغْفِرُوا ‏ ‏لِلْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏غَفَرَ اللَّهُ تَعَالَى لَهُ فَإِنَّهُ كَانَ يُحِبُّ ‏ ‏الْعَافِيَةَ ‏ ‏أَمَّا بَعْدُ فَإِنِّي أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُبَايِعُهُ بِيَدِي هَذِهِ عَلَى الْإِسْلَامِ ‏ ‏فَاشْتَرَطَ عَلَيَّ النُّصْحَ فَوَرَبِّ هَذَا الْمَسْجِدِ إِنِّي لَكُمْ لَنَاصِحٌ ‏","","",""],[18398,18398,"","আমরা খালি পায়ের কথা বলেছি, বাবা মুছে যাওয়ার কথা শুনে আমি কিছু কৌশল করেছি। আরলিন বলেছিল যে তারা ধরা পড়েছে বা নির্ভীকভাবে দুঃখিত। ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং তিনি আত্মসমর্পণ করবেন বলে আমরা বলেছিলাম যে, তারা থেমে গিয়েছিল এবং আনন্দ করেছিল ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا إِسْحَاقَ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏جَرِيرُ بْنُ عَبْدِ اللَّهِ ‏ ‏فِي بَعْثٍ ‏ ‏بِأَرْمِينِيَّةَ ‏ ‏قَالَ فَأَصَابَتْهُمْ ‏ ‏مَخْمَصَةٌ ‏ ‏أَوْ مَجَاعَةٌ ‏ ‏قَالَ فَكَتَبَ ‏ ‏جَرِيرٌ ‏ ‏إِلَى ‏ ‏مُعَاوِيَةَ ‏ ‏إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ لَمْ يَرْحَمْ النَّاسَ لَا يَرْحَمْهُ اللَّهُ عَزَّ وَجَلَّ قَالَ فَأَرْسَلَ إِلَيْهِ فَأَتَاهُ فَقَالَ ‏ ‏آنْتَ سَمِعْتَهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ نَعَمْ قَالَ ‏ ‏فَأَقْفَلَهُمْ ‏ ‏وَمَتَّعَهُمْ ‏ ‏قَالَ ‏ ‏أَبُو إِسْحَاقَ ‏ ‏وَكَانَ أَبِي فِي ذَلِكَ الْجَيْشِ فَجَاءَ بِقَطِيفَةٍ مِمَّا مَتَّعَهُ ‏ ‏مُعَاوِيَةُ ‏","","",""],[18399,18399,"","আমরা পরের যে বিষয়গুলো বলেছিলাম, তা নিয়ে আমরা কথা বলেছিলাম, পরের জন বলেছিলেন যে আমি ঈশ্বরকে পাঠিয়েছি, তিনি বলেছিলেন যে শান্তি আছে আর তিনি তা করবেন। যখন পারবে আর পারবে তখন বলেছিল সব ঠিক করতে পারবে.","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏قَالَ ثَنَا ‏ ‏سَيَّارٌ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏قَالَ ‏ ‏بَايَعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى السَّمْعِ وَالطَّاعَةِ فَقَالَ ‏ ‏فَلَقَّنِّي فَقَالَ فِيمَا اسْتَطَعْتَ وَالنُّصْحَ لِكُلِّ مُسْلِمٍ ‏","","",""],[18400,18400,"","আমি ঈশ্বরকে প্রার্থনা করতে দেখেছি এবং তিনি যেমন ছিলেন, তেমনই তাঁর শ্রেষ্ঠত্ব জানতে সক্ষম হবেন ।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي زُرْعَةَ بْنِ عُمَرٍو ‏ ‏عَنْ ‏ ‏جَرِيرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَفْتِلُ ‏ ‏عُرْفَ فَرَسٍ بِأُصْبُعَيْهِ وَهُوَ يَقُولُ ‏ ‏الْخَيْلُ مَعْقُودٌ بِنَوَاصِيهَا الْخَيْرُ الْأَجْرُ وَالْمَغْنَمُ إِلَى يَوْمِ الْقِيَامَةِ ‏","","",""]];
